COLLDATA("tafsirnoor","ur",[[850,"§امام الہند مولانا ابو الکلام آزاد رحمہ اللہ کا یہود کی ذلت پر بے لاگ تبصرہ\nمولانا ابو الکلام آزاد رحمہ اللہ رقم طراز ہیں : ’’دعوت حق کی مخالفت میں سب سے زیادہ حصہ یہودیوں کا ہے ان لوگوں کا حال یہ ہے کہ اپنی بدعملیوں اور سرکشیوں سے مغضوب الٰہی ہو چکے ہیں اور دنیا کا کوئی گوشہ نہیں جہاں اپنے بل بوتے پر زندگی بسر کر رہے ہوں جہاں کہیں بھی پناہ ملی ہےذلت ونامرادی کی پناہ ہے،یعنی یا تو اہل کتاب ہونے کی وجہ سے لوگوں نے چھوڑ رکھا ہے یا پھر حکمران قوموں نے محکومیت واطاعت کے قول و قرار پر زندگی کی مہلت دے دی ہے چنانچہ پہلی حالت عرب میں تھی دوسری روم اور ایران میں پس کوئی وجہ نہیں کہ تم ان کی مخالفت سے پریشان خاطر ہو وہ وقت دور نہیں جب عرب میں ان کی رہی سہی طاقت کا بھی خاتمہ ہو جائے گا۔ یہاں سے یہ حقیقت بھی واضح ہو گئی کہ قرآن قومی محکومیت کی حالت کو کس نظر سے دیکھتا ہے اس زمانہ میں یہودی رومیوں کے ماتحت زندگی بسر کر رہے تھے اور عرب میں بھی ان کی بڑی بڑی بستیاں تھیں لیکن چونکہ حکومت وفرماں روائی سے محروم ہو چکے تھے اس لیے فرمایا: کہ یہ دوسروں کے رحم پر زندگی بسر کرنے والے ہیں۔ (تفسیر ترجمان القرآن : 335/1)\n﴿لَيْسُوْا سَوَآءًؕ مِنْ اَهْلِ الْكِتٰبِ اُمَّةٌ قَآىِٕمَةٌ يَّتْلُوْنَ اٰيٰتِ اللّٰهِ اٰنَآءَ الَّيْلِ وَهُمْ يَسْجُدُوْنَ۰۰۱۱۳ يُؤْمِنُوْنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَيَاْمُرُوْنَ بِالْمَعْرُوْفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُسَارِعُوْنَ فِي الْخَيْرٰتِؕ وَاُولٰٓىِٕكَ مِنَ الصّٰلِحِيْنَ۰۰۱۱۴ وَمَا يَفْعَلُوْا مِنْ خَيْرٍ فَلَنْ يُّكْفَرُوْهُؕ وَاللّٰهُ عَلِيْمٌۢ بِالْمُتَّقِيْنَ۠۰۰۱۱۵ اِنَّ الَّذِيْنَ كَفَرُوْا لَنْ تُغْنِيَ عَنْهُمْ اَمْوَالُهُمْ وَلَاۤ اَوْلَادُهُمْ مِّنَ اللّٰهِ شَيْـًٔاؕ وَاُولٰٓىِٕكَ اَصْحٰبُ النَّارِۚ هُمْ فِيْهَا خٰلِدُوْنَ۰۰۱۱۶ مَثَلُ مَا يُنْفِقُوْنَ فِيْ هٰذِهِ الْحَيٰوةِ الدُّنْيَا كَمَثَلِ رِيْحٍ فِيْهَا صِرٌّ اَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوْۤا اَنْفُسَهُمْ فَاَهْلَكَتْهُؕ وَمَا ظَلَمَهُمُ اللّٰهُ وَلٰكِنْ اَنْفُسَهُمْ يَظْلِمُوْنَ۰۰۱۱۷﴾\nوہ سب برابر نہیں ہیں، اہل کتاب میں سے ایک گروہ حق پر قائم ہے، وہ رات کی گھڑیوں میں اللہ کی آیتیں تلاوت کرتے ہیں، اور وہ سجدہ کرتے ہیں وہ اللہ اور یوم آخرت پر ایمان رکھتے ہیں اور وہ نیکی کا حکم دیتے اور وہ برائی سے روکتے ہیں اور وہ بھلائی کے کاموں میں سبقت کرتے ہیں اور وہی نیکو کاروں میں سے ہیں\nاور وہ جو بھی بھلائی کریں گے اس کی نا قدری نہیں کی جائے گی، اور اللہ پرہیز گاروں کو خوب جانتا ہے\nبے شک جن لوگوں نے کفر کیا، انہیں ان کے مال اور ان کی اولاد اللہ (کے عذاب) سے ذرا بھی چھڑا نہ سکیں گے اور وہی دوزخ والے ہیں۔ وہ اس میں ہمیشہ رہیں گے\n(کافر) اس دنیا میں جو کچھ خرچ کرتے ہیں، اس کی مثال ایسی آندھی کی سی ہے جس میں سخت پالا ہو، وہ ان لوگوں کی کھیتی پر چلے جنہوں نے اپنی جانوں پر ظلم\nکیا، تو وہ اسے تباہ کر ڈالے۔ اور اللہ نے ان پر ظلم نہیں کیا بلکہ وہ خود اپنی جانوں پر ظلم کرتے تھے"],[851,"§اہل کتاب میں سے اسلام قبول کرنے والوں کی فضیلت\nمحمد بن اسحاق رحمہ اللہ وغیرہ نے حضرت ابن عباس رضی اللہ عنہما سے روایت کی ہے کہ یہ آیات یہود کے ان علماء کے بارے میں نازل ہوئی ہیں جو ایمان لے آئے تھے، مثلاً : سیدنا عبداللہ بن سلام، اسد بن عبید، ثعلبہ بن سعیہ اور اسید بن سعیہ رضی اللہ عنہم وغیرہ۔(تفسیر الطبری : 71/4) یعنی اہل کتاب میں سے وہ لوگ جن کی قبل ازیں مذمت بیان کی گئی ہے، وہ اور ان میں سے مشرف بہ اسلام ہونے والے برابر نہیں ہو سکتے کیونکہ ان میں سے مومن بھی ہیں اور مجرم بھی۔ اسی لیے فرمایا: ﴿مِنْ اَهْلِ الْكِتٰبِ اُمَّةٌ قَآىِٕمَةٌ﴾ یعنی ان اہل کتاب میں کچھ لوگ اللہ تعالیٰ کے حکم پر قائم ہیں، اس کی شریعت کے مطیع ہیں اور اس کے نبی علیہ السلام کے متبع ہیں تو یہ لوگ حق پر قائم اور مستقیم ہیں۔ ﴿يَّتْلُوْنَ اٰيٰتِ اللّٰهِ اٰنَآءَ الَّيْلِ وَهُمْ يَسْجُدُوْنَ۰۰۱۱۳﴾ ’’وہ رات کی گھڑیوں میں اللہ تعالیٰ کی آیات کی تلاوت کرتے ہیں اور وہ سجدہ کرتے ہیں۔‘‘ یعنی رات کو قیام کرتے، کثرت سے نماز تہجد پڑھتے اور نمازوں میں قرآن مجید کی تلاوت کرتے ہیں۔ ﴿يُؤْمِنُوْنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَيَاْمُرُوْنَ بِالْمَعْرُوْفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُسَارِعُوْنَ فِي الْخَيْرٰتِؕ وَاُولٰٓىِٕكَ مِنَ الصّٰلِحِيْنَ۰۰۱۱۴﴾ ’’(اور) اللہ پر اور روزِ آخرت پر ایمان رکھتے اور اچھے کام کرنے کو کہتے اور بُری باتوں سے منع کرتے اور نیکیوں پر لپکتے ہیں اور یہی لوگ نیکوکار ہیں۔‘‘ اور انہی لوگوں کا اسی سورۂ مبارکہ کے آخر میں ذکر کرتے ہوئے فرمایا: ﴿وَاِنَّ مِنْ اَهْلِ الْكِتٰبِ لَمَنْ يُّؤْمِنُ بِاللّٰهِ وَمَاۤ اُنْزِلَ اِلَيْكُمْ وَمَاۤ اُنْزِلَ اِلَيْهِمْ خٰشِعِيْنَ لِلّٰهِۙ لَا يَشْتَرُوْنَ بِاٰيٰتِ اللّٰهِ ثَمَنًا قَلِيْلًاؕ اُولٰٓىِٕكَ لَهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْؕ اِنَّ اللّٰهَ سَرِيْعُ الْحِسَابِ۰۰۱۹۹﴾ (آل عمران:199) ’’اور بعض اہل کتاب ایسے بھی ہیں جو اللہ تعالیٰ پر اور اس (کتاب) پر جو تم پر نازل ہوئی اور اس پر جو اُن پر نازل ہوئی ایمان رکھتے ہیں اور اللہ تعالیٰ کے آگے عاجزی کرتے ہیں وہ اللہ تعالیٰ کی آیتیں تھوڑی قیمت میں نہیں بیچتے وہی ہیں جن کا اجر ان کے رب کے پاس ہے بے شک اللہ جلد حساب لینے والا ہے۔‘‘ اسی طرح یہاں بیان فرمایا: ﴿وَمَا يَفْعَلُوْا مِنْ خَيْرٍ فَلَنْ يُّكْفَرُوْهُؕ﴾ ’’اور یہ جس طرح کی نیکی بھی کریں گے تو اس کی ناقدری نہیں کی جائے گی۔ ‘‘ یعنی وہ اللہ تعالیٰ کے ہاں ضائع نہیں ہوگی بلکہ اللہ تعالیٰ اس کی پوری پوری جزا عطا فرمائے گا۔ ﴿وَاللّٰهُ عَلِيْمٌۢ بِالْمُتَّقِيْنَ۠۰۰۱۱۵﴾ ’’اور اللہ تعالیٰ پرہیز گاروں کو خوب جانتا ہے۔‘‘ یعنی اس سے کسی بھی عمل کرنے والے کا عمل مخفی نہیں ہے اور نہ کسی اچھے عمل کرنے والے کے عمل کا اجر ضائع ہو سکتا ہے۔\nپھر اللہ تعالیٰ نے کافروں اور مشرکوں کے بارے میں خبر دیتے ہوئے فرمایا ہے : ﴿لَنْ تُغْنِيَ عَنْهُمْ اَمْوَالُهُمْ وَلَاۤ اَوْلَادُهُمْ مِّنَ اللّٰهِ شَيْـًٔاؕ﴾ یعنی جب اللہ تعالیٰ انہیں سزا دینے کا ارادہ فرمائے گا تو ان کے مال اور اولاد اللہ تعالیٰ کی سزا یا اس کے عذاب کو ان سے ہر گز دور نہیں کر سکیں گے۔ ﴿وَاُولٰٓىِٕكَ اَصْحٰبُ النَّارِۚ هُمْ فِيْهَا خٰلِدُوْنَ۰۰۱۱۶﴾ ’’اور وہی لوگ اہل دوزخ ہیں کہ ہمیشہ اسی میں رہیں گے۔ ‘‘"],[852,"§کفار جو خرچ کرتے ہیں اس کی مثال\nپھر اللہ تعالیٰ نے اس کے لیے ایک مثال بیان فرمائی ہے جو کفار دنیا کی اس زندگی میں خرچ کرتے ہیں، یہ امام مجاہد، حسن اور سُدی رحمہم اللہ کا قول ہے۔ (تفسیر ابن أبی حاتم : 741/3)\nپس اللہ تعالیٰ نے فرمایا ہے : ﴿مَثَلُ مَا يُنْفِقُوْنَ فِيْ هٰذِهِ الْحَيٰوةِ الدُّنْيَا كَمَثَلِ رِيْحٍ فِيْهَا صِرٌّ﴾ ’’یہ جو مال دنیا کی زندگی میں خرچ کرتے ہیں اس کی مثال ہوا کی سی ہے جس میں سخت سردی ہو۔‘‘ (صِرٌّ) کے معنی سخت سردی کے ہیں، یہ حضرت ابن عباس رضی اللہ عنہما، عکرمہ، سعید بن جبیر، حسن، قتادہ، ضحاک، ربیع بن انس رحمہم اللہ اور دیگر کئی ائمہ تفسیر کا قول ہے۔(تفسیر ابن أبی حاتم : 741/3) عطا نے اس کے معنی سردی اور کہر کے بیان کیے ہیں۔(تفسیر ابن أبی حاتم : 741/3) حضرت ابن عباس رضی اللہ عنہما اور مجاہد سے یہ بھی مروی ہے کہ اس کے معنی آگ کے ہیں۔(تفسیر ابن أبی حاتم : 741/3) یہ معنی بھی پہلے ہی کی طرف راجع ہے کیونکہ سخت سردی خصوصًا کہراور ژالہ باری بھی فصلوں اور پھلوں کو اسی طرح جلا دیتی ہے جس طرح آگ سے کسی چیز کو جلا دیاجاتا ہے۔\nارشاد باری تعالیٰ ہے : ﴿اَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوْۤا اَنْفُسَهُمْ فَاَهْلَكَتْهُؕ﴾ ’’وہ ایسے لوگوں کی کھیتی پر جو اپنے آپ پر ظلم کرتے تھے، چلے پھر اسے تباہ کر دے۔ ‘‘ یعنی اسے جلا دے، اس سے مراد آگ کا وہ بگولا ہے کہ جب وہ کسی ایسی کھیتی کو اپنی لپیٹ میں لیتا ہے جس کے پکنے اور کٹنے کا وقت قریب آگیا ہو تو اسے تباہ و برباد کر کے رکھ دیتا ہے اور اس کی فصل اور پھل خراب ہو کر تہس نہس ہوجاتے ہیں، اور کھیتی کامالک اپنے پھل اور فصل سے اس وقت محروم ہوجاتاہے جب اسے اس کی بہت ضرورت تھی۔\nاسی طرح اللہ تعالیٰ کافروں کے اعمال کے ثواب کو اسی دنیا ہی میں ختم کر دیتا ہے جس طرح اس کھیتی کے پھل کو اس کے مالک کے گناہوں کی وجہ سے تباہ و برباد کر دیتا ہے اسی طرح یہ لوگ ہیں کہ جنہوں نے کسی اصل اور اساس کے بغیر ہی اپنے کاموں کی بنیاد رکھی ہے۔ ﴿وَمَا ظَلَمَهُمُ اللّٰهُ وَلٰكِنْ اَنْفُسَهُمْ يَظْلِمُوْنَ۰۰۱۱۷﴾ ’’اور اللہ تعالیٰ نے ان پر کچھ ظلم نہیں کیا بلکہ یہ خود اپنے اوپر ظلم کر رہے ہیں۔ ‘‘\n﴿وَمَا يَفْعَلُوْا مِنْ خَيْرٍ﴾ ’’اور جو کچھ بھی بھلائیاں کریں‘‘ تھوڑی ہوں یا زیادہ ﴿فَلَنْ يُّكْفَرُوْهُؕ﴾ ’’ان کی ناقدری نہیں کی جائے گی‘‘ انہیں ان کے ثواب سے محروم نہیں رکھا جائے گا، بلکہ اللہ تعالیٰ انہیں ان اعمال کا مکمل ترین ثواب دے گا۔ لیکن ایمان کے ثواب کا دارومدار عمل کرنے والے کے دل میں موجود ایمان و تقویٰ پر ہوتا ہے۔ اس لیے فرمایا: ﴿وَاللّٰهُ عَلِيْمٌۢ بِالْمُتَّقِيْنَ۠۰۰۱۱۵﴾ ’’اور اللہ پرہیزگاروں کو خوب جانتا ہے‘‘ جیسے دوسرے مقام پر فرمایا ہے: ﴿اِنَّمَا يَتَقَبَّلُ اللّٰهُ مِنَ الْمُتَّقِيْنَ۰۰۲۷﴾ (المائدہ : 27) ’’اللہ صرف پرہیزگاروں کی قربانی قبول کرتا ہے۔‘‘\nاللہ تعالیٰ بیان فرماتا ہے: کہ کافروں کو ان کے مال اور ان کی اولاد اللہ کے ہاں کچھ کام نہ آئیں گی۔ یعنی اللہ کےعذاب سے بچانے میں یا اللہ سے ثواب کے حصول میں معمولی سا بھی فائدہ نہیں دیں گی۔ جیسے فرمان الٰہی ہے: ﴿وَمَاۤ اَمْوَالُكُمْ وَلَاۤ اَوْلَادُكُمْ بِالَّتِيْ تُقَرِّبُكُمْ عِنْدَنَا زُلْفٰۤى اِلَّا مَنْ اٰمَنَ وَعَمِلَ صَالِحًا١ٞ﴾ (سبائ : 34) ’’یہ تمہارے مال اور تمہاری اولادیں ایسی نہیں کہ جو تمہیں ہمارا قرب بخش سکیں، لیکن جو ایمان لایا اور اس نے نیک عمل کیے (اسے قرب حاصل ہوگا)‘‘ بلکہ ان کے مال و اولاد جہنم کی طرف سفر میں ان کا زادراہ ہیں۔ اللہ کی نعمتوں میں اضافے کا تقاضا یہ ہے کہ ان کا شکر ادا کیا جائے، لیکن ان کے لیے یہ چیزیں شکر نہ کرنے کی وجہ سےان کے خلاف حجت ہوں گی، اس لیے ان پر شکر نہ کرنے اورناشکری کی پاداش میں انہیں سزا دی جائے گی۔ اس لیے فرمایا: ﴿وَاُولٰٓىِٕكَ اَصْحٰبُ النَّارِۚ هُمْ فِيْهَا خٰلِدُوْنَ۰۰۱۱۶﴾ ’’یہ تو جہنمی ہیں، جو ہمیشہ اس میں پڑے رہیں گے۔‘‘\nپھر اللہ نے کافروں کے مال خرچ کرنے کے بارے میں ایک مثال بیان فرمائی، کہ وہ لوگ مال خرچ کر کے اللہ کے نور کو بجھانے کی کوشش کرتے ہیں اور لوگوں کو اللہ کی راہ سے روکتے ہیں، تویہ کوششیں ناکام رہیں گی، جیسے کوئی شخص فصل بوئے اس سے اس کا نتیجہ ملنے اوراس سے پیداوار حاصل ہونے کی امید ہو، اچانک کھیتی پر ایک سخت ٹھنڈی ہوا چلے، جس سے کھیتی تباہ ہوجائے۔ اس کے حصے میں صرف محنت، مشقت اور حسرت و افسوس ہی آئے۔ کافروں کا بھی یہی حال ہے۔ جیسے اللہ تعالیٰ نے دوسرے مقام پر فرمایا: ﴿اِنَّ الَّذِيْنَ كَفَرُوْا يُنْفِقُوْنَ اَمْوَالَهُمْ لِيَصُدُّوْا عَنْ سَبِيْلِ اللّٰهِؕ فَسَيُنْفِقُوْنَهَا ثُمَّ تَكُوْنُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُوْنَ࣢ؕ﴾ (الانفال : 36) ’’بے شک کافر اپنے مال اللہ کی راہ سے روکنے کے لیے خرچ کرتے ہیں، یہ خرچ کریں گے، پھر یہ ان کے لیے حسرت کا باعث بن جائیں گے، پھریہ مغلوب ہوجائیں گے۔‘‘ اللہ تعالیٰ فرماتا ہے: ﴿وَمَا ظَلَمَهُمُ اللّٰهُ﴾ ’’اللہ نے ان پر ظلم نہیں کیا۔‘‘ کہ ان کے عمل ضائع کر دئیے۔ ﴿وَلٰكِنْ اَنْفُسَهُمْ يَظْلِمُوْنَ۰۰۱۱۷﴾ ’’بلکہ وہ خود اپنی جانوں پر ظلم کرتے تھے۔‘‘ وہ اس طرح کہ انہوں نےاللہ کی آیتوں کا انکار کیا، اس کےر سولوں کو جھٹلایا اور اللہ کے نور کو بجھانے کی کوشش کی۔ ان بد اعمالیوں کی وجہ سے ان کی نیکیاں ضائع ہوگئیںاور مال تباہ ہوگئے۔\nاس آیت کا پس منظر بیان کرتے ہوئے ابن جریر، ابن المنذر، ابن ابی حاتم، طبرانی رحمہ اللہ اور دیگر کئی محدثین نے ابن عباس رضی اللہ عنہا کا یہ قول نقل کیا ہے کہ جب عبداللہ بن سلام، ثعلبہ بن سعید، اسید بن سعید، اسید بن عبید رضی اللہ عنہم اور کچھ دوسرے یہودیوں نے اسلام قبول کر لیا، تو علماء یہود کہنے لگے کہ محمد صلی اللہ علیہ وسلم پر برے لوگ ایمان لائے ہیں، اگر وہ اچھے ہوتے تو اپنے باپ دادا کا دین نہ چھوڑتے اور ان مسلمانوں سے مخاطب ہو کر کہا کہ تم لوگوں نے اپنا دین بدل کر خسارہ اٹھایا ہے۔ اس وقت یہ آیت کریمہ نازل ہوئی کہ وہ اہل کتاب جنہوں نے دین اسلام کو قبول کر لیا، ان اہل کتاب کی مانند نہیں جو اپنے کفر پر قائم رہے۔\nامام احمد اور نسائی رحمہم اللہ وغیرہما نے عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ہے کہ ایک رات رسول اللہ صلی اللہ علیہ وسلم عشاء کی نمازکے لیے بہت تاخیر سے تشریف لائے،ا ورفرمایا: کہ اہل ادیان میں سے تمہارے علاوہ کوئی نہیں جو اس وقت اللہ کو یاد کر رہا ہو۔ تو لَيْسُوا سَوَائً سے بِالْمُتَّقِينَ تک تین آیتیں نازل ہوئیں۔\nاس روایت کے مطابق بھی آیت کا مفہوم بھی یہی ہوگا کہ اہل کتاب میں سے جو لوگ رسول اللہ صلی اللہ علیہ وسلم پر ایمان لائے اور جن کی صفات وہ ہیں جو یہاں بیان کی گئی ہیں، وہ لوگ ان اہل کتاب کی مانند نہیں ہیں،جنہوں نے کفر کی راہ اختیار کی۔"],[853,"§اہل کتاب میں منصف مزاج آدمی\nپہلے اللہ تعالیٰ نے یہ بتایا تھا کہ اہل کتاب کی اکثریت فسق و فجور پر ہی مصر رہی۔ اس آیت میں یہ بتایا جا رہا ہے کہ وہ سب کے سب ہی برے نہیں۔ ان میں بھی کچھ اچھے لوگ موجود ہیں جو ایمان لے آئے ہیں۔ مثلاً عبداللہ بن سلام رضی اللہ عنہ اور ان کے ساتھی یا نجاشی شاہ حبشہ وغیرہ اور ان میں وہ سب خوبیاں موجود ہیں جو نیکوکار مسلمانوں میں ہوتی ہیں۔ عبداللہ بن سلام یہود کے ممتاز علماء میں سے تھے۔ لیکن مفاد پرست اور جاہ طلب ہونے کی بجائے حق والے تھے۔"],[854,"§عبداللہ بن سلام کا تعارف اور اسلام لانا\nجب آپ صلی اللہ علیہ وسلم ہجرت کرکے مدینہ تشریف لائے اور عبداللہ بن سلام رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم میں وہ نشانیاں دیکھیں جو تورات میں نبی آخر الزمان کی بتائی گئی تھیں تو آپ فوراً خدمت اقدس میں حاضر ہوئے اور چند سوالات پوچھنے کے بعد اسلام لےآئے۔ پھر آپ ہی نے رسول اللہ صلی اللہ علیہ وسلم کو یہود کی سرشت سے آگاہ کیا۔ چنانچہ یہود ان کے دشمن بن گئے۔ پھر جب ایک زنا کے مقدمہ میں یہود نے تورات سے رجم کی آیت کو چھپانا چاہا تو عبداللہ بن سلام رضی اللہ عنہ نے ہی اس آیت کی نشاندہی کرکے یہود کو نادم اور رسوا کیا۔ عبداللہ بن سلام رضی اللہ عنہ کو ایک خواب آیا تھا جس کی تعبیر رسول اللہ صلی اللہ علیہ وسلم نے یہ بتائی کہ عبداللہ بن سلام رضی اللہ عنہ آخری دم تک اسلام پر ثابت قدم رہیں گے۔ چنانچہ بعض صحابہ انھیں جنتی کہا کرتے تھے۔"],[855,"§نجاشی شاہ حبشہ کا کردار اور اس کا اسلام لانا\nنجاشی شاہ حبشہ جس کا نام اصحمہ تھا، نے مسلمانوں کی اس وقت بھرپور حمایت کی جب مسلمان ہجرت کرکے حبشہ پہنچے اور قریش مکہ کا ایک وفد انھیں واپس لانے کے لیے شاہ حبشہ کی خدمت میں حاضر ہوا تھا۔ شاہ نے نہ صرف یہ کہ مسلمانوں کو واپس نہیں کیا اور انھیں پناہدی بلکہ برملا اعتراف کیا کہ سیدنا عیسیٰ اور مریم علیہما السلام کےمعاملہ میں مسلمانوں کے عقائد بالکل درست اور عیسیٰ علیہ السلام کی تعلیمات کے عین مطابق ہیں پھر مسلمانوں سے بہتر سے بہتر سلوک کیا۔ اس کے باقاعدہ اسلام لانے کی تفصیل تو نہیں ملتی تاہم جب وہ فوت ہوا تو آپ صلی اللہ علیہ وسلم نے مسلمانوں کو اس کی وفات پر مطلع کرکے فرمایا کہ اپنے مسلمان بھائی کی نماز جنازہ پڑھو۔ چنانچہ اس کی غائبانہ نماز جنازہ پڑھی گئی۔(بخاری، کتاب الجنائز، باب الصفوف علی الجنازۃ...) اس سے معلوم ہوتا ہے کہ وہ فی الحقیقت اسلام لا چکا تھا۔"],[856,"§اسلام لانے سے سابقہ گناہ معاف مگر نیک کاموں کا اجر ملے گا\nیعنی اہل کتاب کے منصف مزاج لوگ جو اسلام لے آئے ہیں۔ ان کے اسلام لانے سے پہلے کے اچھے کاموں کا انھیں بدلہ دیا جائے گا۔ کیونکہ اسلام لانے کے دو فائدے ہیں اور وہ احادیث صحیحہ سے ثابت ہیں۔ ایک یہ کہ اسلام لانے سے پہلے کے گناہ معاف کر دیے جاتے ہیں دوسرا یہ کہ اسلام لانے سے پہلے نیک اعمال برقرار رکھے جاتے ہیں، یعنی دور کفر کے اچھے کاموں کا بھی انھیں ثواب عطا کیاجائے گا۔ اور کافروں کا معاملہ اس کے برعکس ہوتاہے۔ یعنی ان کی نیکیاں برباد اور گناہ لازم ہوتے ہیں۔"],[857,"§یہ دنیا دارالعمل ہے اور آخرت دار الجزاء ہے\nاس دنیا میں انسان جو کچھ بوئے گا وہ عالم آخرت میں کاٹے گا۔ مگر دنیا میں بوئی ہوئی کھیتی کی بار آوری کے لیے چند شرائط ہیں۔ ان شرائط کو اگر ملحوظ نہ رکھا جائے تو کھیتی کبھی بار آور نہ ہوگی اور وہ شرائط ہیں۔ اللہ اور روزِ آخرت پر ایمان، خلوص نیت یعنی اس میں ریاکار شائبہ تک نہ ہو اور جو کام کیاجائے خالص اللہ کی رضا مندی کے لیے کیا جائے اور تیسرے اتباع کتاب و سنت یعنی وہ کام یا صدقہ و خیرات جو شریعت کی بتائی ہوئی ہدایت کے مطابق کیاجائے۔ ان میں سے اگر کوئی چیز بھی مفقود ہوگی تو آخرت میں کچھ بھی حاصل نہ ہوگا۔"],[858,"§کافروں کے نیک اعمال بھی برباد کیوں ہوتے ہیں؟\nاس آیت میں جن کافروں کے متعلق کہا گیا ہے کہ انھوں نے خود اپنے آپ پر ظلم کیاہے۔ ان میں یہ تینوں شرائط ہی مفقود ہوتی ہیں۔ کافر تو وہ کہلاتے ہی اس لیے ہیں کہ اللہ اور آخرت کے دن پر ایمان نہیں رکھتے اور یہی اپنے آپ پر سب سے بڑا ظلم ہوتاہے یا اگر اپنے خیال کے مطابق ایمان رکھتے بھی ہیں تو وہ اللہ کے ہاں مقبول نہیں اور چونکہ ان کا روزِ آخرت پر ایمان نہیں ہوتا۔ لہٰذا وہ جو بھی خرچ کریں گے وہ محض نمائش اور اپنی واہ واہ کے لیے کریں گے اور شریعت محمدیہ کی ہدایات کی اتباع کا یہاں سوال ہی پیدا نہیں ہوتا۔ تو پھر آخرت میں بھلا انھیں ایسے اعمال کا کیا بدلہ مل سکتا ہے۔ ان کے نیک اعمال کی کھیتی کو ان کے کفر کے کہر نے تباہ و برباد کرکے رکھ دیا تو اب آخرت میں انھیں کیا بدلہ ملے گا؟\nسورہ بقرہ کی آیت نمبر 263میں لوگوں کے دکھاوے کی خاطر خرچ کرنے والے کی یہ مثال بیان کی گئی کہ جیسے ایک صاف چکنے پتھر پر تھوڑی سی مٹی پڑی ہو اور اس مٹی میں کوئی شخص بیج بودے،پھر زور کی بارش آئے تو دانہ اور مٹی ہر چیز کو بہا کر لے جائے اور صاف چکنا پتھر باقی رہ جائے اور یہاں یہ مثال بیان کی گئی ہے کہ کھیتی تو اُگ آئی مگر اس پر ایسی شدید ٹھنڈی ہوا چلی جس نے اس کھیتی کو بھسم کرکے رکھ دیا۔ ماحصل دونوں مثالوں کا ایک ہی ہے کہ ایسے کافروں اور ریاکاروں کو آخرت میں ان کے صدقہ و خیرات کا کچھ بھی اجر نہیں ملے گا۔ کیونکہ ان کی کھیتی تو دنیا میں ہی تباہ برباد ہو چکی اور جو کام انھوں نے آخرت کے لیے کیا ہی نہ تھا اس کی انھیں جزا کیسے مل سکتی ہے؟\nعبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں اہل کتاب اور اُمت محمدیہ برابر نہیں ہیں رسول اکرم صلی اللہ علیہ وسلم نے ایک روز عشاء کی نماز کی ادائیگی میں تاخیر فرمائی بعد ازاں آپ صلی اللہ علیہ وسلم نے مسجد نبوی کا رخ کیا تو لوگ جماعت کے انتظار میں تھے آپ صلی اللہ علیہ وسلم نے فرمایا خبردار! اہل اسلام میں سے کوئی فرد ایسا نہیں ہے جو اس نماز کو اتنی تاخیر سے ادا کر رہا ہو جتنی تاخیر سے تم ادا کر رہے ہو۔‘‘\nاس کے بعد ان تین آیات کا نزول ہوا جب کہ مفسرین کے نزدیک مشہور یہ ہے ابن عباس رضی اللہ عنہما بیان فرماتے ہیں کہ یہ تینوں آیات اہل کتاب سے علماء کرام کے بارے میں نازل ہوئیں جن کے اسماء یہ ہیں عبداللہ بن سلام، اسد بن عبید، ثعلبہ بن سعید وغیرہ مقصود یہ ہے کہ اہل کتاب سے جن لوگوں کا ذکر مذموم انداز میں کیا گیا ہے وہ اورجو لوگ ان میں سے اسلام لائے ہیں دونوں برابر نہیں ہیں جب کہ ان میں ایمان والے بھی ہیں اور مجرم بھی ہیں اسی لیے وضاحت ہے کہ ان میں ایک جماعت ایسی ہے جو اللہ تعالیٰ کے احکام کے مطابق رواں دواں ہے وہ اللہ تعالیٰ کے پیغمبر علیہ السلام کی اطاعت کرنے والے ہیں ان میں استقامت ہے وہ رات کے لمحات میں قیام کرتے ہیں کثرت کے ساتھ نماز تہجد ادا کرنے میں مشغول رہتے ہیں اورقیام میں قرآن پاک کی تلاوت کرتے ہیں ان کا ایمان اللہ پاک پر اور آخرت کے دن پر ہے۔ مزید برآں وہ امر بالمعروف اور نہی عن المنکر جیسے مبار ک کام میں مشغول رہتے ہیں نیز اچھے کاموںکے سر انجا م دینے میں جلدی کرتے ہیں یقیناً ان اوصاف کے ساتھ موصوف لوگ صالحین میں شمار ہوتے ہیں چنانچہ ان لوگوں کا تذکرہ اس سورت کے آخر میں مذکور ہے ملاحظہ فرمائیں :\n﴿وَاِنَّ مِنْ اَهْلِ الْكِتٰبِ لَمَنْ يُّؤْمِنُ بِاللّٰهِ وَمَاۤ اُنْزِلَ اِلَيْكُمْ وَمَاۤ اُنْزِلَ اِلَيْهِمْ خٰشِعِيْنَ لِلّٰهِۙ لَا يَشْتَرُوْنَ بِاٰيٰتِ اللّٰهِ ثَمَنًا قَلِيْلًاؕ اُولٰٓىِٕكَ لَهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْؕ اِنَّ اللّٰهَ سَرِيْعُ الْحِسَابِ۰۰۱۹۹﴾ (آل عمران :199) ’’اور بعض اہل کتاب ایسے بھی ہیں جو اللہ پر اور اس (کتاب) پر جو تم پر نازل ہوئی اور اس پر جو ان پر نازل ہوئی ایمان رکھتے ہیں اور اللہ کے آگے عاجزی کرتے ہیں اور اللہ تعالیٰ کی آیتوں کے بدلے تھوڑی سی قیمت نہیں لیتے یہی لوگ ہیں جن کا صلہ ان کے پروردگار کے ہاں تیار ہے اور اللہ تعالیٰ جلد حساب لینے والا ہے۔‘‘"],[859,"§اہل کتاب سے ایمان لانے والوں کی فضیلت\nاہل کتاب کا جو فرد جب اسلام قبول کرلیتا ہے اس کی فضیلت میں رسول اللہ صلی اللہ علیہ وسلم فرماتے ہیں :’’ تین افراد ایسے ہیں جنہیں دگنا ثواب عطا ہوگاان میں ایک شخص وہ ہے جو پہلے کتابی تھا، اپنے پیغمبر علیہ السلام پر ایمان رکھتا تھا پھر اس کوموقع ملا اس نے آخر الزمان پیغمبر صلی اللہ علیہ وسلم کی نبوت کو تسلیم کیا آپ صلی اللہ علیہ وسلم کا تابعدار بنا وہ دوہرے ثواب کا حق دار ہے۔ ‘‘(مشکوٰۃ المصابیح مع تحقیق البانی، کتاب الایمان)\nایمان داروں کا تذکرہ فرمانے کے بعد کفار کی وعید کا بیان ہو رہا ہے، ترغیب و ترہیب کو جمع کرکے بیان کرنا قرآن پاک کا اسلوب ہے۔ كَفَرُواسے مقصود بنو قریظہ، بنو نضیر یہودیوں کے قبائل ہوں یا مشرکین قریش ہوں تاہم یہودی زبردست حریص تھے کہ ان کے پاس مال کی بہتات ہوا، نہیں طویل زندگی گزارنے کا موقع میسر آئے نیز اولاد بھی زیادہ ہو،تا کہ عددی قوت کے لحاظ سے بھی انہیں معاشرہ میں تفوق حاصل ہو، چنانچہ وہ مال کی بہتات پرنازاں تھے اور اپنے مخالف گروہ، ایمان داروں کو فقر و فاقہ کی عاردلاتے رہتے تھے بلکہ وہ برملا یہ بکواس بھی کرتے کہ اگر محمد صلی اللہ علیہ وسلم حق پر ہوتا تو اللہ تعالیٰ اس کو فقر و فاقہ سے دو چار نہ کرتا اور اس کی زندگی تلخ نہ ہوتی اصل حقیقت یہ ہے کہ جو لوگ مال کی بہتات رکھتے ہوں اور ان کی اولاد بھی زیادہ ہو تو وہ علم و ادب کی جانب کم ہی توجہ کرتے ہیں روشنی سے انہیں محبت نہیں ہوتی ہے۔ ارشاد ربانی ہے :\n﴿كَلَّاۤ اِنَّ الْاِنْسَانَ لَيَطْغٰۤىۙ۰۰۶ اَنْ رَّاٰهُ اسْتَغْنٰىؕ۰۰۷﴾ (العلق :7) ’’ہر گز نہیں بے شک انسان سرکش ہوجاتا ہے جبکہ اپنے تئیں غنی دیکھتا ہے۔‘‘\nلیکن مال و دولت سے اللہ تعالیٰ کا عذاب ٹل نہیں سکتا مال و دولت کے سبب مغرور انسان حق و صداقت سے روگردانی کرتاہے وہ حق کی جستجو کی جانب دھیان ہی نہیں کرتا اسے مال کی کثرت اور اولاد کی بہتات پر ناز ہوتا ہے اور جو شخص حق و صداقت کی جانب رخ ہی نہیں کرتا وہ زندگی بھر کفر وجہالت کے عمیق اندھیروں میں گھومتا رہتا ہے یہاں تک کہ اس کی زندگی ختم ہوجاتی ہے دنیوی زندگی میں اس نے مال و دولت کو فراہم کیا اور اپنے وارثوں کے لیے چھوڑ گیا آخرت میں اسے مال واولاد سے کچھ فائدہ نہیں ہوگا۔ دراصل ان کی روحانیت مسخ ہو گئی اور وہ اپنے غلط کردار کے سبب دوزخ کا ایندھن بن گئے۔\n﴿مَثَلُ مَا يُنْفِقُوْنَ﴾ : تباہی لانے والی آندھی سے مقصود مال ہے جس کو وہ لذات و شہوات کے حصول میں خرچ کرتے ہیں بلکہ سستی شہرت اور اپنے خیالات کے مؤیدین بنانے میں صرف کرتے ہیں جب کہ مال کی بہتات ان لوگوں کو راہ ہدایت کی جانب جانے سے رکاوٹ بنتی ہے اور انسان میں عقل و شعور کی موجودگی اور اخلاق حسنہ کی عظمت کی مثال کھیتی کی ہے یعنی جس مال کو وہ خرچ کررہے ہیں اسی مال نے ان کے اخلاق اور ان کے اعتدال کو ختم کر دیا ہے غور و فکر کے زاویوں سے کام نہیں لیا گیا اور نتائج سے خود کو بے پرواہ بنا دیا ہے۔ وضاحت ملاحظہ فرمائیں کہ وہ جو مال خرچ کرر ہے ہیں اگرچہ مصرف میں خیر کا پہلو ہے اس ٹھنڈی تیز ہوا کی مانند ہے جس کے تیز چلنے سے کھیت اور باغات بھسم ہو جاتے ہیں انہیں مال خرچ کرنے سے کچھ فائد ہ نہیں ہوتا۔ بعض مفسرین نے اس سے مقصود وہ لوگ لیے ہیں جو نبی صلی اللہ علیہ وسلم کی دشمنی میں مال خرچ کرتے ہیں وہ لوگ آپ صلی اللہ علیہ وسلم کی دعوت حقہ کو کالعدم کرنے کے لیے مال خرچ کرنے سے دریغ نہیں کرتے ہیں۔ عام ہے کہ مال خرچ کرنے والے یہودی ہیں یا منافق ہیں چنانچہ بعض مفسرین نے اس سے مقصود وہ منافق لوگ لیے ہیں جو ریاکاری یا تقیہ کے پیش نظر مال خرچ کرتے ہیں لیکن یہ دونوں گروہ ناکام ہیں جب کہ ان کے مقابلہ میں اللہ تعالیٰ نے اپنے پیغمبر علیہ السلام اور ایمان داروں کوغلبہ عطا کیا اور منافقین کو رسوائی سے ہمکنار کیا جیسا کہ سورۂ براء ۃ میں اس کا مفصل تذکرہ ہے۔ (المنار : 76/4-77)\n﴿يٰۤاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تَتَّخِذُوْا بِطَانَةً مِّنْ دُوْنِكُمْ لَا يَاْلُوْنَكُمْ خَبَالًاؕ وَدُّوْا مَا عَنِتُّمْۚ قَدْ بَدَتِ الْبَغْضَآءُ مِنْ اَفْوَاهِهِمْۚۖ وَمَا تُخْفِيْ صُدُوْرُهُمْ اَكْبَرُؕ قَدْ بَيَّنَّا لَكُمُ الْاٰيٰتِ اِنْ كُنْتُمْ تَعْقِلُوْنَ۰۰۱۱۸ هٰۤاَنْتُمْ اُولَآءِ تُحِبُّوْنَهُمْ وَلَا يُحِبُّوْنَكُمْ وَتُؤْمِنُوْنَ بِالْكِتٰبِ كُلِّهٖۚ وَاِذَا لَقُوْكُمْ قَالُوْۤا اٰمَنَّاۚࣗۖ وَاِذَا خَلَوْا عَضُّوْا عَلَيْكُمُ الْاَنَامِلَ مِنَ الْغَيْظِؕ قُلْ مُوْتُوْا بِغَيْظِكُمْؕ اِنَّ اللّٰهَ عَلِيْمٌۢ بِذَاتِ الصُّدُوْرِ۰۰۱۱۹ اِنْ تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ١ٞؗ وَاِنْ تُصِبْكُمْ سَيِّئَةٌ يَّفْرَحُوْا بِهَاؕ وَاِنْ تَصْبِرُوْا وَتَتَّقُوْا لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔاؕ اِنَّ اللّٰهَ بِمَا يَعْمَلُوْنَ مُحِيْطٌࣖ۰۰۱۲۰﴾\nاے لوگو جو ایمان لائے ہو! تم اپنے لوگوں کے سوا کسی کو دلی دوست نہ بنائو، دوسرے لوگ تمہیں برباد کرنے میں کوئی کسر نہیں چھوڑتے، وہ چاہتے ہیں کہ تم مصیبت میں پڑو، ان کے دلوں کی دشمنی ان کے مونہوں سے ظاہر ہو چکی ہے اور وہ اپنے سینوں میں جو (بغض و عناد) چھپاتے ہیں وہ کہیں زیادہ ہے۔ ہم نے تمہارے لیے آیتیں کھول کر بیان کی ہیں اگر تم عقل رکھتے ہو\nخبردار! تم لوگ ان سے محبت رکھتے ہو، جبکہ وہ تم سے محبت نہیں رکھتے تم سب کتابوں پر ایمان رکھتے ہو (جبکہ وہ ایسا نہیں کرتے) اور وہ تمہارے سامنے تو اپنے ایمان کا اقرار کرتے ہیں مگر جب تنہا ہوتے ہیں تو تم پر اپنی انگلیاں چباتے ہیں غصے کے مارے۔ (ان سے) کہیے: تم اپنے غصے ہی میں مر جائو، بے شک اللہ دلوں کے راز خوب جانتا ہے\nاگر تمہیں کوئی بھلائی پہنچے تو وہ انہیں بری لگتی ہے اور اگر تمہیں کوئی برائی پہنچے تو وہ اس پر خوش ہوتے ہیں۔ اگر تم صبر کرو اور پرہیز گاری اختیار کرو تو ان کا مکر تمہیں کوئی\nنقصان نہیں پہنچائے گا۔ بے شک اللہ نے ان کے اعمال کو گھیر رکھا ہے"],[860,"§مومنوں کو چھوڑ کر دوسروں کو راز دار بنانے کی ممانعت\nاللہ تبارک و تعالیٰ اپنے مومن بندوں کو اس بات سے منع فرما رہا ہے کہ وہ منافقوں کو راز دار بنائیں اور انہیں اپنے بھیدوں سے آگاہ کریں اور انہیں وہ باتیں بتائیں جو انہوں نے اپنے دشمنوں سے چھپا رکھی ہوں کیونکہ منافقوں کی یہ کوشش ہوتی ہے کہ وہ مسلمانوں کو نقصان پہنچانے میں کوئی کسر نہ اُٹھا رکھیں، یعنی وہ مسلمانوں کی دشمنی میں ہر وقت اورہر ممکن طریقے سے مستعد رہتے ہیں اور جس قدر بھی ممکن ہو مکر و فریب سے کام لیتے ہیں اور ایسے کاموں کو پسند کرتے ہیں جو مومنوں کے لیے تکلیف اور مشقت کا باعث ہوں۔\nاللہ تعالیٰ نے فرمایا ہے : ﴿لَا تَتَّخِذُوْا بِطَانَةً مِّنْ دُوْنِكُمْ﴾ ’’کسی غیر (مذہب کے آدمی) کو اپنا رازدار نہ بنانا۔‘‘ یعنی اپنے علاوہ دیگر اہل ادیان کے لوگوں کو راز دارنہ بناؤ۔ عربی زبان میں ﴿بِطَانَةً ﴾ آدمی کے ان خاص اہل و عیال کو کہتے ہیں جو گھر کے داخلی امور سے مکمل طور پر آگاہ ہوتے ہیں۔ (صحیح البخاری : 7198)\nامام بخاری، نسائی اور دیگر کئی محدثین رحمہ اللہ نے سیدنا ابو سعید خدری رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’اللہ تعالیٰ نے جو بھی نبی مبعوث فرمایا اور جو بھی خلیفہ مقرر فرمایا تو اس کے دو قسم کے راز دار تھے۔ ایک قسم وہ جو خیر کا حکم اور ترغیب دیتے تھے اور دوسرے وہ جو برائی کا حکم اور ترغیب دیتے تھے اور معصوم تو وہ ہے جسے اللہ تعالیٰ گناہ سے بچالے۔‘‘(صحیح البخاری : 7198وسنن النسائی : 4207)\nامام ابن ابو حاتم رحمہ اللہ نے ابو دجانہ کی روایت کو بیان کیا ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ کی خدمت میں عرض کی گئی کہ یہاں اہل حِیرہ کا ایک بڑا ماہر کاتب ہے، لہٰذا آپ رضی اللہ عنہ اسے اپنے ہاں بطور کاتب مقرر فرمالیں تو آپ رضی اللہ عنہ نے فرمایا: کہ اس کے معنی تو یہ ہوں گے کہ میں مومنوں کے علاوہ کسی دوسرے کو اپنا راز دار بنالوں۔(تفسیر ابن أبی حاتم : 743/3 والمصنف لابن أبی شیبۃ : 25863) آیت کے ساتھ ساتھ یہ اثر بھی اس بات کی دلیل ہے کہ ذِمیوں کو اس کتابت کے لیے استعمال کرنا جائز نہیں جسے وہ مسلمانوں کی دشمنی کے لیے استعمال کر سکیں اورمسلمانوں کے ان داخلی اُمور سے آگاہ ہوجائیں جن کے بارے میں یہ خدشہ ہو کہ وہ جنگی دشمنوں کو ان سے مطلع کردیں گے۔ اسی لیے اللہ تعالیٰ نے فرمایاہے: ﴿لَا يَاْلُوْنَكُمْ خَبَالًاؕ وَدُّوْا مَا عَنِتُّمْۚ﴾ ’’یہ لوگ تمہاری خرابی (اور فتنہ انگیزی کرنے) میں کسی طرح کی کوتاہی نہیں کرتے، چاہتے ہیں کہ (جس طرح ہو) تمہیں تکلیف پہنچے۔ ‘‘\nپھر اللہ تعالیٰ نے فرمایا: ﴿قَدْ بَدَتِ الْبَغْضَآءُ مِنْ اَفْوَاهِهِمْۚۖ وَمَا تُخْفِيْ صُدُوْرُهُمْ اَكْبَرُؕ﴾ ’’ان کی زبانوں سے تو دشمنی ظاہرہو چکی ہے اور جو (کینے) ان کے سینوں میں مخفی ہیں، وہ کہیں زیادہ ہیں۔‘‘ یعنی ان کے چہروں کے نقوش اور زبانوں کے الفاظ ہی سے دشمنی نمایاں ہے۔ اور اس کے ساتھ ساتھ اسلام اور مسلمانوں کے لیے اپنے سینوں میں جو بغض رکھتے ہیں وہ کسی بھی ذی شعور اور عقل مند شخص سے مخفی نہیں رہ سکتا۔ اسی لیے اللہ تعالیٰ نے فرمایاہے :﴿قَدْ بَيَّنَّا لَكُمُ الْاٰيٰتِ اِنْ كُنْتُمْ تَعْقِلُوْنَ۰۰۱۱۸﴾ ’’یقیناً اگر تم عقل رکھتے ہو تو ہم نے تم سے اپنی آیتیں کھول کھول کر بیان کر دی ہیں۔ ‘‘\nفرمان باری تعالیٰ ہے : ﴿هٰۤاَنْتُمْ اُولَآءِ تُحِبُّوْنَهُمْ وَلَا يُحِبُّوْنَكُمْ﴾ ’’دیکھو! تم ایسے (صاف دل) لوگ ہو کہ ان لوگوںسے دوستی رکھتے ہو، حالانکہ وہ تم سے دوستی نہیں رکھتے۔‘‘ مطلب یہ ہے کہ مومنو! جب منافق تمہارے سامنے ایمان کا اظہار کرتے ہیں تو تم ان سے دوستی رکھنے لگ جاتے ہو مگر وہ ظاہری یا باطنی طور پر تم سے قطعاً دوستی نہیں رکھتے ﴿وَتُؤْمِنُوْنَ بِالْكِتٰبِ كُلِّهٖۚ﴾ ’’اور تم سب کتابوں پر ایمان رکھتے ہو۔‘‘ تمہیں ان کتابوں کے بارے میں قطعاً کوئی شک و شبہ نہیں ہے جبکہ وہ شک وشبہ اورحیرت میں مبتلا ہیں۔\nمحمد بن اسحاق رحمہ اللہ نے حضرت ابن عباس رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ تم اپنی کتاب پر بھی، ان کی کتاب پر بھی اور اس سے پہلے کی تمام کتابوں پر بھی ایمان رکھتے ہو مگر وہ تمہاری کتاب پر ایمان نہیں رکھتے بلکہ اس کے ساتھ کفر کرتے ہیں، لہٰذا ان کی نسبت تم اس بات کے زیادہ حق دار ہو کہ ان سے بغض رکھو۔(تفسیر الطبری : 86/4)\nارشاد باری تعالیٰ ہے : ﴿وَاِذَا لَقُوْكُمْ قَالُوْۤا اٰمَنَّاۚࣗۖ وَاِذَا خَلَوْا عَضُّوْا عَلَيْكُمُ الْاَنَامِلَ مِنَ الْغَيْظِؕ﴾ ’’اور وہ جب تم سے ملتے ہیں تو کہتے ہیں : ہم ایمان لے آئے ہیں اور جب الگ ہوتے ہیں تو تم پر غصے کے سبب انگلیاں کاٹ کاٹ کھاتے ہیں۔‘‘ امام قتادہ رحمہ اللہ کا قول ہے کہ ﴿ الْاَنَامِلَ﴾ سے مراد اُنگلیوںکے پورے ہیں۔(تفسیر الطبری : 89/4) منافقوں کی یہی حالت ہوتی ہے کہ مومنوں کے سامنے تو ایمان اور مودّت کا اظہار کرتے ہیں لیکن باطنی طور پر ان کی صورتحال اس کے بالکل خلاف ہے۔ جیسا کہ اللہ تعالیٰ نے فرمایا ہے :﴿وَاِذَا خَلَوْا عَضُّوْا عَلَيْكُمُ الْاَنَامِلَ مِنَ الْغَيْظِؕ﴾ ’’اور وہ جب الگ ہوتے ہیں تو تم پر غصے کے سبب اُنگلیاں کاٹ کاٹ کھاتے ہیں۔‘‘ اور ان کی یہ حالت غیض و غضب کی شدت کی وجہ سے ہوتی ہے تو اللہ تعالیٰ نے فرمایا ہے : ﴿قُلْ مُوْتُوْا بِغَيْظِكُمْؕ اِنَّ اللّٰهَ عَلِيْمٌۢ بِذَاتِ الصُّدُوْرِ۰۰۱۱۹﴾ ’’(ا ن سے) کہہ دیجئے کہ (بدبختو!) تم اپنے غصے ہی میں مرجاؤ، اللہ تعالیٰ تمہارے دلوں کی باتوں سے خوف واقف ہے۔‘‘ تم مسلمانوں سے جس قدر بھی حسد رکھو، ان سے جس قدر بھی بغض رکھو، اللہ تعالیٰ اپنے ان مومن بندوں پر اپنی نعمتوں کو مکمل فرما کر رہے گا، اپنے دین کی تکمیل کرکے رہے گا، اپنے کلمے کو ہر صورت سربلندی عطا فرمائے گا اور اپنے دین کو بہر آئینہ غالب کرکے رہے گا، لہٰذا تم اپنے غصے میں مرجاؤ۔\nارشاد ِالٰہی ہے:﴿اِنَّ اللّٰهَ عَلِيْمٌۢ بِذَاتِ الصُّدُوْرِ۰۰۱۱۹﴾ ’’بے شک اللہ تعالیٰ دلوں کے راز جانتا ہے۔‘‘ یعنی اللہ تبارک و تعالیٰ تمہارے دلوں کی باتوں سے خوب واقف ہے۔ وہ جانتا ہے کہ تمہارے دلوں میں کیا کچھ ہے اور تمہارے سینوں میں مسلمانوں کے خلاف کس قدر بغض، حسد اور کینہ ہے ! اور وہ تمہیں دنیا میں بھی اس کی سزا یہ دے گا کہ تمہیں تمہاری اُمیدوں کے خلاف صورت حال دکھائے گا اور آخرت میں تمہیں جہنم میں عذابِ شدید کا مزہ چکھائے گا جس میں تم ہمیشہ ہمیشہ رہو گے اور کبھی بھی اس سے باہر نہ آسکوگے۔\nکافروںکی مسلمانوں سے شدت عداوت کی مزید تفصیل بیان کرتے ہوئے،ا للہ نے فرمایا: کہ تم ان کافروں سے دوستی رکھتے ہو، جب کہ تم سے ان کی عداوت کا حال یہ ہے کہ اگر کوئی بھلائی تمہیں چھو بھی جاتی ہے تو انہیں تکلیف ہوتی ہے، اور اگر تم پر کوئی مصیبت آپڑتی ہے تو مارے خوشی کے آپے سے باہر نکلے جاتے ہیں، تو بھلا ایسوں کو دوست بنانا کہاں کہ دانش مندی ہے؟!\nاس کے بعد اللہ تعالیٰ نے مسلمانوں کو کافروں کے شر و فساد سے بچنے کا یہ طریقہ بتایا کہ مسلمانوں کو اللہ کی طرف سے آزمائشوں پر صبر کی عادت ڈالنی چاہیے، ہر حال میں اللہ سے ڈرتے رہنا چاہیے، تقویٰ اور بندگی کی راہ اختیار کرنی چاہیے، اور غیر مسلموں سے مدد نہیں لینی چاہیے، اگر وہ ایسا کریں گے تو کافروں کا مکر و فریب انہیں نقصان نہیں پہنچائے گا، اس لیے کہ جو اللہ پر توکل کرے گا، آزمائشوں پر صبر کرے گا اور صر ف اسی سے مدد مانگے گا، وہ یقینا اپنے مقاصد میں کامیاب ہوگا۔ اللہ اسے کبھی بھی ضائع نہیں کرے گا، اور دشمن کے مقابلے میں اسے فتح و نصرت عطا کرے گا، اور جو غیروں سے مددچاہے گا، اللہ اسے اس کے نفس کے حوالے کر دے گا اور اپنی نصرت سے اسے محروم کر دے گا۔\nکاش مسلمان آج بھی یہ نسخہ استعمال کرکے دیکھتے اور اللہ کو چھوڑ کر دوسروں کے سامنے جبہ سائی نہ کرتے۔بڑی طاقتوں کو اپنامعبود نہ بناتے، اللہ کےبجائے ان سے مدد نہ مانگتے، تو اللہ کا وعدہ ہمیشہ کے لیے ایک ہی ہے، فتح و کامیابی ان کے قدم چومتی، عزت و سیادت ان کےسر کا تاج ہوتی اور دوسری قومیں ان کے سامنے گھٹنا ٹیک دیتیں، کیا کوئی ہے جو اس آواز پر کان دھرے؟"],[861,"§یہود مدینہ سے دوستی کی ممانعت\nیہ خطاب دراصل انھی انصار مدینہ سے ہے۔ ان کے دو بڑے قبیلے اوس و خزرج مدینہ میں آباد تھے۔ اسلام سے پہلے ان قبائل کی آپس میں ٹھنی رہتی تھی اور مدینہ کے یہودی بھی تین قبائل میں منقسم تھے۔ یہودیوں کا کام یہ تھا کہ ان کا ایک قبیلہ اوس کا حلیف بن جاتا اور دوسرا خزرج کا اور اس طرح اوس و خزرج کو آپس میں لڑاتے رہتے تھے اور اس طرح کئی طرح کے مفادات حاصل کرتے تھے۔ مثلاً ایک یہ کہ ان کے ہتھیار فروخت ہو جاتے تھے۔ دوسرے یہ کہ اپنی قلت تعداد کے باوجود انصار مدینہ پر اپنی بالادستی قائم رکھتے اور ان کی معیشت و سیاست پر چھائے ہوئے تھے۔ جب اوس و خزرج کے قبیلےمسلمان ہو گئے تو اس کے بعد بھی وہ یہودیوں کے ساتھ وہی پرانے تعلقات نباہتے رہے اور اپنے سابق یہودی دوستوں سے اسی سابقہ محبت و خلوص سے ملتے رہے۔ لیکن یہودیوں کو آپ اور آپ صلی اللہ علیہ وسلم کے مشن سے جو بغض و عناد تھا اس کی بنا پر وہ کسی مسلمان سے مخلصانہ محبت رکھنے کو تیار نہ تھے۔ انھوں نے منافقانہ روشن اختیار کر رکھی تھی۔ ظاہر میں تو وہ انصار سے دوستی کام دم بھرتے تھے۔ مگر دل میں ان کے سخت دشمن بن چکے تھے۔ اس ظاہری دوستی سے وہ دو قسم کے فوائد حاصل کرنا چاہتے تھے۔ ایک یہ کہ کسی طرح مسلمانوں میں فتنہ و فساد پیدا کر دیں جیسا کہ شماس بن قیس یہودی نے کیا بھی تھا اور دوسرے یہ کہ مسلمانوں کے جماعتی راز ان کے دشمنوں تک پہنچائیں۔ انھی وجوہ کی بنا پر اللہ تعالیٰ نے مسلمانوں کو کسی بھی غیر مسلم سے دوستی گانٹھنے اور اسے اپنا راز دار بنانے سے روک دیا اور یہود کے بغض و عناد کا تو یہ حال تھا کہ بسااوقات ان کی زبان سے کوئی ایسی بات نکل جاتی تھی جو ان کی مسلمانوں سے گہری دشمنی کا پتا دے جاتی تھی اور حسد اور دشمنی کے بارے میں ان کی زبان قابو میں نہیں رہتی تھی۔ اور جو ان کے دلوں میں کدورت بھری ہوئی تھی وہ تو اس سے بہت بڑھ کر تھی۔ اسی لیے اللہ تعالیٰ نے مسلمانوں کو متنبہ کرتے ہوئے فرمایا کہ اگر تم سوچو تو ان کی دوستی میں تمھیں سراسر نقصان ہی نقصان ہے۔ لہٰذا کافروں سے دوستی رکھنے سے بہر حال تمھیں اجتناب کرناچاہیے۔"],[862,"§کفار سے دوستی کی ممانعت\nموجودہ صورت حال یہ ہے کہ تم تو تمام آسمانی کتابوں پر ایمان رکھتے ہو جن میں تورات بھی شامل ہے۔لیکن اہل کتاب تمھارے قرآن پر ایمان نہیں رکھتے، اس بات کا تقاضا تو یہ تھا کہ وہ تم سے محبت رکھتے اور تم ان سے دشمنی رکھتے، مگر یہاں معاملہ اس کے بالکل برعکس ہے۔ تم یہ کیسی اُلٹی گنگا بہا رہے ہو؟\nاگر تمھیں کوئی خوشی کا موقعہ میسر آئے تو یہ جل بھن جاتے ہیں اور کوئی تکلیف پہنچے تو اس پر خوشی سے پھولے نہیں سماتے۔ تو کیا پھر ایسے لوگوں کی دوستی سے پرہیز ہی بہتر نہیں؟ بس تم صبر سے کام لو۔ ان کی سازشیں اور پراپیگنڈے تمھارا بال بھی بیکا نہیں کر سکتے۔ کیونکہ اللہ تعالیٰ خود ان پر کڑی نظر رکھے ہوئے ہے۔\nآیت نمبر (118)سے لے کر (120)تک 3آیات میں اللہ تعالیٰ نے کافروں سے دوستی گانٹھنے کی ممانعت کے لیے جو وجوہات بیان فرمائی ہیں وہ مختصراً درج ذیل ہیں:\n(1) وہ تمھارے درمیان خرابی، بگاڑ اور فساد پیدا کرنے کے لیے کوئی دقیقہ فروگذاشت نہیں کرتے اور ان کی ہر ممکن کوشش یہ ہوتی ہے کہ تم میں تفرقہ و انتشار اور بغض و عداوت پیدا ہوجائے۔\n(2) وہ یہ چاہتے ہیں کہ تم کسی ارضی و سماوی آفت اور مصیبت میں پھنس جاؤ۔\n(3) ان کے منہ سے کچھ بے اختیار ایسی باتیں نکل جاتی ہیں جو ان کے دلوں میں پکنے والے مواد کا پتہ دے جاتی ہیں۔\n(4) تم ان سے محبت رکھتے ہو جبکہ وہ تم سے دشمنی رکھتے ہیں، حالانکہ تم ان کی کتاب تورات پر ایمان لاتے ہو اور وہ تمھاری کتاب قرآن کے منکر ہیں اور اس کا منطقی نتیجہ یہ ہونا چاہیے کہ وہ تم سے دوستی رکھتے اور تم ان سے دوشمنی رکھتے، لیکن یہاں اُلٹی گنگا بہائی جا رہی ہے۔\n(5) اگر تمھیں کوئی بھلائی حاصل ہو تو اس سے وہ جل بھن جاتے ہیں اور اگر تمھیں تکلیف پہنچے تو اندر ہی اندر پھولے نہیں سماتے۔ (6) اگر وہ تم سےکوئی خیر خواہی کی بات بھی کریں تو وہ منافقت پر مبنی ہوتی ہے۔\nلہٰذا ان وجوہات کی بناء پر تمھیں ان سے دوستی نہ رکھنا چاہیے اور راز بتانا تو بڑی دور کی بات ہے۔\nیہ ان کے مکر و فریب سے بچنے کا طریقہ اور علاج ہے۔ گویا منافقین اور دیگر اعدائے اسلام و مسلمین کی سازشوں سے بچنے کے لیے صبر اورتقویٰ نہایت ضروری ہے۔ اس صبر اور تقویٰ کے فقدان نے غیر مسلموں کی سازشوں کو کامیاب بنا رکھا ہے۔ لوگ سمجھتے ہیں کہ کافروں کی یہ کامیابی مادی اسباب و وسائل کی فراوانی اور سائنس و ٹیکنالوجی میں ان کی ترقی کا نتیجہ ہے۔ حالانکہ واقعہ یہ ہے کہ مسلمانوں کی پستی و زوال کا اصل سبب یہی ہے کہ وہ اپنے دین پر استقامت (جو صبر کا متقاضی ہے) سے محروم اور تقویٰ سے عاری ہو گئے ہیں جو مسلمان کی کامیابی کی کلید اور تائید الٰہی کے حصول کاذریعہ ہے۔"],[863,"§شانِ نزول\nابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ کچھ مسلمان لوگ یہودیوں کے ساتھ تعلقات رکھتے تھے اللہ پاک نے مسلمانوں کو سختی کے ساتھ روک دیا ہے کہ وہ یہودیوں کے ساتھ جاہلیت کے کسی معاہدہ کے پیش نظر بھائی چارہ قائم نہ رکھیں وہ لوگ فتنہ پرور ہیں ان کے فتنوں سے خود کو تحفظ عطا کریں۔ بعض مفسرین نے ان منافقین کو بھی شامل کیا ہے جن کا تعلق اوس، خزرج قبائل سے تھا ان قبائل کے لوگوں کی یہودیوں سے پرانی دوستی تھی بلکہ اسلام لانے کے بعد بھی انہوں نے اپنے پرانے تعلقات کو قائم رکھا لیکن یہودی آپ صلی اللہ علیہ وسلم کے مشن کے شدید مخالف تھے اس بناء پر ان کی دوستی انصار صحابہ کرام رضی اللہ عنہم کے ساتھ ظاہری تھی اس دوستی سے فائدہ اُٹھاتے ہوئے وہ برابر اس کوشش میں لگے رہتے تھے کہ جیسے بھی ممکن ہو مسلمانوں کی جماعت میں فتنہ وفساد برپا کریں اور ان کے تنظیمی رازوں سے باخبر ہو کر ان کے دشمنوں تک پہنچائیں ان کی اس منافقانہ روش سے محتاط رہنے کے لیے مسلمانوں کو متنبہ کیا ہے۔ (المنار : 80/2-81)\nصحیح بخاری، نسائی کتب حدیث میں ابو سعیدخدری رضی اللہ عنہ سے ایک حدیث مروی ہے ارشاد نبوی صلی اللہ علیہ وسلم ہے :’’اللہ پاک نے ہر پیغمبر علیہ السلام بلکہ ہر وہ شخص جو پیغمبر علیہ السلام کا خلیفہ بنا اس کے ساتھ دور ازدار ساتھی مقرر فرمائے ہیں ان میں ایک خاص راز دار ساتھی تو اسے اچھے کاموں کا مشورہ دیتا ہے بلکہ ترغیب دلاتا ہے جب کہ دوسرا ساتھی اسے گناہ کے کاموں پر اُکساتا ہے لیکن جس شخص کو اللہ پاک اس کے اُکسانے سے تحفظ عطا فرمائے وہ محفوظ رہتا ہے۔\nپس غیر مسلمان شخص کو راز دار نہ سمجھا جائے اور اسے کسی اُونچی پوسٹ پر متعین نہ کیا جائے چنانچہ عمر رضی اللہ عنہ کو مشورہ دیا گیا کہ فلاں شہر کا ایک شخص فن کتابت میں ماہر ہے اور نگرانی کے فرائض میں کوتاہی کرنے والا نہیں ہے آپ اسے اپنا انشاء پردازی کا کام سونپ دیں آپ رضی اللہ عنہ نے جواب دیا کیسے ممکن ہے کہ میں اپنا رازدار ایسے انسان کو بناؤں جو ایمان دار نہیں ہے۔معلوم ہوا کہ کتابت کا کام کسی ذمی کو نہ سونپا جائے وہ اس پوسٹ پر جب متعین ہوگا تو اس میں غرور آئے گا اور وہ خود کو مسلمانوں سے اُونچا سمجھےگا۔ مزید برآں مسلمانوں کے داخلی مخفی اُمور پر اس کو آگاہی حاصل ہوگی ممکن ہے کہ اس کی خفیہ سرگرمیاںمسلمانوں کو کسی نقصان سے دو چار نہ کردیں اسی لیے فرمایا: کہ وہ تمہیں نقصان پہنچانے میں کوئی کسر نہیں چھوڑیں گے وہ تو اس کوشش میں برابر لگے رہتے ہیں کہ کسی طرح مسلمانوں کو مصائب و مشکلات کے بھنور میں پھنسائے رکھیں۔\n﴿قَدْ بَدَتِ الْبَغْضَآءُ مِنْ اَفْوَاهِهِمْۚۖ﴾ ان کے چہروں کے خدوخال اور ان کی زبانوں پر غیر شعوری طور پر باتیں آجاتی ہیں اس کے ساتھ ساتھ ان کے دل اسلام اور مسلمانوں کے ساتھ دشمنی میں اس قدر تیز ہیں کہ ان کی دشمنی ان کے چہرے مہرے سے اس قدر مترشح ہوتی ہے کہ کسی بھی سمجھ دار انسان سے ان کی دشمنی مخفی نہیں ہے۔\n(تفسیر ابن کثیر : 595/1-596)\n﴿قَدْ بَيَّنَّا لَكُمُ الْاٰيٰتِ﴾ : مقصود یہ ہے کہ ہم نے تمہیں ان علامات سے آگاہ کر دیا ہے جن کی روشنی میں تم خود میں اس صلاحیت کو اُجاگر کر پاتے ہو کہ کون شخص ایسا ہے جس کو راز دار، دوست بنایا جائے اور کس کو خائن اور اس کی خباثت باطنی کے سبب اس سے مکمل انقطاع رکھا جائے، ارشاد الٰہی میں مکمل وضاحت ہے، ملاحظہ فرمائیں :\n﴿لَا يَنْهٰىكُمُ اللّٰهُ عَنِ الَّذِيْنَ لَمْ يُقَاتِلُوْكُمْ فِي الدِّيْنِ وَلَمْ يُخْرِجُوْكُمْ مِّنْ دِيَارِكُمْ اَنْ تَبَرُّوْهُمْ وَتُقْسِطُوْۤا اِلَيْهِمْؕ اِنَّ اللّٰهَ يُحِبُّ الْمُقْسِطِيْنَ۰۰۸ اِنَّمَا يَنْهٰىكُمُ اللّٰهُ عَنِ الَّذِيْنَ قٰتَلُوْكُمْ فِي الدِّيْنِ وَاَخْرَجُوْكُمْ مِّنْ دِيَارِكُمْ وَظٰهَرُوْا عَلٰۤى اِخْرَاجِكُمْ اَنْ تَوَلَّوْهُمْۚ وَمَنْ يَّتَوَلَّهُمْ فَاُولٰٓىِٕكَ هُمُ الظّٰلِمُوْنَ۰۰۹﴾ (الممتحنہ :8-9) ’’جن لوگوں نے تم سے دین کے بارے میں جنگ نہیں کی اورنہ تم کو تمہارے گھروں سے نکالا ان کے ساتھ بھلائی اور انصاف کا سلوک کرنے سے اللہ تم کو منع نہیں کرتا اللہ تعالیٰ تو انصاف کرنے والوں کو دوست رکھتا ہے اللہ تعالیٰ انہی لوگوں کے ساتھ تم کو دوستی کرنے سے منع کرتا ہے جنہوں نے تم سے دین کے بارے میں لڑائی کی اور تم کو تمہارے گھروں سے نکالا اور تمہارے نکالنے میں اوروں کی مدد کی تو جو لوگ ان سے دوستی کریں وہی ظالم ہیں۔ ‘‘\n﴿هٰۤاَنْتُمْ اُولَآءِ تُحِبُّوْنَهُمْ وَلَا يُحِبُّوْنَكُمْ﴾ : بلاشبہ تم تو ان کفار سے محبت کرتے ہو جو سب لوگوں سے زیادہ تمہارے دشمن ہیں اور تمہارے معاملات کے بگاڑ میں ہر گز نرمی کا سبب نہیں رکھتے ہیں ان کی دلی آرزو ہے کہ تم مشقت میں غلطاں رہو وہ تمہارے بارے میں دشمنی اور دھوکہ بازی کا کھلے بندوں کردار ادا کرتے ہیں۔ بلکہ وہ اس انتظار میںہیں کہ کب تم پر مصائب کے پہاڑٹوٹتے ہیں تعجب ہے کہ تم کیسے ان کے ساتھ محبت کرتے ہو اور صلہ رحمی کرتے ہو۔ غور فرمائیں باوجود ان کی اس کیفیت کے مقابلہ میں ایمان والوں کا ان سے محبت کرنا اس حقیقت کو ثابت نہیں کر رہا ہے کہ دین اسلام تو محبت، آشتی، سہل انگاری کا نام ہے کہ اس سے زیادہ بہترین سلوک کا تصور بھی ممکن نہیں ہے۔\nبلکہ حیرت ہے کہ اس قدر بہترین سلوک کے مقابلہ میں وہ تم سے محبت کا اظہار بھی نہیں کرتے ہیں حالانکہ تم نہ صرف اس کتاب پر ایمان رکھتے ہو جو تمہارے لیے نازل ہوئی ہے بلکہ اس کتاب پر بھی ایمان رکھتے ہو جو ان کی ہدایت کے لیے نازل ہوئی ہے لیکن کیا خیال ہے اگر تم ان کی کتاب پر ایمان کااظہار نہ کرو جیسا کہ وہ تمہاری کتاب پر ایمان کا اظہار نہیں کرتے ہیں پھر تم اس لائق ہو کہ وہ تم سے دشمنی کریں باوجود اس کے تم ان سے محبت کرتے ہو لیکن وہ تم سے محبت کا اظہار بھی نہیں کرتے ہیں مزید برآں تم تو ان کی کتاب پر بھی ایمان رکھتے ہو۔\n﴿وَاِذَا لَقُوْكُمْ قَالُوْۤا اٰمَنَّاۚࣗۖ﴾ :جب منافقین تم سے ملاقات کرتے ہیں تو تمہارے ساتھ گفتگو کا انداز نرم ہوتا ہے بلکہ بظاہرزبان سے ایمان کااظہا رکرتے ہیں اور جب وہ تنہائی میں ہوتے ہیں جہاں سے وہ ایمان داروں کے سامنے نہیں ہوتے تو مسلمانوںکے ساتھ زبردست دشمنی کا اظہار کرتے ہیں یہاں تک کہ غصہ کی شدت کے عالم میں اپنی اُنگلیوں کو کاٹنا شروع کر دیتے ہیں اور مطلوب کے عدم حصول پر زبردست غم وغصہ کا اظہار کرتے ہیں۔ دراصل ان کی یہ کیفیت اس بنا پر ہے کہ وہ ایمان داروں میں اُلفت و مودت کا جذبہ کار فرما دیکھتے ہیں اور ان کے اتفاق پر ان کے غم و غصہ میں زبردست اضافہ ہوتا ہے۔ مزید برآں اللہ پاک جب مسلمانوں کوغلبہ عطا فرماتا ہے تو انہیں اس کے سوا کوئی چارہ کار نہیں رہتا ہے کہ وہ کفار کے ساتھ بظاہر دشمنی کے انداز کو چھوڑ کر مدارات پر اُتر آتے ہیں۔\n﴿قُلْ مُوْتُوْا بِغَيْظِكُمْؕ﴾ :ان کے حق میں بددعائیہ کلمہ ہے تاکہ ان کے غیظ و غضب میں مزید اضافہ ہو کہ وہ تباہ وبرباد ہوجائیں مقصود اسلام کی قوت میں اضافہ اور مسلمانوں کی عزت میں حیران کن خوشخبری ہے۔\n﴿اِنْ تَمْسَسْكُمْ حَسَنَةٌ﴾ جب تمہیں دشمن پر غلبہ حاصل ہوتا ہے اور لوگ دین اسلام میں فوج درفوج داخل ہونے لگتے ہیں تو انہیں اس سے غم لاحق ہوتا ہے اور ان کے دلوںپر یہ خبر نہایت شاق گزرتی ہے اور اگر تمہیں شکست کا سامنا ہوتا ہے یا تمہاری جمعیت میں اختلاف رونما ہوتا ہے تو وہ اس پر خوش ہوتے ہیں۔\n﴿وَاِنْ تَصْبِرُوْا وَتَتَّقُوْا لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔاؕ﴾ اگر تم میں تکالیف پر صبر کا جذبہ کار فرما ہے بلکہ تم احکام الٰہیہ کے مطابق رواں دواں رہو اور منہیات سے بچاؤ اختیار کرو چنانچہ کفار کو رازدار بنانا بھی ممنوع ہے تو اس سے بھی رُکے رہو تو ایسی حالت میں ان کا دجل فریب تمہیں کچھ نقصان نہیں پہنچا سکتا جب کہ تم نے اللہ تعالیٰ کے ساتھ کیے گئے عہد کا ایفاء کیا عبودیت کا ثبوت پیش کیا تو اللہ تعالیٰ بھی اپنے حق ربوبیت کو پورا فرمائے گا اور تمہیں آفات و مصائب سے تحفظ عطا کرےگا۔ ارشادِ الٰہیہے: ﴿وَمَنْ يَّتَّقِ اللّٰهَ يَجْعَلْ لَّهٗ مَخْرَجًاۙ۰۰۲ وَّيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُؕ﴾ (الطلاق :2-3) ’’اور جو کوئی اللہ تعالیٰ سے ڈرے گا وہ اس کے لیے (تنگی سے)خلاصی(کی صورت) پیدا کر دے گا اور اس کو ایسی جگہ سے رزق دےگا جہاں سے (وہم و) گمان بھی نہ ہو۔‘‘\nایک حکیم کا قول ہے جب تم اپنے حاسدین کو ذلیل و خوار کرنا چاہتے ہو توتم مزید فضائل اور مکارم اخلاق میں کوشاں رہو اس آیت کے مفہوم میں عبرت کا سامان موجزن ہے کہ ایمان دار لوگ دشمنوں کی دشمنی پر صبر کریں جہاں تک ممکن ہو ان کے شر سے خود کو تحفظ عطا کریں لیکن برائی کا بدلہ برائی سے نہ دیں قرآن پاک کا اسلوب داعیانہ ہے وہ تو محبت و آشتی کا درس دیتاہے وہ تو برائی کے مقابلہ میں نیکی کا حکم دیتا ہے۔ ارشاد ربانی ہے : ﴿اِدْفَعْ بِالَّتِيْ هِيَ اَحْسَنُ فَاِذَا الَّذِيْ بَيْنَكَ وَبَيْنَهٗ عَدَاوَةٌ كَاَنَّهٗ وَلِيٌّ حَمِيْمٌ۰۰۳۴﴾ (فصلت :34) ’’مدافعت میں بہت اچھا انداز اختیار کریں تو اس وقت وہ شخص کہ تیرے اور اس کے درمیان دشمنی ہے گویا کہ وہ اب گہرا دوست ہے۔‘‘\nلیکن دشمنی کو محبت کے ساتھ بدلنا مشکل ہو تو پھر برائی کا بدلہ برائی سے دینا درست ہے لیکن زیادتی سے بچاؤ اختیار کیاجائے جیسا کہ بنو نضیر کے ساتھ آپ نے بالآخر لڑائی کی اور انہیں ان کے گھروں سے جلاوطن کر دیا جب انہوں نے عہد کا خیال نہ کیا خیانت پر اُتر آئے بلکہ آپ صلی اللہ علیہ وسلم کے دشمنوں کا ساتھ دیا قریش مکہ اور پورے اہل عرب کے تعاون میں انہوں نے مضبوط پارٹ ادا کیا اس کے بعد صرف ایک ہی علاج تھا کہ انہیں ملک سے جلاوطن کیا جائے۔ خلاصہ یہ ہے کہ اللہ تعالیٰ نے تمہاری راہنمائی فرما دی ہے کہ تم اپنے دشمن کے حملہ سے محفوظ رہ سکتے ہو جب تم احکام الٰہیہ کے مطابق زندگی بسر کرو۔ اس حقیقت پر تمہارا ایمان ہو کہ اللہ پاک نے ان کے اعمال کا احاطہ کیا ہوا ہے اور اللہ پاک اس بات پر بھی قادر ہے کہ وہ ان کے ارادوں کو ختم کر دے پس اللہ تعالیٰ کی ذات پر ہی اعتماد کرو اور اسی پر توکل رکھو۔ (تفسیر مراغی : 48/2)\n﴿وَاِذْ غَدَوْتَ مِنْ اَهْلِكَ تُبَوِّئُ الْمُؤْمِنِيْنَ مَقَاعِدَ لِلْقِتَالِؕ وَاللّٰهُ سَمِيْعٌ عَلِيْمٌۙ۰۰۱۲۱ اِذْ هَمَّتْ طَّآىِٕفَتٰنِ مِنْكُمْ اَنْ تَفْشَلَاۙ وَاللّٰهُ وَلِيُّهُمَاؕ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُوْنَ۰۰۱۲۲ وَلَقَدْ نَصَرَكُمُ اللّٰهُ بِبَدْرٍ وَّاَنْتُمْ اَذِلَّةٌۚ فَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تَشْكُرُوْنَ۰۰۱۲۳﴾\nاور (اے نبی علیہ السلام! یاد کریں) جب آپ صبح سویرے اپنے گھر والوں سے روانہ ہوئے اور مومنوں کو جنگ (احد) کے لیے مورچوں پر بٹھا رہے تھے اور اللہ خوب سننے والا، خوب جاننے والا ہے جب تمہارے دو گروہوں نے کم ہمتی دکھانے کا ارادہ کیا اور اللہ ان کا دوست تھا، اور مومنوں کو اللہ ہی پر بھروسہ کرنا چاہیے\nاور اللہ نے بدر میں عین اس وقت تمہاری مدد کی جب تم\nکمزور تھے۔ پس تم اللہ سے ڈرو تاکہ تمہیں شکر ادا کرنے کی توفیق ہو"],[864,"§غزوۂ اُحد کا بیان\nان آیات میں مذکور اس واقعے سے مراد جمہور مفسرین کے نزدیک غزوۂ اُحد ہے، حضرت ابن عباس رضی اللہ عنہما، امام حسن بصری، قتادہ، سُدی رحمہ اللہ اور کئی ایک ائمہ کا یہی قول ہے۔(تفسیر ابن أبی حاتم : 748/3) غزوۂ اُحد کا یہ واقعہ ہفتے کے دن 3ہجر ی میں پیش آیا اور بقول عکرمہ رحمہ اللہ یہ ہفتے کے دن نصف شوال کو پیش آیا تھا۔واللہ أَعلَم.(البدایۃ والنہایۃ: 10/4 والدرالمنثور : 119/2) اس کا سبب یہ تھا کہ جنگ بدر میں بہت سے مشرک سردار تو مار ے گئے مگر وہ تجارتی قافلہ جو ابو سفیان کی سربراہی میں آرہا تھا، بچ نکلنے میں کامیاب ہو گیا اور جب وہ مکہ میں پہنچا تو مقتول سرداروں کے بیٹوں اور زندہ بچ جانے والے سرداروں نے ابو سفیان سے کہا کہ ان اموال کو محمد صلی اللہ علیہ وسلم سے جنگ کرنے کے لیے وقف کر دو، چنانچہ انہوں نے مزید اموال اور لشکروں کو جمع کیا اور تین ہزار افراد پر مشتمل اس لشکر نے مدینہ کی جانب اُحد پہاڑ کے قریب آکر پڑاؤ ڈال دیا۔\nرسول اللہ صلی اللہ علیہ وسلم نے نماز جمعہ ادا فرمائی اور نماز جمعہ کے بعد بنو نجار کے ایک شخص مالک بن عمرو رضی اللہ عنہ کی نماز جنازہ پڑھائی، پھر لوگوں سے مشورہ کیا کہ ان لوگوں کا شہر سے باہر نکل کر یا مدینہ میں رہ کر ہی مقابلہ کریں۔ عبداللہ بن اُبی (رئیس المنافقین) کی رائے یہ تھی کہ مدینہ کے اندر رہ کر ہی مقابلہ کیا جائے۔ اگر وہ یہاں مقیم ہوئے تو بدترین قید سے دو چار ہوں گے، اگر وہ مدینہ میں داخل ہوئے تو مرودان کا دوبدو مقابلہ کریں گے اور عورتیں اور بچے اوپر سے ان پر پتھر برسائیں گے اور اگر وہ لوٹ گئے توناکام ونامراد ہوکر لوٹیں گے، اس کے برعکس دیگر صحابہ کرام رضی اللہ عنہم خصوصاً جو غزوۂ بدر میں شرکت نہ کرسکے تھے، ان کی رائے یہ تھی کہ شہرسے باہر نکل کر ان کا مقابلہ کیا جائے۔\nرسول اللہ صلی اللہ علیہ وسلم اندر کا شانۂ نبوت میں تشریف لے گئے اور آپ صلی اللہ علیہ وسلم نے زرہ کو پہنااور باہر تشریف لے آئے، بعض صحابہ کرام رضی اللہ عنہم نے ندامت محسوس کی اور سوچا شاید ہم نے رسول اللہ صلی اللہ علیہ وسلم کوباہر نکلنے کے لیے مجبور کر دیا ہے، اس لیے انہوں نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم ! اگر آپ صلی اللہ علیہ وسلم پسند فرمائیں تو شہر کے اندر ہی رہ کر ان کا مقابلہ کریں گے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’کسی نبی کے یہ شایان شان نہیں کہ جب وہ زرہ پہن لے اللہ تعالیٰ کے (اس کے اور اس کے دشمنوں کے درمیان) فیصلہ فرمانے سے قبل ہی اسے اُتار دے۔‘‘ (الدرالمنثور : 121/2)\nرسول اللہ صلی اللہ علیہ وسلم اپنے ایک ہزار ساتھیوں کے ہمراہ چلے اور جب مقام شَوْط پر پہنچے تو عبداللہ بن اُبی (رئی المنافقین) اس بات پرناراضی کا اظہار کرتے ہوئے کہ اس کی رائے کو نہیں ما نا گیا، لشکر کے ایک تہائی حصے کو لے کر واپس مدینہ چلا گیا۔ اس نے اور اس کے ساتھیوں نے یہ بھی کہا کہ اگر ہمیں یہ معلوم ہو کہ آج لڑائی ہوگی تو ہم ضرور تمہارا ساتھ دیتے لیکن ہمارا خیال ہے کہ آج تم نہیں لڑوگے۔ بہر آئینہ رسول اللہ صلی اللہ علیہ وسلم سوئے منزل کشاں کشاں تشریف لے جا رہے تھے حتی کہ آپ صلی اللہ علیہ وسلم وادی کے ناکے میں اُحد کی گھاٹی کے پاس فروکش ہو گئے۔ آپ صلی اللہ علیہ وسلم نے اپنی پشت مبارک اور لشکر کی پشت اُحد کی طرف کرلی اور فرمایا: «لَايُقَاتِلَنَّ أَحَدٌ حَتّٰى نَأْمُرَهُ بِالْقِتَالِ»’’ اس وقت تک تم میں سے کوئی بھی لڑائی شروع نہ کرے جب تک ہم لڑائی کا حکم نہ دے دیں۔‘‘ (السیرۃ النبویۃ لابن ہشام، غزوۃ أحد : 69/3)\nرسول اللہ صلی اللہ علیہ وسلم اپنے سات سو جانثار صحابہ کرام رضی اللہ عنہم کے ساتھ لڑائی کے لیے تیار ہو گئے۔ آپ صلی اللہ علیہ وسلم نے تیر اندازوں کا امیر عبداللہ بن جبیر رضی اللہ عنہ کو قرار دیا جن کا تعلق بنو عمرو بن عوف سے تھا، اس میں تیر اندازوں کی کل تعداد پچاس تھی،آپ نے فرمایا:’’تم دشمن کو تیروں کے ذریعے سے ہم سے دور رکھو، پشت کی طرف سے ہماری حفاظت کرتے رہو تاکہ دشمن عقب سے حملہ آور نہ ہو سکے، خواہ ہمیں فتح ہو یا شکست، تمہیں اسی جگہ رہنا ہے اور اسے ہر گز نہیں چھوڑنا، خواہ تم پرندوں کو دیکھو کہ وہ ہمیں اچک کر لے جارہے ہیں تو تمہیں پھر بھی اسی جگہ پر کھڑے رہنا ہے اور یہاں سے نہیں ہلنا۔ ‘‘(صحیح البخاری: 3039 و مسند أحمد)\nنبی اکرم صلی اللہ علیہ وسلم نے دوزِرہیں زیب تن فرمائی ہوئی تھیں، پرچم آپ صلی اللہ علیہ وسلم نے خاندان عبدالدار کے فرزند مصعب بن عمیر رضی اللہ عنہ کو عطا فرمایا، اس دن آپ صلی اللہ علیہ وسلم نے بعض نوخیز لیکن تنو مندصحابہ کرام رضی اللہ عنہم کو تو اجازت دے دی تھی لیکن بعض کم سن لڑکوں کولڑائی میں شرکت کی اجازت نہیں دی تھی، انہیں آپ صلی اللہ علیہ وسلم نے اس سے دو سال بعد غزوۂ خندق کے موقع پر اجازت عطافرمادی تھی۔ قریش نے بھی اپنے لشکرکو جو تین ہزار افراد پر مشتمل تھا، ترتیب دیا، ان کے پاس دو سو گھوڑے بھی تھے، انہوں نے شہسواروں کے میمنہ پر خالد بن ولید اور میسرہ پر عکرمہ بن ابوجہل کو متعین کیا اور اپنا پرچم خاندان عبدالدار کے لوگوں کے سپرد کیا، پھر مسلمانوں اور کافروں کی ان جماعتوں کے مابین جو واقعات رونما ہوئے، ان کی تفصیل ان آیات کی تفسیر کے دوران میں اپنے اپنے مقام پر بیان کی جائے گی۔(دلائل النبوۃ للبیہقی : 206/2، صحیح البخاری : 36/2، البدایۃ والنہایۃ : 16/4) إِنْ شَائَ اللهُ تَعَالٰى.\nاللہ تعالیٰ نے فرمایا ہے : ﴿وَاِذْ غَدَوْتَ مِنْ اَهْلِكَ تُبَوِّئُ الْمُؤْمِنِيْنَ مَقَاعِدَ لِلْقِتَالِؕ﴾ ’’اور (اس وقت کو یاد کریں) جب آپ صبح کو اپنے گھرسے روانہ ہو کر ایمان والوں کو لڑائی کے لیے مورچوں پر (موقع بموقع) متعین کرنے لگے۔‘‘یعنی آپ انہیں ان کے مورچوں پر متعین کرنے لگے اورمیمنہ ومیسرہ پر انہیں مقرر کرنے لگے تھے۔ ﴿وَاللّٰهُ سَمِيْعٌ عَلِيْمٌۙ۰۰۱۲۱﴾ ’’اور اللہ سب کچھ سنتا (اور) جانتا ہے۔‘‘ وہ تمہاری باتوں کو سنتا اور تمھارےضمیر میں جو کچھ تھا، اسے خوب جانتا تھا۔\nارشادربانی ہے : ﴿اِذْ هَمَّتْ طَّآىِٕفَتٰنِ مِنْكُمْ اَنْ تَفْشَلَاۙ﴾ ’’اس وقت تم میں سے دو جماعتوں نے جی چھوڑ دینا چاہا۔‘‘ امام بخاری رحمہ اللہ نے حضرت جابر بن عبداللہ رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ ان دو جماعتوں سے ہم، یعنی بنو حارثہ اور بنو سلمہ مراد ہیں اور ہم اس بات کو پسند نہیں کرتے، اس حدیث کی سند کے ایک راوی سفیان نے ایک بار یہ کہا: (جابر بن عبداللہ رضی اللہ عنہما نے یہ کہا) کہ مجھے یہ بات پسند نہیں کہ یہ آیت نازل ہوتی کیونکہ اسی میں یہ فرمان باری تعالیٰ بھی موجود ہے:﴿وَاللّٰهُ وَلِيُّهُمَاؕ﴾ ’’اور اللہ ان کا مددگار تھا۔‘‘(صحیح البخاری : 4558) امام مسلم نے بھی اسے بروایت سفیان بن عیینہ رحمہ اللہ ہی بیان کیا ہے۔ (صحیح مسلم : 2505)"],[865,"§تعداد اور سامان کی قلت کے باوجود بدر میں فتح نصرت\nارشاد باری تعالیٰ ہے:﴿وَلَقَدْ نَصَرَكُمُ اللّٰهُ بِبَدْرٍ﴾ ’’اور اللہ تعالیٰ جنگ بدر میں بھی تمہاری مدد کی تھی۔ ‘‘ غزوۂ بدر جمعے کے دن 17رمضان 2ہجری کو پیش آیا تھا۔(تفسیرالقرطبی : 190/4 والمصنف لابن أبی شیبۃ : 36642)یہی وہ یوم فرقان ہے جس میں اللہ تعالیٰ نے اسلام اور مسلمانوں کو عزت و سربلندی سے نوازا اور شرک اور مشرکوں کو تباہ و برباد کر دیا تھا، حالانکہ اس دن مسلمانوں کی تعداد بھی کم تھی اور وہ صرف تین سو تیرہ تھے(دلائل النبوۃ للبیہقی : 40/3، صحیح البخاری : 3957،3958) جن میں سے دو گھوڑوں پر اور ستر اونٹوں پر سوار تھے (دلائل النبوۃ للبیہقی : 39/3) اور باقی سب پیدل تھے، ان کے پاس حسب ضرورت سامان بھی نہیں تھا جبکہ اس دن دشمن کی تعداد نوسو سے لے کر ایک ہزار کے درمیان تھی۔ (دلائل النبوۃ للبیہقی : 43/3)\nدشمن ہر طرح کے سامان حرب اور کیل کانٹے سے لیس تھا۔ بہترین گھوڑے اس کے پاس تھے اور ضرورت کی تمام اشیاء اسے میسر تھیں مگر اللہ تعالیٰ نے اس سب کچھ کے باوجود اپنے رسول صلی اللہ علیہ وسلم کوعزت و سربلندی سے نوازا، اپنی وحی وتنزیل کو غلبہ عطا فرمایا، اپنے نبی صلی اللہ علیہ وسلم اور ان کے جان نثار رفقاء کو سرخرو کر دیا اور شیطان اور اس کے چیلوں کو ذلیل و خوار کر دیا۔ اسی لیے اللہ تعالیٰ نے اپنے ایمان دار اور بندگی شعار بندوں پر احسان جتلاتے ہوئے فرمایا: ﴿وَلَقَدْ نَصَرَكُمُ اللّٰهُ بِبَدْرٍ وَّاَنْتُمْ اَذِلَّةٌۚ﴾ ’’اور اللہ تعالیٰ نے جنگ بدر میں بھی تمہاری مدد کی تھی جب تم کمزور تھے۔‘‘ یعنی تمہاری تعداد بھی کم تھی تاکہ تم جان لو کہ فتح و نصرت صرف اور صرف اللہ تعالیٰ کے ہاتھ میں ہے، اس کا تعلق تعداد اور سامان کی کثرت سے نہیں ہے۔ اسی وجہ سے اللہ تعالیٰ نے ایک دوسری آیت میں فرمایا ہے : ﴿وَّيَوْمَ حُنَيْنٍۙ اِذْ اَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنْكُمْ شَيْـًٔا...تا... وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌ۰۰۲۷﴾ (التوبۃ:25-27) ’’اور (جنگ) حنین کے دن جبکہ تم کو اپنی (جماعت کی) کثرت پر غرور تھا تو وہ تمہارے کچھ بھی کام نہ آئی ....اور اللہ بہت بخشنے والا، نہایت رحم کرنے والا ہے۔‘‘ بدر، مکہ اور مدینہ کے درمیان ایک جگہ ہے جو اپنے کنویں کے نام سے معروف ہے اور یہ کنواں بدر بن نارین کی طرف منسوب ہے کیونکہ اسی نے اسے کھودا تھا۔ ﴿فَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تَشْكُرُوْنَ۰۰۱۲۳﴾ ’’پس تم اللہ سے ڈرو (اور ا س احسان کو یاد کرو) تاکہ تم شکر کرو۔‘‘ اور اس کی اطاعت بجا لاؤ۔\nیہ آیات واقعہ احد کے بارے میں نازل ہوئیں۔ اس کا قصہ معروف ہے جو سیرت اور تاریخ کی کتابوںمیں تفصیل سے بیان ہوا ہے۔ یہاں اسے بیان کرنے اور اس کے درمیان میں بدر کا واقعہ لے آنے میں غالباً یہ حکمت ہے کہ اللہ تعالیٰ نے مومنوں سے وعدہ کیا تھا کہ اگر وہ صبر اور تقویٰ اختیار کریں گے تو اللہ ان کی مدد کرے گا اور دشمن کی سازشوں سے انہیں محفوظ فرمائے گا۔ یہ ایک عام حکم اور سچا وعدہ تھا، جس کی شرائط پوری کی جاتیں تو اس کا پورا ہونا ناممکن نہیں تھا۔ ان دو قصوں میں اس کا ایک نمونہ پیش فرما دیا کہ اللہ نے بدر میں مسلمانوں کی مدد اس لیے فرمائی تھی کہ انہوں نے صبر کیا اور تقویٰ اختیار کیا، اور احد میں انہیں دشمنوں کے ہاتھوں اس لیے نقصان پہنچا کہ ان میں سے بعض افراد سے ایسی غلطی ہو گئی جو تقویٰ کے منافی تھی دونوں واقعات اکٹھے بیان کرنے کا یہ مقصد ہے کہ اللہ کو بندوں کا عمل پسند ہے کہ جب انہیں کوئی ناخوشگوار صورت حال پیش آجائے تو انہیں وہ نعمت یاد کرنی چاہیے جو انہیں پسند ہے، تو ان کی مصیبت ہلکی ہو جائے گی اور وہ اس بڑی نعمت کے مقابلے میں بہت معمولی محسوس ہوگی۔ اللہ نے اس آیت مبارکہ میں اسی حکمت کی طرف اشارہ کیا ہے۔ ﴿اَوَ لَمَّاۤ اَصَابَتْكُمْ مُّصِيْبَةٌ قَدْ اَصَبْتُمْ مِّثْلَيْهَاۙ﴾ (آل عمران : 165) ’’کیا بات ہے کہ جب تمہیں کوئی ایسی تکلیف پہنچی کہ تم اس جیسی دو چند پہنچا چکے۔‘‘\nواقعہ احد کا خلاصہ یہ ہے کہ جب 2ھ جنگ بدر کے بعد بچے کھچے مشرکین مکہ پہنچے، تو انہوں نے اپنی طاقت کے مطابق مال، افراد اور اسلحہ کے ساتھ بھرپور تیاری کی، حتی کہ اتنا کچھ جمع ہو گیاجس کی وجہ سے انہوںنے اپنا مقصود حاصل کرنے اور اپنا غصہ نکالنے کا پختہ ارادہ کر لیا۔ تب وہ تین ہزار جنگ جو افراد کا لشکر لے کر مکہ سے روانہ ہوئے اور مدینہ کے قریب آٹھہرے۔ نبی اکرم صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم سے مشورہ کیا، تو طے پایا کہ شہر سے باہر نکل کر مقابلہ کیا جائے۔نبی صلی اللہ علیہ وسلم ایک ہزار آدمی لے کر روانہ ہوئے۔ تھوڑا سا فاصلہ طے کرنے کے بعد عبداللہ بن اُبی (منافق) اپنے جیسے تین سو افراد لے کر واپس پلٹ گیا۔ اس طرح اسلامی لشکر کی تعداد میںایک تہائی مقدار کی کمی ہو گئی۔ مومنوں کے دو گروہ بھی پلٹ جانے کا سوچنے لگے۔ وہ بنوحارثہ اور بنوسلمہ کے قبائل تھے۔ اللہ نے انہیں ثابت قدمی عطا فرمائی۔ جب احد کے مقام پر پہنچے تو نبی صلی اللہ علیہ وسلم نے لشکر کو ترتیب دے کر ان کے مختلف دستے اپنے اپنے مقام پر متعین فرمائے۔ احد کا پہاڑ ان کی پشت کی طرف تھا۔ انہوں نے اپنی پیٹھیں احد کی طرف رکھیں۔ نبی صلی اللہ علیہ وسلم نے پچاس صحابہ کرام رضی اللہ عنہم کو احد کی ایک گھاٹی پر متعین فرمایا اور انہیں حکم دیا کہ وہیں ٹھہرے رہیں، اور وہ جگہ نہ چھوڑیں،تاکہ پیچھے سے دشمن کا خطرہ نہ رہے۔ جب مسلمانوں اور مشرکوں کے مابین جنگ ہوئی تو مشرکوں کو بری طرح شکست ہوئی، وہ اپنی لشکر گاہ کو چھوڑ گئے۔ مسلمانوں نے ان کا تعاقب کر کے انہیں قتل اور قید کرنا شروع کر دیا۔ جن تیز اندازوں کو نبی صلی اللہ علیہ وسلم نے پہاڑ پر متعین فرمایا تھا، جب انہوں نے یہ صورت حال دیکھی تو (انہوں نے سوچا کہ اب ہمارا فرض مکمل ہو گیا ہے۔ اس لیے) انہوں نے آپس میں کہا، غنیمت! غنیمت! ہم یہاں کیوں بیٹھے ہیں جبکہ مشرکین شکست کھا چکے ہیں۔ ان کے امیر سیدنا عبداللہ بن جبیر رضی اللہ عنہ نے انہیں نصیحت فرمائی کہ رسول اللہ صلی اللہ علیہ وسلم کی حکم عدولی نہ کریں۔ لیکن دوسروں نے اس طرف توجہ نہ دی۔ جب انہوں نے اپنی جگہ چھوڑ دی اور وہاں صرف چند افراد رہ گئے تو مشرکین کا گھڑ سوار دستہ اس گھاٹی سے آگیا اور مسلمانوں کے پیچھے آکر لشکر کے پچھلے دستے پر حملہ کر دیا۔ تب مسلمان کچھ ادھر ادھر ہوئے، جو اللہ کی طرف سے ایک آزمائش تھی۔ جس سےان کے گناہ معاف ہوئے، اور تعمیل حکم میں کوتاہی کی سزا مل گئی۔ اس کے نتیجے میں جن کی قسمت میں شہادت تھی، وہ شہید ہوگئے۔ آخر کار مسلمان جبل احد کی چوٹی کی طرف جمع ہو گئے اللہ نے مشرکین کے ہاتھوں کو روک دیا اور وہ لوگ اپنے وطن کی طرف لوٹ گئے۔ رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم مدینہ منورہ تشریف لے آئے۔\nاللہ تعالیٰ فرماتا ہے: ﴿وَاِذْ غَدَوْتَ مِنْ اَهْلِكَ﴾ ’’اور اس وقت کو یاد کرو جب آپ صلی اللہ علیہ وسلم اپنے گھر سے نکلے، اس مقام پر (غدوت) کا مطلب ’’مطلقا نکلنا ہے‘‘ صبح کے وقت نکلنا نہیں۔ کیونکہ نبی صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم جمعہ کی نماز پڑھ کر روانہ ہوئے تھے۔ ﴿تُبَوِّئُ الْمُؤْمِنِيْنَ مَقَاعِدَ لِلْقِتَالِؕ﴾ ’’مومنوں کو میدان جنگ میں لڑائی کے مورچوںپر باقاعدہ بٹھا رہے تھے‘‘ یعنی آپ صلی اللہ علیہ وسلم انہیں ترتیب دے رہے تھے۔ اور ہر ایک کو اس مقام پر ٹھہرا رہےتھے جو اس کے لیے مناسب تھا۔ اس میں نبی صلی اللہ علیہ وسلم کی عظیم تعریف ہے۔ کہ آپ بنفس نفیس ان کو منظم فرما رہے تھے اور جنگ کے لیے مناسب مقامات پر ٹھہرا رہے تھے۔ا س کی وجہ آپ صلی اللہ علیہ وسلم کے علم و فراست کا کمال، دور اندیشی اور بلند ہمتی تھی۔ علاوہ ازیں آپ صلی اللہ علیہ وسلم کامل شجاعت سے بہرہ ور تھے، صلوات اللہ وسلامہ علیہ ﴿وَاللّٰهُ سَمِيْعٌ عَلِيْمٌۙ۰۰۱۲۱﴾ ’’اور اللہ (خوب) سننے والا، (ہر چیز کو) جاننے والا ہے‘‘ جو ہر بات سنتا ہے۔ مومنوں کی باتیں بھی سنتا ہےا ور منافقوں کی بھی۔ ہر ایک کی بات چیت سے اس کے دل سے جذبات، احساسات اور خیالات ظاہر ہوتے ہیں۔ وہ بندوں کی نیتوں کو جانتا ہے، وہ ان کے مطابق انہیں مکمل بدلہ عطا فرماتا ہے۔ علاوہ ازیں یہ مطلب بھی ہے کہ وہ سننے والا جاننے والا ہے۔ تمہاری حفاظت کرتا ہے۔ تمہارے معاملات سنوارتا ہے۔ اور تمہیں اپنی مدد سے نوازتا ہے۔ اللہ تعالیٰ نے موسیٰ علیہ السلام اور ہارون علیہ السلام سے بھی اسی طرح فرمایا تھا۔ ﴿اِنَّنِيْ مَعَكُمَاۤ اَسْمَعُ وَاَرٰى۰۰۴۶﴾ (طٰہ : 46)’’میں تمہارے ساتھ ہوں، اور سنتا اور دیکھتا ہوں۔‘‘\nاللہ تعالیٰ کی مومنوں پر مہربانی اور احسان اس طرح بھی ہوا کہ ﴿اِذْ هَمَّتْ طَّآىِٕفَتٰنِ﴾ جب مومنوں کی دو جماعتیں پست ہمتی کا ارادہ کر چکی تھیں، اوروہ بنو سلمہ اور بنو حارثہ تھے، جیسے پہلے بیان ہوا۔ اللہ نے ان پر اور تمام مومنوں پر احسان کرتے ہوئے انہیں ثابت قدمی کی توفیق بخشی۔ اس لیے فرمایا: ﴿وَاللّٰهُ وَلِيُّهُمَاؕ﴾ ’’اللہ ان کا ولی اور مددگار ہے‘‘ یہاں اللہ تعالیٰ کی خاص ولایت مراد ہے یعنی اس کی اپنے دوستوں پر مہربانی، انہیں ایسے کاموں کی توفیق دینا جن میں ان کا فائدہ ہو، اور ایسے کاموں سے محفوظ رکھنا، جن میں ان کا نقصان ہو۔ اس کا ایک مظہر یہ بھی تھا کہ جب انہوں نے اس گناہ کا ارادہ کیا کہ وہ پست ہمتی کا مظاہرہ کرتے ہوئے میدان جنگ سے چلے جائیںاور نبی صلی اللہ علیہ وسلم کو چھوڑ کر بھاگ جائیں تو اللہ تعالیٰ نے انہیں اس غلطی سے بچا لیا، کیونکہ ان میں ایمان موجود تھا۔ جیسے اللہ تعالیٰ کا ارشاد ہے: ﴿اَللّٰهُ وَلِيُّ الَّذِيْنَ اٰمَنُوْا يُخْرِجُهُمْ مِّنَ الظُّلُمٰتِ اِلَى النُّوْرِ࣢ؕ﴾ (البقرہ : 257) ’’اللہ مومنوں کا دوست اور مددگار ہے،انہیں اندھیروں سے روشنی کی طرف نکال لاتا ہے۔‘‘ اس کے بعد فرمایا: ﴿وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُوْنَ﴾ ’’اور اللہ ہی کی ذا ت پر مومنوں کو بھروسا کرنا چاہیے‘‘ اس میں توکل کا حکم ہے۔ توکل کا مطلب یہ ہے کہ فائدہ مند اشیاء کے حصول کے لیے اور نقصان سے بچنے کے لیے اللہ پر اعتماد کرتے ہوئے دل کا سہارا اللہ پر ہو۔ بندے کو اللہ پر جتنا ایمان ہوتا ہے، اس کے مطابق اس کا توکل ہوتا ہے۔ اس آیت میں یہ اشارہ بھی ہے کہ دوسروں کی نسبت مومن اللہ پر توکل کرنے کا زیادہ حق رکھتے ہیں۔ بالخصوص سختی اور جہاد کے موقع پر انہیں اللہ پر توکل کرنا، اس سے مدد اور فتح طلب کرنا، اپنی طاقت پر بالکل بھروسا نہ کرنا، بلکہ اللہ کی قوت اور حفاظت پر بھروسا کرنا انتہائی ضروری ہے۔ اللہ تعالیٰ اس کی برکت سے ان کی مدد کرتا ہے اور ان کی مصیبتیں اور مشکلات دور فرماتا ہے۔\nغزوات کے مؤرخین اور جمہور علماء کی رائے ہے کہ یہ آیت واقعہ اُحد کے بارے میں نازل ہوئی ہے اور اس واقعہ کے ساتھ غزوۂ بدر کے ذکر کرنے کا مقصد یہ بتانا ہے کہ فتح و نصرت اور شکست و ناکامی کے باب میں نظام الٰہی یہ ہے کہ صبر و تقویٰ کا نتیجہ نصرت، کامیابی ہوتی ہے، اور بے صبری اور عدم تقویٰ کا لازمی نتیجہ شکست و ناکامی ہوتی ہے۔ اور اس کی مثال مسلمانوں کا ماضی قریب ہے، کہ میدان اُحد میں بے صبری اور حرصِ دنیا کا ثبوت دیا تو فتح کے بعد شکست کا منہ دیکھنا پڑا۔ اور ان کے دشمنوں نے خوشی کے نغمے گائے۔ اور میدانِ بدر میں صبر و شکیب کا ثبوت دیا اور تقویٰ اور تعلق باللہ کی راہ پر گامزن رہے تو اللہ تعالیٰ نے انھیں فتح یاب کیا، اور ان کے ستر (70) بڑے بڑے دشمن مارے گئے اور ستر (70) قیدی بنے۔ اور غنیمت کا بہت سامال ان کے ہاتھ آیا۔ اس آیت سے جنگ اُحد کے واقعہ کی ابتداہوتی ہے۔ اور تقریباً ساٹھ آیتوں میں اس کی تفصیل بیان کی گئی ہے۔ یہ واقعہ شوال ۳ھ میں وقوع پذیر ہوا، اور اس کا سبب یہ تھا کہ جنگِ بدر میں جب قریش کے سرداران مارے گئے، اور رسوا کن شکست سے دو چار ہوئے۔ تو مسلمانوںسے انتقام لینے کے لیے کفارِ قریش ابو سفیان کی قیادت میں تین ہزار کی تعداد میں جبل اُحد کے قریب آکر جمع ہوگئے۔ نبی کریم صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم سے مشورہ کیا کہ مدینہ میں رہ کر ہی دفاع کیا جائے۔ یاباہر نکل کر مقابلہ کیا جائے، کچھ لوگوں کی پہلی رائے تھی۔ عبداللہ بن اُبی بن سلول رائیس المنافقین کی بھی یہی رائے تھی۔ کچھ نوجوان اور پر جوش صحابہ کی رائے دوسری تھی، اور اس پر انھوں نے اصرار کیا۔ نبی کریم صلی اللہ علیہ وسلم اسی دوسری رائے کے مطابق گھر کے اندر تشریف لے گئے، اور زرہ پہن کر باہر آگئے۔ دوسری رائے والے صحابہ نے سمجھا کہ شاید ہم نے رسول اللہ صلی اللہ علیہ وسلم کو مجبور کیا ہے، اس لیے انھوں نے آپ سے کہا کہ اگر آپ چاہیں تو پہلی رائے پر عمل کریں۔ تو آپ نے فرمایا کہ اللہ کا نبی جب زرہ پہن کر گھر سے باہرآجاتا ہے تو اسےاس وقت تک نہیں اُتارتا جب تک اس کے اور اس کے دشمن کے درمیان اللہ تعالیٰ فیصلہ نہ کردے۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم ایک ہزار لشکر کے ساتھ جمعہ کے بعد جبل اُحد کی طرف روانہ ہو گئے۔ عبداللہ بن اُبی مقام ”شوط“ سے اپنے تین سو افراد کے ساتھ یہ بہانا بنا کر واپس آگیا کہ ہماری بات نہیں مانی گئی۔\nجنگ ہوئی اور مسلمانوں کو فتح ہوئی، لیکن جن تیر اندازوں کو رسول اللہ صلی اللہ علیہ وسلم نے جبل اُحد پر مقرر کیا تھا اور کہا تھا کہ اگر ہمیں چڑیاں بھی اُچک کر لے جائیں تو بھی اپنی جگہ نہ چھوڑنا، انھوں نے مالِ غنیمت لوٹنے کے لیے اپنی جگہ چھوڑدی، اور خالد بن ولید نے اُس طر ف سے حملہ کر دیا، اور مسلمانوں کی فتح شکست میں بدل گئی۔ (تفصیل کے لیے دیکھئے زاد المعاد، ابن القیم رحمہ اللہ)\nبعض لوگوں نے ”عدوت“کا معنی ”صبح کے وقت نکلنا“ کیا ہے، اور پھر یہ اشکال پیدا کیا ہے کہ پھر یہ کیسے صحیح ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ کے بعد نکلے۔ صاحب ِ فتح البیان نے لکھا ہے کہ بسااوقات ”عدو“مطلق خروج کے معنی میں استعمال ہوتا ہے، یہاں بھی ”عدوت“ ”حرجت“کے معنی میں ہے۔ اس لیے اشکال باقی نہیں رہتا۔"],[866,"§غزوہ اُحدکا پس منظر اوراسباب\nیہاں سے ایک نیا مضمون شروع ہو رہا ہے جو جنگ اُحد سے متعلق ہے۔ رمضان 2ھ میں غزوہ بدر میں قریش مکہ کو عبرت ناک شکست ہوئی تھی۔ ابو جہل کی موت کے بعد ابو سفیان نے قریش کی قیادت سنبھالی۔ اس نے جنگ بدر کا بدلہ لینے اور مسلمانوں کا قلع قمع کرنے کے لیے حسب ذیل اقدامات کیے: (1) طے ہوا کہ اس تجارتی قافلہ کا سارا منافع جنگ کے اخراجات کے لیے دے دیا جائے جو جنگ بدر سے چند یوم پہلے بچ بچا کر نکل آیا تھا۔ اس سے ایک ہزار اُونٹ اور پچاس ہزار دینار کی خطیر رقم جنگی اخراجات کے لیے جمع ہو گئی۔ (2) رضا کارانہ خدمت کا دورزہ کھول دیا گیا اور تمام اسلام دشمن قبائل کو اس جنگ میں شمولیت کی دعوت دی گئی۔ اس طرح قریش کے حلیف قبیلے بھی اور مسلمانوں کے مخالف قبیلے بھی اس قریشی جھنڈے تلے جمع ہوگئے۔ (3) دوشعلہ بیان شعراء کی خدمات حاصل کی گئیں،جو بدوی قبائل کو مسلمانوں کے خلاف انتقام پر بھڑکاتے تھے۔ ان ایام میں جنگی پروپیگنڈہ کا سب سے موثر ذریعہ یہی تھا۔ چنانچہ شوال 3ھ میں قریش کا یہ تین ہزار مسلح افراد کا لشکر جرار ابو سفیان کی سرکردگی میں اُحد کے میدان میں پہنچ گیا۔ اس موقع پر ابو سفیان نے ایک خطرناک جنگی چال چلی، وہ انصار سے مخاطب ہو کر کہنے لگا: آپ لوگوںسے ہماری کوئی لڑائی نہیں، آپ درمیان سے نکل جائیں تو بہتر ہے، ہم بھی آپ سے کوئی تعرض نہ کریں گے۔ لیکن انصار ابو سفیان کی اس چال کو سمجھ گئے اور اسے کھری کھری سنادیں۔"],[867,"§غزوۂ اُحد سے متعلق مشورہ\nرسول اللہ صلی اللہ علیہ وسلم نے صحابہ رضی اللہ عنہم سے مشورہ کیا کہ یہ جنگ مدینہ میں رہ کر لڑی جائے یا باہر نکل کر کھلے میدان میں لڑی جائے۔ آپ صلی اللہ علیہ وسلم کی ذاتی رائے یہ تھی کہ مدینہ میں رہ کر لڑی جائے اور یہ پہلا موقع تھا کہ عبداللہ بن ابی رئیس المنافقین سے بھی رائے لی گئی جو حضور کی رائے سے موافق تھی۔ مگر پرجوش اور جوان مسلمان جنھیں بدر کی شرکت نصیب نہ ہوئی تھی اور شوق شہادت بے چین کر رہا تھا اس بات پر مصر ہوئے کہ باہر نکل کر کھلے میدان میں مقابلہ کیاجائے۔ تاکہ دشمن ہماری نسبت بزدلی اور کمزوری کا گمان نہ کرے۔ چنانچہ آپ صلی اللہ علیہ وسلم گھر میں تشریف لے گئے اور زرہ پہن کر نکلے۔بعض لوگوں کو خیال آیا کہ ہم نے آپ صلی اللہ علیہ وسلم کو آپ صلی اللہ علیہ وسلم کی مرضی کے خلاف باہر نکلنے پر مجبور کردیا ہے۔ چنانچہ انھوں نے کہا کہ یا رسول اللہ صلی اللہ علیہ وسلم! اگر آپ صلی اللہ علیہ وسلم کا منشاء نہ ہو تو یہیں تشریف رکھیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ایک پیغمبر کو یہ مناسب نہیں کہ وہ ہتھیار لگائے اور جنگ کیے بغیر اُتار دے۔"],[868,"§عبداللہ بن اُبی کا کردار\nجب آپ صلی اللہ علیہ وسلم مدینہ سے باہر نکلے تو تقریباً ایک ہزار آدمی آپ کے ساتھ تھے مگر عبداللہ بن اُبی تقریباً تین سو آدمیوں کو (جن میں بعض مسلمان بھی تھے) ساتھ لے کر راستہ سے یہ کہتا ہوا واپس چلا گیا کہ جب میرا مشورہ نہیں مانا گیا تو ہم کیوں لڑیں اور خواہ مخواہ اپنے آپ کو ہلاکت میں ڈالیں۔ آخر آپ صلی اللہ علیہ وسلم سات سو مجاہدین کا لشکر لےکر میدان جنگ میں پہنچ گئے۔ فوجی قاعدے کے مطابق صفیں ترتیب دیں۔ ہر ایک دستہ کو اس کے مناسب ٹھکانے پر بٹھایا اور فرمایا جب تک میں نہ کہوں جنگ نہ شروع کی جائے۔ جب عبداللہ بن اُبی تین سو ساتھیوں سمیت واپس چلا گیا تو انصار کے دو قبیلوں بنو حارثہ اور بنو سلمہ کےدلوں میں کمزوری واقع ہوئی اورکفار کے مقابلہ میں مسلمانوں کی قلیل تعداد دیکھ کر چھوڑنے لگے مگر چونکہ سچے مسلمان تھے۔ اس لیے اللہ تعالیٰ نے ان کے دلوں کو مضبوط کر دیا چنانچہ سیدنا جابر بن عبداللہ انصاری کہتے ہیں کہ یہ آیت کریمہ ہم انصار کے حق میں اُتری۔ اگرچہ اس میں ہمارا عیب بیان کیا گیا ہے۔ تاہم ہمیں یہ پسند نہیں کہ یہ آیت نازل نہ ہوتی۔ کیونکہ اس میں ﴿اللّٰهُ وَلِيُّهُمَا﴾”اور اللہ دونوں فرقوں کا مددگارتھا“ کے الفاظ بھی مذکور ہیں۔ (بخاری، کتاب التفسیر)\nاولاً:اس حقیقت کو ذہن نشین فرمائیں کہ جب نبی صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے صحابہ کرام رضی اللہ عنہم مدینۃ الرسول کی جانب ہجرت فرما ہوئے تواس واقعہ سے قریش مکہ سخت ناراض ہوئے بلکہ جن لوگوں نے انہیں اپنے شہر میں رہائش کی سہولت عطا کی ان کے خلاف وہ سخت طیش میں آئے بلکہ انہیں ڈرانے دھمکانے کے اسباب کو مہیا کیا ان حالات میں مدینۃ الرسول میں آباد لوگوں کے لیے ضروری تھا کہ وہ اپنی حفاظت کے لیے دفاع کا انتظام کرتے رسول اکرم صلی اللہ علیہ وسلم دین اسلام کے داعی اور لیڈر تھے بلکہ مدینۃ الرسول میں آباد لوگوں کے سربراہ اور لیڈر تھے چنانچہ دفاع کے نتیجہ میں مسلسل لڑائیوں کا آغاز ہوا نتیجتاً اس عرصہ میں اسلام جس سرعت اور تیزی کے ساتھ پھیلا تاریخ میں اس کی مثال نہیں ملتی ہے تو بعض جنگیں ایسی ہیں جن میں نبی صلی اللہ علیہ وسلم بنفس نفیس شریک ہوئے ان میں مشہور جنگ بدر اور جنگ اُحد ہے۔"],[869,"§جنگ بدر کا مختصر تذکرہ\nقریش مکہ اس خام خیالی میں مبتلا تھے کہ محمد صلی اللہ علیہ وسلم اور ا س کے پیروکارہنگامہ خیز لوگ ہیں ان کو صفحہ ہستی سے مٹانا ضروری ہے بالخصوص جب کہ مدینہ میں ان کی قوت کا شہرہ بپا ہے شام کے ملک کی جانب تجارت کی غرض سے جانے والے لوگوں کے راستہ میں اس کا محل وقوع ہے مکہ سے شام کی جانب روانہ ہونے والے قافلوں کے لوٹنے اور ان پر حملہ آور ہونے کا انہوں نے پروگرام بنایا چنانچہ ہجرت سے دوسرے سال ان کی پہلی کوشش جنگ بدر کی شکل میں کامیابی سے ہمکنار ہوئی۔ جنگ بدر کے نتیجہ میں مسلمانوں کو قوت حاصل ہوئی وہ کامیاب رہے جب کہ مشرکین مکہ عظیم شکست اور ناقابل فراموش حوادثات سے دوچار ہوئے کہ ان کے ستر افراد میدان جنگ میں مارے گئے اوراتنی ہی تعداد ان کے جنگ جُو بہادر قیدی بنے ان کی شکست فاش کا چرچا تمام عرب ممالک میںان کی ذلت اور ان کی عبرت کا سامان بنا۔ (المراغی : 51/4)"],[870,"§جنگ اُحد کا مفصل تذکرہ\nاُحد ایک پہاڑ کا نام ہے مدینۃ الرسول سے شمال کی جانب ایک میل کی مسافت پر واقع ہے اس پہاڑ کے بارے میں رسول اکرم صلی اللہ علیہ وسلم کا ارشاد گرامی ہے کہ اُحد پہاڑ ہم سے محبت کرتا ہے اور ہم اس کے ساتھ محبت کرتے ہیں۔(فتح الباری شرح بخاری : 377/7)\nجب مشرکین مکہ جنگ بدر میں شکست خوردہ رسوائی کی حالت میں مکہ مکرمہ کی جانب واپس لوٹے تو ابو سفیان نے مشرکین کو رسول اکرم صلی اللہ علیہ وسلم کے خلاف جمع کرنا شروع کر دیا اس لیے کہ قریش کے عظیم لیڈروں کے قتل کے بعد وہی سردار تھا۔ چنانچہ مشرکین پھر لڑائی کے لیے جمع ہوئے ان کی تعداد تین ہزار تھی ان میں سات صد افراد ذرہ پوش تھے نیز ان کے لشکر میں دو صد (سو) گھوڑے تھے ان کا لیڈر ابو سفیان تھا جب کہ اس سفر میں اس کے ساتھ اس کی بیوی ہندہ نامی تھی مجموعی طور پر عورتوں کی تعداد پندرہ تھی انہوں نے اپنے ساتھ دفیں اُٹھا رکھی تھیں وہ انہیں بجاتی تھیں اور بدر کے مقتولوں پر آہ فغاں کرتی تھیں اس طرح مشرکین کو مسلمانوں کے ساتھ جنگ کرنے پر اُکساتی تھیں۔ چنانچہ کفا رکے لشکر نے مکہ مکرمہ سے روانہ ہو کر شوال سن تین ہجری میں مدینہ کے بالمقابل اپنا کیمپ قائم کیا رسول اکرم صلی اللہ علیہ وسلم کا خیال تھا کہ مدینہ میں ہی قیام کیا جائے اور یہیں سے ان کے ساتھ لڑائی کی جائے جبکہ دیگر صحابہ کرام رضی اللہ عنہم کا خیال تھا کہ مدینہ سے باہر نکل کر ان کے ساتھ جنگ کی جائے آپ صلی اللہ علیہ وسلم کے ساتھ ایک ہزار صحابہ کرام رضی اللہ عنہم لشکر تھا آپ کا لشکر مدینہ اور اُحد کے درمیان تھا اس دوران عبداللہ بن ابی (رئیس المنافقین) اسلامی لشکر سے ایک تہائی فوج لے کر اپنے ساتھ ملا کر الگ ہوجاتا ہے۔ چنانچہ رسول اکرم صلی اللہ علیہ وسلم اپنے لشکر کے ساتھ اُحد پہاڑ کے دامن میں اُترتے ہیں لشکر کی پیٹھ اُحد پہاڑ کی جانب تھی کہ آپ صلی اللہ علیہ وسلم کے لشکر کی تعداد صرف سات صد تھی جن میں ایک صد کی تعداد زرہ پوش تھی جب کہ صرف دو گھوڑے تھے آپ صلی اللہ علیہ وسلم نے جھنڈا مصعب بن عمیر رضی اللہ عنہ کے سپرد کر رکھا تھا دوسری جانب مشرکین کے لشکر کی دائیں جانب پر کنٹرول خالد بن ولید رضی اللہ عنہ کا تھا اور بائیں جانب عکرمہ بن ابی جہل کا تھا اور جھنڈے کی حفاظت کا اہم کام بنو عبدالدار قبیلہ کے افراد کے پاس تھا جب دونوں لشکر آپس میں مڈبھیڑ ہوتے ہیں تو ابو سفیان کی بیوی ہند بنت عتبہ اپنی دیگر رفقاء کے ساتھ دف بجاتی ہوئیں ذیل کا گیت گا رہی تھیں :\nوَيْهًا بَنِي عَبدِ الدَّارِ وَيهًا حُمَاةَ\nالاَدْبَار ضَرْبًا بِكُلِّ بَتَّارٍ\n’’بنو عبدالدار قبیلہ کے لوگو! تم پر افسوس ہے شکست خوردہ لوگوں کی حفاظت کرنے والو! تم پر افسوس ہے تم تیز قاطع تلواروں کا وار مسلسل دشمن پر کیوں نہیں کر رہے ہو ‘‘ اس دوران سیدنا حمزہ رضی اللہ عنہ نے زور دار حملہ کرتے ہوئے اپنی مردانگی کے جوہر دکھلائے جب کہ مصعب بن عمیر رضی اللہ عنہ جن کے سپرد جھنڈا تھا اس نے دیوانگی کے عالم میں ایسا زبردست حملہ کیا کہ وہ شہید ہو گیا اس کی شہادت کی خبر سن کر آپ صلی اللہ علیہ وسلم نے حکم دیا کہ اب جھنڈا علی بن ابی طالب رضی اللہ عنہ کے سپرد کیا جائے۔ مشرکین کی شکست کے بعد جن تیر اندازوں کو اللہ تعالیٰ کے پیغمبر صلی اللہ علیہ وسلم نے حکم دیا تھا کہ ہمیں کامیابی حاصل ہو یا شکست ہو تم نے درہ خالی نہیں چھوڑنا لیکن انہوں نے حکم کی پاسداری نہ کی اور غنیمت لوٹنے میں مصروف ہو گئے۔ درہ خالی چھوڑ دیا موقع کو غنیمت سمجھ کر خالد بن ولید مسلمانوں کے لشکر کے عقب کی جانب سے اپنے لشکر کو لے کر مسلمانوں پر حملہ آور ہو ا لشکر میں شور وغوغا برپا ہو ا اس دوران سنا گیا کہ محمد صلی اللہ علیہ وسلم(معاذ اللہ) شہید ہو گئے ہیں مسلمان پسپا ہو گئے ہیں دشمن ان پر حملہ آور ہے اور ان کے تعاقب میں ہے حقیقت یہ ہے کہ اس روز مسلمانوں پر شدید آزمائش نازل ہوئی اس کے نتیجہ میں ستر صحابہ کرام رضی اللہ عنہم شہید ہو گئے جب کہ مشرکین کے مقتولین کی تعداد صرف بائیس افراد پر مشتمل تھی انتہا یہ ہوئی کہ دشمن کے حملہ سے رسول اکرم صلی اللہ علیہ وسلم بھی محفوظ نہ رہ سکے آپ صلی اللہ علیہ وسلم پر اس زور سے پتھروں کی بوچھاڑ کی گئی کہ آپ صلی اللہ علیہ وسلم زمین پر گرپڑے آپ صلی اللہ علیہ وسلم کا رباعیہ دانت ٹوٹ گیا آپ صلی اللہ علیہ وسلم کا چہرہ مبارک زخمی ہو گیا آپ صلی اللہ علیہ وسلم کے ہونٹ بھی زخمی ہو گئے اس دوران آپ صلی اللہ علیہ وسلم اپنے چہرے سے خون صاف فرما رہے تھے آپ صلی اللہ علیہ وسلم کی زبان پر یہ الفاظ تھے وہ لوگ کیسے فلاح حاصل کر سکتے ہیں جنہوں نے اپنے پیغمبر صلی اللہ علیہ وسلم کے چہرے کو خون آلود کر دیا ہے اس دوران آپ صلی اللہ علیہ وسلم انہیں اللہ پاک کی جانب دعوت دیتے رہے۔ ان حالات میں یہ آیت نازل ہوئی : ﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ اَوْ يَتُوْبَ عَلَيْهِمْ اَوْ يُعَذِّبَهُمْ فَاِنَّهُمْ ظٰلِمُوْنَ۰۰۱۲۸﴾ (آل عمران :128) ’’اس کام سے تجھے کچھ تعلق نہیں یا اللہ تعالیٰ ان پر مہربانی فرمائے یا اللہ تعالیٰ ان کو عذاب میں گرفتار کرے اس لیے کہ وہ ظالم ہیں۔‘‘\nاس دوران آپ کے خود مبارک کا ایک حلقہ رسول اللہ صلی اللہ علیہ وسلم کے رخ انور میں داخل ہو گیا۔ چنانچہ اس دوران ابو سعید خدری رضی اللہ عنہ کے والد مالک بن سنان رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کے رخسار مبارک سے خون کو چوسا اس عالم میں مشرکین آپ صلی اللہ علیہ وسلم کی وفات کے آرزو مند تھے لیکن اللہ پاک نے آپ صلی اللہ علیہ وسلم کو تحفظ عطا فرمایا ان کی آرزوکی تکمیل نہ ہو سکی۔ ارشاد باری ہے: ﴿وَاللّٰهُ يَعْصِمُكَ مِنَ النَّاسِؕ﴾ ’’اور اللہ آپ کو لوگوں (کے شر) سے بچائے گا‘‘ حفاظت کے دوران سیدنا طلحہ رضی اللہ عنہ کو تلوار کا زبردست وار لگا جس سے ان کا ہاتھ ناکارہ ہو گیا، ہند نامی عورت اور اس کے رفقاء عورتوں نے صحابہ کرام رضی اللہ عنہم کی لاشوں کا مثلہ کیا ناک کان کاٹ کر ان کو بصورت ہار پہنا جب کہ ہند نامی عورت کی قساوت قلبی ملاحظہ کریں کہ اس نے سیدنا حمزہ رضی اللہ عنہ کے جگر کو نکال کر اس کو چبایا بلکہ اس کو نگلنے کی کوشش کی لیکن وہ اس کے حلق سے نہ گزر سکا مزید برآں بربریت کا مظاہرہ کرتے ہوئے حمزہ رضی اللہ عنہ کی باچھوں میں نیزے کا کنارا گھونپ دیا پھر وہ اُحد پہاڑ پر بلند ہوا اور نہایت بلند آواز سے چیختے ہوئے کہا’’لڑائی کی مثال تو ڈول جیسی ہے ہم نے جنگ بدر کا بدلہ چکا دیا ہے۔‘‘ کعبہ کے بڑے بت ہبل کومخاطب کرتے ہوئے کہا ’’اب تو بلند ہے یعنی تیرا دین غالب ہے۔‘‘ آخر میں ابو سفیان نے واپس لوٹتے ہوئے اعلان کیا آئندہ سال تم سے بدر کے میدان میں مقابلہ ہوگا اس کی آوازسن کرنبی صلی اللہ علیہ وسلم نے حکم دیا تم اسے جواب دو ’’ہمیں تیری پیشکش منظور ہے اس وقت فیصلہ ہو جائےگا‘‘ اس کے بعد مشرکین مکہ کی جانب چل دیے۔ آپ صلی اللہ علیہ وسلم اپنے چچا حمزہ رضی اللہ عنہ کی لاش کی جانب تشریف لے گئے کیا دیکھتے ہیں اس کا پیٹ کٹا ہوا ہے ناک، کان بھی کٹے ہوئے ہیں اس کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا اگر مستقبل میں مجھے اللہ تعالیٰ نے کفار پر غلبہ دیا تو میں کفار کے تیس (30) آدمیوں کی لاشوں کا مثلہ کروں گا پھرآپ صلی اللہ علیہ وسلم نے لاش کو اس کی چادر کے ساتھ ڈھانپنے کا حکم دیا بعد ازاں آپ صلی اللہ علیہ وسلم نے اس پر نماز جنازہ سات تکبیرات کے ساتھ ادا کی۔ پھر دوسرے شہداء کی لاشوں کو لایا گیا ان کو حمزہ رضی اللہ عنہ کے پہلو میں ایک ایک کرکے رکھا گیا آپ صلی اللہ علیہ وسلم نے ان پر بہتر (72)مرتبہ نماز جنازہ ادا کی اسی کے ساتھ ہی حمزہ رضی اللہ عنہ کی تدفین کا حکم دیا کچھ صحابہ کرام رضی اللہ عنہم نے اپنے شہداء کو مدینہ لے جا کر دفن کیا پھر آپ صلی اللہ علیہ وسلم نے اس سے منع فرمایا آپ صلی اللہ علیہ وسلم نے حکم دیا کہ جہاں لوگ فوت ہوں وہیں ان کو دفن کیا جائے۔ اس واقعہ سے یہ حقیقت واضح ہو رہی ہے کہ نبی صلی اللہ علیہ وسلم کے حکم کی مخالفت کرنا سنگین نتائج پیدا کرتے ہیں۔ غزوۂ اُحد میں اسلامی لشکر کی شکست کا سبب یہ ہے کہ مجاہدین نے غنیمت سمیٹنے کا لالچ کیا اور جس درہ پر آپ صلی اللہ علیہ وسلم نے انہیں مقرر کیا تھا اس کو چھوڑ دیا۔ صرف دنیوی مال و متاع کے حصول کے لیے انہوں نے آپ صلی اللہ علیہ وسلم کے حکم کی خلاف ورزی کی اور پریشانی کا سامنا کرنا پڑا۔ (المراغی : 52/2-53)\nلیکن جنگ بدر میں اگرچہ تمہارے پاس جنگی سازوسامان تھا عددی قوت بھی دشمن کی عددی قوت سے بہت کم تھی پھر بھی اللہ تعالیٰ نے تمہیں فتح و نصرت سے نوازا اس لیے کہ تم نے صبر کے دامن کو خیر باد کہا اور برابر اس کوشش میں رہے کہ کہیں شکست کے اسباب بروئے کار نہ آجائیںتم نے خوب احتیاط سے کام لیا۔ نتیجتاً کفار کے ستر آدمی میدان کارزار میں کام آگئے اور ستر افرادکو قید کر لیا گیا اس کے ساتھ ساتھ بیش بہا مال غنیمت قبضہ میں آیا۔ اللہ نے اس احسان کا تذکرہ کرتے ہوئے فرمایا: کہ جنگ بدر میں اللہ تعالیٰ نے تمہیں غلبہ عطا فرمایا حالانکہ تم اپنے مقابل فریق سے سامانِ حرب اور عددی قوت کے لحاظ سے کمتر تھے اس کے نتیجہ میں اب تمہیں اللہ سے ڈرنا چاہیے تمہاری زندگی اللہ تعالیٰ اور اس کے رسو ل صلی اللہ علیہ وسلم کی اطاعت میں گزرنی چاہیے جب کہ جنگ اُحدمیں یہ اسلوب اختیار نہیں کیا کہ اللہ تعالیٰ نے جنگ اُحد میں تمہیں شکست سے دوچار کیا حالانکہ تم عددی اور مالی قوت کے لحاظ سے اس لائق تھے کہ تمہیں کامیابی حاصل ہوتی اس میں یہ حکمت کار فرما ہے کہ اللہ وصف حیاء کے ساتھ موصوف ہے وہ کریم ہے اس کا یہی تقاضا تھا کہ صرف غزوۂ اُحد کاتذکرہ فرمایا اب ان کی ذمہ داری ہے کہ وہ غور کریں کہ شکست کا سبب کیا ہے۔ ظاہر ہےشکست کا ایک سبب حکم کی اطاعت نہ کرنا اور دوسرا سبب صبر کے دامن کو چھوڑ ناہے۔ (ایسر التفاسیر : 209/1)\n﴿اِذْ تَقُوْلُ لِلْمُؤْمِنِيْنَ۠ اَلَنْ يَّكْفِيَكُمْ اَنْ يُّمِدَّكُمْ رَبُّكُمْ بِثَلٰثَةِ اٰلٰفٍ مِّنَ الْمَلٰٓىِٕكَةِ مُنْزَلِيْنَؕ۰۰۱۲۴ بَلٰۤىۙ اِنْ تَصْبِرُوْا وَتَتَّقُوْا وَيَاْتُوْكُمْ مِّنْ فَوْرِهِمْ هٰذَا يُمْدِدْكُمْ رَبُّكُمْ بِخَمْسَةِ اٰلٰفٍ مِّنَ الْمَلٰٓىِٕكَةِ مُسَوِّمِيْنَ۰۰۱۲۵ وَمَا جَعَلَهُ اللّٰهُ اِلَّا بُشْرٰى لَكُمْ وَلِتَطْمَىِٕنَّ قُلُوْبُكُمْ بِهٖؕ وَمَا النَّصْرُ اِلَّا مِنْ عِنْدِ اللّٰهِ الْعَزِيْزِ الْحَكِيْمِۙ۰۰۱۲۶ لِيَقْطَعَ طَرَفًا مِّنَ الَّذِيْنَ كَفَرُوْۤا اَوْ يَكْبِتَهُمْ فَيَنْقَلِبُوْا خَآىِٕبِيْنَ۰۰۱۲۷ لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ اَوْ يَتُوْبَ عَلَيْهِمْ اَوْ يُعَذِّبَهُمْ فَاِنَّهُمْ ظٰلِمُوْنَ۰۰۱۲۸ وَلِلّٰهِ مَا فِي السَّمٰوٰتِ وَمَا فِي الْاَرْضِؕ يَغْفِرُ لِمَنْ يَّشَآءُ وَيُعَذِّبُ مَنْ يَّشَآءُؕ وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌࣖ۰۰۱۲۹﴾\n(اے نبی صلی اللہ علیہ وسلم!) جب آپ مومنوں سے کہہ رہے تھے: کیا تمہارے لیے کافی نہ ہو گا کہ اللہ آسمان سے تین ہزار فرشتے اتار کر تمہاری مدد کرے؟\nکیوں نہیں! اگر تم صبر کرو اور اللہ سے ڈرتے رہو اور دشمن تم پر فوراً چڑھ آئے تو اسی لمحے تمہارا رب پانچ ہزار فرشتوں سے تمہاری مدد کرے گا جن کے (خاص) نشان لگے ہوں گے\nاور اللہ نے اسے تمہارے لیے خوشخبری بنا دیا، تاکہ اس سے تمہارے دلوں کو تسلی ہو۔ اور مدد تو اللہ ہی کی طرف سے ہوتی ہے جو بہت زبردست، نہایت حکمت والا ہے\nاللہ کا مقصد یہ تھا کہ وہ کافروں کے ایک گروہ کو ہلاک کر دے یا انہیں ذلیل کردے، پھر وہ نامراد ہو کر لوٹ جائیں\n(اے نبی صلی اللہ علیہ وسلم!) آپ کا اس معاملہ میں کچھ اختیار نہیں، اللہ چاہے تو ان کی توبہ قبول کرے، چاہے تو انہیں عذاب دے، کیونکہ وہ ظالم ہیں\nاور آسمانوں اور زمین میں جو کچھ ہے، اللہ ہی کا ہے، وہ جسے چاہتا ہے بخش دیتا ہے اور جسے چاہتا ہے عذاب دیتا ہے اور\nاللہ بہت بخشنے والا، بڑا مہربان ہے"],[871,"§فرشتوں کے ساتھ نصرت\nمفسرین کا اس وعدے کے بارے میں اختلاف ہے کہ یہ بدر کے دن سے متعلق ہے یا اُحد کے دن سے، اس سلسلے میں دو قول ہیں : (1)ان دونوں میں سے ایک قول یہ ہے کہ ارشاد باری تعالیٰ ہے :﴿اِذْ تَقُوْلُ لِلْمُؤْمِنِيْنَ۠﴾ ’’جب آپ صلی اللہ علیہ وسلم مومنوں سےیہ کہہ(کر ان کے دل بڑھا) رہے تھے۔ ‘‘ کا تعلق ﴿وَلَقَدْ نَصَرَكُمُ اللّٰهُ بِبَدْرٍ﴾ سے ہے، یہ قول امام حسن بصری، عامر شعبی، ربیع بن انس رحمہم اللہ اور دیگر کئی ائمہ تفسیر سے مروی ہے۔(تفسیر ابن أبی حاتم : 752/3) امام ابن جریر رحمہ اللہ نے بھی اسی قول کو اختیار کیا ہے۔(تفسیر الطبری : 108/4) عباد بن منصور رحمہ اللہ نے اس آیت: ﴿اِذْ تَقُوْلُ لِلْمُؤْمِنِيْنَ۠ اَلَنْ يَّكْفِيَكُمْ اَنْ يُّمِدَّكُمْ رَبُّكُمْ بِثَلٰثَةِ اٰلٰفٍ مِّنَ الْمَلٰٓىِٕكَةِ مُنْزَلِيْنَؕ۰۰۱۲۴﴾ سے متعلق امام حسن بصری رحمہ اللہ کا قول بیان کیا ہے کہ اس کا تعلق یوم بدر سے ہے۔(تفسیر ابن أبی حاتم : 752/3) اسے امام ابن ابو حاتم رحمہ اللہ نے روایت کیا ہے، پھر انہوں نے عامر شعبی رحمہ اللہ کی اس روایت کو بھی بیان کیا ہے کہ مسلمانوں کو بدر کے دن جب یہ خبرملی کہ كُرْز بن جابر مشرکوں کی مدد کر رہا ہے تو ان پر یہ بہت گراں گزری تو اس موقع پر اللہ تعالیٰ نے نازل فرمایا:﴿اَلَنْ يَّكْفِيَكُمْ اَنْ يُّمِدَّكُمْ رَبُّكُمْ بِثَلٰثَةِ اٰلٰفٍ مِّنَ الْمَلٰٓىِٕكَةِ مُنْزَلِيْنَؕ۰۰۱۲۴﴾ تا﴿ مُسَوِّمِيْنَ۰۰۱۲۵﴾ ’’کیا یہ کافی نہیں کہ تمہارا پروردگار تین ہزار فرشتے نازل کرکے تمہیں مدد دے ؟ ...جو (خاص) نشان والے ہوں گے۔ ‘‘ جب کرز کو یہ خبر پہنچی کہ مشرکوں کو شکست ہو گئی ہے تو اس نے ان کی مدد سے ہاتھ کھینچ لیا اور اللہ تعالیٰ نے بھی پانچ ہزار فرشتوں کو نازل نہیںفرمایا۔(تفسیر ابن أبی حاتم : 752/3)\nربیع بن انس رحمہ اللہ کا قول ہے کہ اللہ تعالیٰ نے مسلمانوں کو ایک ہزار فرشتوں سے مدد فرمائی، پھر فرشتوں کی تعداد تین ہزار ہو گئی اور اس کے بعد یہ تعداد پانچ ہزار ہو گئی تھی۔(تفسیر ابن أبی حاتم : 752/3)\nاگریہ کہا جائے کہ اس قول کی بنیاد پر اس آیت اور قصۂ بدر سے متعلق اس آیت میں تطبیق کس طرح ہوگی کہ :﴿اِذْ تَسْتَغِيْثُوْنَ۠ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ اَنِّيْ مُمِدُّكُمْ بِاَلْفٍ مِّنَ الْمَلٰٓىِٕكَةِ مُرْدِفِيْنَ۰۰۹﴾ (الانفال:9) ’’جب تم اپنے پروردگار سے فریاد کرتے تھے تو اس نے تمہاری دعا قبول کر لی (اور فرمایا : تسلی رکھو) کہ بے شک میں ایک ہزار فرشتوں سے، جو ایک دوسرے کے پیچھے آتے جائیں گے، تمہاری مدد کروں گا۔‘‘\nتو اس کا جواب یہ ہے کہ یہاں ایک ہزار کی تعداد کا مذکور ہونا تین ہزار یا ا س سے زیادہ تعداد کے منافی نہیں ہے کیونکہ ﴿مُرْدِفِيْنَ۰۰۹﴾ کے معنی یہ ہیں کہ وہ ایک دوسرے کے پیچھے آتے جائیں گے، پہلے آنے والے فرشتوں کے بعد کئی ہزار فرشتے اور آجائیں گے، یہ سیاق ایسے ہی ہے جیسے سورۂ آل عمران میں ہے اور بظاہر یہی معلوم ہوتا ہے کہ اس کا تعلق یوم بدر سے ہے کیونکہ مشہور بات یہی ہے کہ فرشتوں نے بدر کی لڑائی میں حصہ لیا تھا۔ واللہ اعلم\nاور فرمان الٰہی ہے : ﴿بَلٰۤىۙ اِنْ تَصْبِرُوْا وَتَتَّقُوْا﴾ ’’ہاں، اگر تم دل کو مضبوط رکھو اور (اللہ سے) ڈرتے رہو۔‘‘ یعنی دشمن سے مقابلے کے لیے صبر کرو گے، مجھ سے ڈرو گے اور میرے حکم کی اطاعت بجالاؤ گے۔ اور ارشاد باری تعالیٰ ہے:﴿وَيَاْتُوْكُمْ مِّنْ فَوْرِهِمْ هٰذَا﴾ ’’اور کافر تم پر جوش کے ساتھ دفعتاً حملہ کر دیں۔‘‘ امام حسن بصری، قتادہ، ربیع اور سُدی رحمہم اللہ فرماتے ہیں کہ وہ تم پر اپنے اسی ارادے سے حملہ کر دیں۔(تفسیر الطبری : 106/4 اور اس معنی میں کرز بن جابر کے اس لشکر کی طرف اشارہ ہے جو بدر کے دن مشرکین کی امدادکا ارادہ رکھتا تھا) عوفی نے حضرت ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ اپنے اس سفر میں وہ تم پر حملہ کر دیں۔(تفسیر الطبری : 107/4) اس کے یہ معنی بھی بیان کیے جاتے ہیں کہ وہ جوش و غضب میں آکر حملہ کر دیں۔(تفسیر الطبری : 107/4)\n(2)دوسرا قول یہ ہے کہ اس وعدے کا تعلق ارشاد باری تعالیٰ :﴿وَاِذْ غَدَوْتَ مِنْ اَهْلِكَ تُبَوِّئُ الْمُؤْمِنِيْنَ مَقَاعِدَ لِلْقِتَالِؕ﴾ (آل عمران:121) ’’اور (اے نبی صلی اللہ علیہ وسلم!) جب آپ صلی اللہ علیہ وسلم صبح سویرے اپنے گھر والوں سے روانہ ہوئے اور مومنوں کو جنگ (اُحد) کے لیے مورچوں پر بٹھا رہے تھے۔‘‘ سے ہے اور اس میں یوم احد کا ذکر ہے لیکن اس دن فرشتوں کے ذریعے سے امداد حاصل نہیں ہوئی تھی کیونکہ ارشاد باری تعالیٰ ہے :﴿بَلٰۤىۙ اِنْ تَصْبِرُوْا وَتَتَّقُوْا﴾ ’’ہاں، اگر تم دل کو مضبوط رکھو اور (اللہ سے) ڈرتے رہو۔ ‘‘ لیکن مسلمان صبر نہ کر سکے بلکہ بھا گ گئے جس کی وجہ سے ایک فرشتہ بھی ان کی مدد کے لیے نازل نہ ہوا۔\nارشاد باری تعالیٰ ہے : ﴿يُمْدِدْكُمْ رَبُّكُمْ بِخَمْسَةِ اٰلٰفٍ مِّنَ الْمَلٰٓىِٕكَةِ مُسَوِّمِيْنَ۰۰۱۲۵﴾ ’’تو تمہارا پروردگار پانچ ہزار فرشتے، جن پرنشان ہوں گے، تمہاری مدد کو بھیجے گا۔‘‘ یعنی علامات کے ساتھ ان پر نشان لگے ہوں گے۔ ابو اسحاق سبیعی رحمہ اللہ نے حارثہ بن مضرب رحمہ اللہ سے اور انہوں نے سیدنا علی بن ابو طالب رضی اللہ عنہ سے روایت کیا ہے کہ بدر کے دن فرشتوں کی نشانی سفید اونی لباس تھا۔ فرشتوں کے گھوڑوں کی پیشانیوں پر بھی نشان تھے۔(تفسیر ابن أبی حاتم : 754/3) مکحول کا قول یہ ہے کہ ان کے نشان یہ تھے کہ انہوں نے پگڑیاں باندھی ہوئی تھیں۔(تفسیر ابن أبی حاتم : 755/3) اور ان کی پگڑیاںسیاہ رنگ کی تھیں اور غزوۂ حنین کے دن ان کی پگڑیوں کا رنگ سرخ تھا۔(مجمع الزوائد : 10901، السیرۃ النبویۃ لابن ہشام : 633/2)حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ فرشتوں نے عملی طور پر صرف غزوۂ بدر ہی میں حصہ لیا تھا۔ (تفسیر الطبری : 102/4 والمصنف لابن أبی شیبۃ :36647) ابن ابو حاتم نے یحییٰ بن عباد سے روایت کیا ہے کہ سیدنا زبیر رضی اللہ عنہ نے بدر کے دن زرد رنگ کا عمامہ پہنا اور اس سے ڈھاٹا باندھا ہوا تھا تو فرشتے جب نازل ہوئے تو ان سب کے عمامے بھی زرد رنگ کے تھے۔\n(تفسیر ابن أبی حاتم : 755/3 والمستدرک للحاکم : 5554)\n﴿وَمَا جَعَلَهُ اللّٰهُ اِلَّا بُشْرٰى لَكُمْ وَلِتَطْمَىِٕنَّ قُلُوْبُكُمْ بِهٖؕ﴾ ’’اور اس مدد کو تو اللہ تعالیٰ نے تمہارے لیے (ذریعہ) بشارت بنایا تاکہ تمہارے دلوں کو اس سے تسلی ہو۔ ‘‘ یعنی اللہ تعالیٰ نے جو فرشتوں کو نازل فرمایا اور ان کے نازل ہونے کے بارے میں تمہیں بتادیا تو یہ تمہارے لیے بشارت تھی ورنہ حقیقی طور پر مددتو اللہ تعالیٰ ہی کی طرف سے ہے۔ اگر وہ چاہے تو تمہارے جنگ کرنے کے بغیر ہی اپنے دشمنوں سے بدلہ لے سکتا ہے اور اسے تمہارے لڑنے کی ضرورت نہیں ہے جیسا کہ اللہ تعالیٰ نے مومنوں کو جہاد کا حکم دینے کے بعد فرمایا: ﴿ذٰلِكَؕۛ وَلَوْ يَشَآءُ اللّٰهُ لَانْتَصَرَ مِنْهُمْۙ وَلٰكِنْ لِّيَبْلُوَاۡ بَعْضَكُمْ بِبَعْضٍؕ وَالَّذِيْنَ قُتِلُوْا فِيْ سَبِيْلِ اللّٰهِ فَلَنْ يُّضِلَّ اَعْمَالَهُمْ۰۰۴ سَيَهْدِيْهِمْ وَيُصْلِحُ بَالَهُمْۚ۰۰۵ وَيُدْخِلُهُمُ الْجَنَّةَ عَرَّفَهَا لَهُمْ۰۰۶﴾ (محمد:4-6) ’’یہ (حکم یاد رکھو!) اور اگر اللہ چاہتا تو (خود ہی) ان سے انتقام لے لیتا لیکن اس نے چاہا کہ تمہاری آزمائش ایک (کو) دوسرے سے (لڑواکر) کرے اور جو لوگ اللہ کی راہ میں مارے گئے، ان کے عملوں کو ہر گز ضائع نہیں کرے گا (بلکہ) ان کو سیدھے راستے پر چلائے گا اور ان کی حالت درست کر دے گا۔ اور ان کو بہشت میں، جس سے ان کو شناسا کر رکھاہے، داخل کرے گا۔‘‘\nاسی لیے یہاں فرمایا ہے : ﴿وَمَا جَعَلَهُ اللّٰهُ اِلَّا بُشْرٰى لَكُمْ وَلِتَطْمَىِٕنَّ قُلُوْبُكُمْ بِهٖؕ وَمَا النَّصْرُ اِلَّا مِنْ عِنْدِ اللّٰهِ الْعَزِيْزِ الْحَكِيْمِۙ۰۰۱۲۶﴾ ’’اور اس مدد کو تو اللہ نے تمہارے لیے (ذریعہ) بشارت بنایا تاکہ تمہارے دلوں کو اس سے تسلی حاصل ہو، ورنہ مدد تو اللہ ہی کی ہے جو غالب (اور) حکمت والا ہے۔‘‘یعنی اسے اس قدر غلبہ حاصل ہے کہ اس کا مقابلہ نہیں کیا جا سکتا اور اس کی تقدیر اور اس کے تمام احکام حکمت پر مبنی ہیں۔\nپھر اللہ تعالیٰ نے فرمایا: ﴿لِيَقْطَعَ طَرَفًا مِّنَ الَّذِيْنَ كَفَرُوْۤا﴾ ’’تاکہ کافروں کی ایک جماعت کو ہلاک کر دے۔ ‘‘﴿اَوْ يَكْبِتَهُمْ﴾ ’’یا انہیں ذلیل کر دے۔‘‘ اور انہیں غصے سے مغلوب لوٹا دے کہ انہیں تمہارے مقابلے میں اپنے مقاصد حاصل نہیں ہو سکے، اسی لیے فرمایا: ﴿فَيَنْقَلِبُوْا خَآىِٕبِيْنَ۰۰۱۲۷﴾ ’’تو (جیسے آئے تھے ویسے ہی) ناکام واپس جائیں ‘‘ کہ انہیں جو اُمید تھی اسے وہ حاصل نہیں کر سکے۔\nپھر اللہ تعالیٰ نے درمیان میں ایک ایسا جملہ بیان فرما دیا ہے جس سے یہ حقیقت آشکار ا ہوتی ہے کہ دنیااور آخرت میں صرف اسی وحدہ لا شریک کا حکم چلتا ہے، فرمایا:﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ﴾ ’’(اے پیغمبر صلی اللہ علیہ وسلم!) اس کام میں آپ صلی اللہ علیہ وسلم کو کچھ اختیار نہیں۔‘‘ بلکہ تمام تر تصرف اور اختیار میرا ہی ہے جیسا کہ اللہ تعالیٰ نے فرمایا ہے :﴿فَاِنَّمَا عَلَيْكَ الْبَلٰغُ وَعَلَيْنَا الْحِسَابُ۰۰۴۰﴾ (الرعد:40) ’’تو (بے شک صرف) آپ صلی اللہ علیہ وسلم کا کام (ہمارے احکام کا) پہنچا دینا ہے اور ہمارا کام حساب لینا ہے۔‘‘ اور فرمایا:﴿لَيْسَ عَلَيْكَ هُدٰىهُمْ وَلٰكِنَّ اللّٰهَ يَهْدِيْ مَنْ يَّشَآءُؕ﴾ (البقرۃ:272) ’’(اے نبی صلی اللہ علیہ وسلم!) آپ صلی اللہ علیہ وسلم ان لوگوں کی ہدایت کے ذمہ دار نہیں ہیں بلکہ اللہ تعالیٰ ہی جس کو چاہتا ہے ہدایت دیتا ہے۔‘‘ اور فرمایا:﴿اِنَّكَ لَا تَهْدِيْ مَنْ اَحْبَبْتَ وَلٰكِنَّ اللّٰهَ يَهْدِيْ مَنْ يَّشَآءُۚ﴾ (القصص:56) ’’بے شک آپ صلی اللہ علیہ وسلم جسے چاہیں ہدایت نہیں کر سکتے بلکہ اللہ ہی جس کو چاہتا ہے ہدایت دیتا ہے۔‘‘\nامام محمد بن اسحاق رحمہ اللہ نے فرمان باری تعالیٰ :﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ﴾ کی تفسیر میں کہا ہے کہ اس کا مفہوم یہ ہے کہ اے پیغمبر علیہ السلام ! میرے بندوں کے بارے میں آپ علیہ السلام کا کوئی حکم نہیں ہے سوائے ان کے جن کے بارے میں نے تمہیں حکم دیا ہو۔(تفسیر الطبری : 114/4) پھر اللہ تعالیٰ نے کفار کی باقی اقسام کا ذکر کرتے ہوئے فرمایا:﴿اَوْ يَتُوْبَ عَلَيْهِمْ﴾ ’’یا اللہ ان کے حال پر مہربانی کرے۔ ‘‘ کہ انہیں کفر سے نکال کر ضلالت کے بعد ہدایت عطا فرما دے﴿اَوْ يُعَذِّبَهُمْ﴾ یا وہ ان کے کفر اور گناہوں کی وجہ سے دنیا و آخرت میں انہیں اپنے عذاب میں مبتلا کر دے ﴿فَاِنَّهُمْ ظٰلِمُوْنَ۰۰۱۲۸﴾ کیونکہ وہ ظالم ہیں اور اسی بات کے مستحق ہیں۔\nامام احمد رحمہ اللہ نے بھی سالم کی اپنے باپ سے اس حدیث کو روایت کیا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ’’اے اللہ ! فلاں شخص پر لعنت فرما، اے اللہ ! حارث بن ہشام پر لعنت فرما، اے اللہ ! سہیل بن عمرو پر لعنت فرما۔ اے اللہ ! صفوان بن اُمیہ پر لعنت فرما۔‘‘ تو اسی موقع پر یہ آیت ِ کریمہ نازل ہوئی : ﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ اَوْ يَتُوْبَ عَلَيْهِمْ اَوْ يُعَذِّبَهُمْ فَاِنَّهُمْ ظٰلِمُوْنَ۰۰۱۲۸﴾ چنانچہ اللہ تعالیٰ نے ان سب کے حال پر مہربانی فرما دی تھی۔ (مسند أحمد)\nامام بخاری رحمہ اللہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے مروی اس حدیث کو بھی بیان فرمایا ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی کے لیے دعا یا بددعا کا ارادہ فرماتے تو رکوع کے بعد قنوت کرتے۔ راوی نے بسااوقات یہ بھی کہا ہے کہ آپ «سَمِعَ اللهُ لِمَنْ حَمِدَهُ، اَللّٰهُمَّ! رَبَّنَا لَكَ الْحَمْدُ» کے بعد فرماتے : ’’اے اللہ ! ولید بن ولید بن سلمہ بن ہشام، عیاش بن ابو ربیعہ اور کمزور مومنوں کو نجات عطا فرما، اے اللہ ! خاندان مُضَر کے لوگوں پر اپنی گرفت کو اور مضبوط کردے۔ اور اے اللہ ! انہیں اسی طرح قحط سالی میں مبتلا فرما دے جس طرح حضرت یوسف علیہ السلام کے دور میں قحط پڑا تھا۔‘‘ آپ صلی اللہ علیہ وسلم ان کلمات کو بلندآواز سے پڑھتے اور نماز فجر میں بعض اوقات عرب کے مختلف خاندانوں کے نام لے کر اس طرح بددعا بھی کرتے کہ :«اَللّٰهُمَّ! الْعَنْ فُلَانًا وَّفُلَانًا»’’اے اللہ ! فلاں فلاں پر لعنت فرما۔‘‘ تو اللہ تعالیٰ نے یہ آیت کریمہ نازل فرما دی : ﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ﴾ الآیۃ.(صحیح البخاری : 4560)\nامام بخاری رحمہ اللہ نے حمید اور ثابت کے حوالے سے سیدنا انس بن مالک رضی اللہ عنہ کی روایت بیان کی ہے کہ اُحد کے دن نبی اکرم صلی اللہ علیہ وسلم کا سر مبارک زخمی ہو گیا تھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: «كَيْفَ يُفْلِحُ قَوْمٌ شَجُّوا نَبِيَّهُمْ؟»’’وہ قوم کس طرح فلا ح پائے گی جس نے اپنے نبی صلی اللہ علیہ وسلم کے سر کو زخمی کر دیا ؟ ‘‘ تو اس موقع پر یہ آیت نازل ہوئی : ﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ﴾(صحیح البخاری قبل الحدیث : 4069)\nامام احمد رحمہ اللہ نے سیدنا انس رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ اُحد کے دن نبی اکرم صلی اللہ علیہ وسلم کا دانت مبارک شہید ہو گیا اور آپ صلی اللہ علیہ وسلم کی پیشانی پر زخم آیا جس کی وجہ سے خون بہہ کر چہرۂ اقدس پر آگیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:«كَيْفَ يُفْلِحُ قَوْمٌ فَعَلُوا هٰذَا بِنَبِيِّهِمْ وَهُوَ يَدْعُوهُمْ إِلٰى رَبِّهِمْ؟» ’’وہ قوم کس طرح فلاح پائے گی جس نے اپنے نبی صلی اللہ علیہ وسلم کے ساتھ یہ سلوک کیا جبکہ وہ انہیں اپنے رب عزوجل کی طرف دعوت دے رہے تھے ؟‘‘ تو اللہ تعالیٰ نے اس موقع پر اس آیت کریمہ کو نازل فرمایا:﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ اَوْ يَتُوْبَ عَلَيْهِمْ اَوْ يُعَذِّبَهُمْ فَاِنَّهُمْ ظٰلِمُوْنَ۰۰۱۲۸﴾ (مسند أحمد : 93/2) اور اسے امام مسلم نے بھی روایت کیا ہے۔ (صحیح مسلم : 1791)\nپھر اللہ تعالیٰ نے فرمایا ہے : ﴿وَلِلّٰهِ مَا فِي السَّمٰوٰتِ وَمَا فِي الْاَرْضِؕ﴾ یعنی آسمانوں اور زمین میں جو کچھ ہے، وہ اسی اللہ کی ملکیت ہے اور آسمانوں اور زمین کے سب رہنے والے اسی کے غلام اور بندے ہیں۔﴿يَغْفِرُ لِمَنْ يَّشَآءُ وَيُعَذِّبُ مَنْ يَّشَآءُؕ﴾ ’’وہ جسے چاہے بخش دے اور جسے چاہے عذاب دے۔‘‘ اسی کا تصرف و اختیار ہے، کوئی اس کے حکم کو ٹال نہیں سکتا اور جو کچھ وہ کرتا ہے اس سے پوچھ نہیں سکتا جبکہ ان سب سے باز پُرس ہوگی۔ ﴿وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌࣖ۰۰۱۲۹﴾ ’’اور اللہ بخشنے والا بڑا مہربان ہے۔ ‘‘\nجب جنگ احد کے سنگین واقعات پیش آئے اور نبی صلی اللہ علیہ وسلم کو سخت مصائب پیش آئے، جن کی وجہ سے اللہ نے آپ صلی اللہ علیہ وسلم کا مقام مزید بلند فرما دیا۔ اس موقع پرآپ صلی اللہ علیہ وسلم کا سر مبارک زخمی ہوا، اور دندان مبارک شہید ہوئے تو آپ صلی اللہ علیہ وسلم نے فرمایا تھا: «كَيْفَ يُفْلِحُ قَوْمٌ شَجُّوْا نَبِيَّهُمْ» ’’وہ قوم کس طرح فلاح پا سکتی ہے جس نے اپنے نبی کو زخمی کر دیا۔‘‘ اس موقعے پر آپ صلی اللہ علیہ وسلم نے مشرکین کے سرداروں کے حق میں بد دعا بھی فرمائی۔ مثلاً ابو سفیان بن حرب، صفوان بن امیہ، سہیل بن عمرو اور حارث بن ہشام۔ اللہ تعالیٰ نے اپنے نبی پر وحی نازل فرما کر آپ کو ان کے خلاف دعا کرنے، انہیںلعنت کرنے، ان کے لیے رحمت سے دوری کی درخواست کرنے سے منع فرما دیا اور فرمایا: ﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ﴾ ’’آپ صلی اللہ علیہ وسلم کے اختیار میں کچھ نہیں‘‘ آپ صلی اللہ علیہ وسلم کے فرائض صرف یہ ہیں کہ تبلیغ کریں، مخلوق کی رہنمائی فرمائیں، اور ان کو فائدہ پہنچانے کی کوشش کریں۔ باقی معاملات اللہ کے ہاتھ میں ہیں، وہ جیسے چاہتا ہے تدبیر فرماتا ہے۔ جسے چاہتا ہے ہدایت نصیب فرما دیتا ہے اور جسے چاہتا ہے گمراہ کرتا ہے۔آپ صلی اللہ علیہ وسلم انہیں بد دعائیں نہ دیں۔ ان کا معاملہ اللہ کے ہاتھ میں ہے۔ اگر اس کی حکمت اور رحمت کا تقاضا ہوگا تو ان کی توبہ قبول فرما کر انہیں اسلام کی نعمت عطا فرما دے گا اور اگر اس کی حکمت کا تقاضا ہوا تو انہیں ہدایت سے محروم فرما کر کفر میں پڑا رہنے دے گا اس صورت میں اپنے نقصان کا باعث اور اپنی جانوں پر ظلم کرنے والے وہی ہوں گے۔ اللہ تعالیٰ نے ان معین افراد کو اور دوسروں کو بھی ہدایت نصیب فرمائی اور وہ مسلمان ہو گئے۔ اس سے ثابت ہوتا ہے کہ اللہ کا اختیار بندوں کے اختیار پر غالب ہے۔ بندے کا درجہ جتنا بھی بلند ہو، اس سے یہ ہو سکتاہے کہ وہ ایک چیز کو بہتر سمجھ کر منتخب کرے حالانکہ بہتری اور مصلحت دوسری چیز ہو۔اس آیت سے یہ بھی معلوم ہوا کہ رسول صلی اللہ علیہ وسلم معاملات میں اختیار نہیں رکھتے تھے۔ لہٰذا دوسرےا فراد بدرجہ اولیٰ اختیار سے محروم ہوں گے۔ اس میں انبیاء و اولیا سے حاجتیں مانگنے والوں کی سخت تردید ہے اور یہ وضاحت ہےکہ اس قسم کا عقیدہ رکھنا شرک فی العبادات ہے، جو ان لوگوں کی کم عقلی کو ظاہر کرتا ہے کہ جس ہستی کے ہاتھ میں سب اختیارات ہیں اسے چھوڑ کر انہیں پکارتے ہیں جو ذرہ برابر اختیار نہیں رکھتے، یہ بہت بڑی گمراہی ہے۔ غور کیجئے جب اللہ نے ان کی توبہ قبول کرنے کا ذکر فرمایا تو فعل کو اپنی طرف منسوب فرمایا۔ (یعنی یہ فرمایا: کہ اللہ توبہ قبول فرماتا ہے) اس کا کوئی سبب بیان نہیں فرمایا جس کا نتیجہ برآمد ہوا ہو۔تاکہ یہ ثابت ہو تو نعمت تو بندے پر اللہ کا خالص فضل ہوتا ہے۔ اس کے لیے ضروری نہیں کہ بندے کی طرف سے پہلے کوئی عمل ہوا ہو، جو اس نعمت کا سبب بنے نہ کسی وسیلے کی ضرورت ہے۔ لیکن جب عذاب کا ذکر فرمایا تو ساتھ ہی ان کے ظلم کا ذکر فرمایا اور فائے سببیہ کے ذریعے سے واضح فرمایا: کہ عذاب کا سبب ان کا ظلم ہے۔ ارشاد ہے: ﴿اَوْ يُعَذِّبَهُمْ فَاِنَّهُمْ ظٰلِمُوْنَ۰۰۱۲۸﴾ ’’یاان کو عذاب دے کیونکہ وہ ظالم ہیں‘‘ تاکہ اس سے اللہ کا کامل عدل اور اس کی کامل حکمت ظاہر ہو، کہ اس نے سزا کو مناسب مقام پر رکھا، اور بندے پر ظلم نہیں کیا، بلکہ بندے نے خود اپنے آپ پر ظلم کیا۔\nجب یہ واضح فرما دیا کہ رسول صلی اللہ علیہ وسلم کے ہاتھ میں اختیار نہیں،تو اس کے بعد بیان فرمایا: کہ اختیار کس کے ہاتھ میں ہے۔ چنانچہ فرمایا: ﴿وَلِلّٰهِ مَا فِي السَّمٰوٰتِ وَمَا فِي الْاَرْضِؕ﴾ ’’آسمانوں اور زمین میں جو کچھ ہے، سب اللہ ہی کا ہے۔‘‘ یعنی فرشتے، انسان، جن، حیوانات، جمادات، افلاک وغیرہ اور آسمانوں اور زمین میں موجود تمام کی تمام اشیاء اللہ کی ملک اور اللہ کی مخلوق ہیں اوراس کی تدبیر کے تابع ہیں۔ وہ ان میں اس طرح تصرف کرتا ہے جس طرح بادشاہ اپنے ملک میں تصرف کرتا ہے۔ اس حکومت میں ان کا ایک ذرہ بھی نہیں۔ جب صورت حال یہ ہے تو وہ سب اس کی مغفرت اور اس کے عذاب کے درمیان ہیں۔ وہ جسے چاہتا ہےاس کی مغفرت اس طرح فرماتا ہے کہ اسے گناہ ترک کرنے کی توفیق دیتا ہے اوراس طرح اس کے گناہ بھی معاف کر دیتا ہے۔ ﴿وَيُعَذِّبُ مَنْ يَّشَآءُؕ﴾ ’’اور جسے چاہتا ہے عذاب دیتا ہے‘‘ وہ اس طرح کہ اسے اس کے نفس کے حوالے کر دیتا ہے۔ انسان کا نفس جاہل اور ظالم ہے جو برائیوں کا ارتکاب کا تقاضا کرتا ہے۔ چنانچہ انسان کا گناہ کا ارتکاب کرتا ہے اور اللہ تعالیٰ اسے گناہ کی سزا دے دیتا ہے۔ آیت مبارکہ کو دو اسمائے مبارکہ پر ختم کیا گیا ہے جن سے اللہ کی رحمت کی وسعت، اس کی مغفرت کا لامحدود ہونا، اس کےا حسان کی وسعت و عموم ظاہر ہوتا ہے۔ چنانچہ فرمایا: ﴿وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌࣖ۰۰۱۲۹﴾ ’’اللہ بخشش کرنے والا مہربان ہے۔‘‘ اس میں بہت بڑا اشارہ ہے کہ اس کی رحمت اس کے غضب پر غالب ہے اوراس کی مغفرت اس کے مؤاخذہ پر غالب ہے۔ اس آیت میں مخلوق کی حالت بیان کی گئی ہے کہ ان میں سے کسی کو اللہ تعالیٰ بخش دیتا ہے اور کسی کو عذاب دیتا ہے لیکن آیت کے آخر میں اس طرح کے دو اسمائے مبارکہ ذکر نہیں فرمائے کہ ایک سے اس کی رحمت ظاہر ہو اور دوسرے سے ان کا انتقام۔ پس اللہ تعالیٰ رحمت و احسان والا ہے۔ وہ اپنے بندوں پر ایسے انداز سے رحمت فرمائے گا جو کسی انسان کے خیال میں بھی نہیں آ سکتا، نہ اس کی کیفیت معلوم ہو سکتی ہے۔ ہم بھی اللہ تعالیٰ سے دعا کرتے ہیں کہ ہمیں اپنے دامن رحمت میں جگہ دے اور اپنی رحمت سے ہمیں بھی اپنے نیک بندوں میں شامل فرما لے۔ (آمین)\nاس آیت میں مسلمانوں سے نبی کریم صلی اللہ علیہ وسلم کے وعدے کا ذکر ہے، کہ اللہ تعالیٰ اُن کے تین ہزار (3000) فرشتوں سے مدد کرے گا، اور اس کے بعد والی آیت میں پانچ ہزار (5000) فرشتوں سے ذریعہ مدد کے وعدے کا ذکر ہے۔ اللہ کا یہ وعدہ جنگ بدر سے متعلق تھا یا جنگ احد کے متعلق، مفسرین کے دونوںاقوال ہیں۔ راجح یہی معلوم ہوتا ہے کہ اس وعدے کا تعلق یوم بدر سے تھا، اس لیے کہ سیاق کلام واقعۂ بدر سے متعلق ہے اور سورۂ انفال میں واقعۂ بدر کے بیان میں ایک ہزار (1000) فرشتوں کے ذریعہ مدد کا جو ذکر ہے، وہ اس آیت میں تین ہزار(3000) یاا س سے زیادہ کے ذریعہ مدد کے لیے منافی نہیں ہے، اس لیے کہ سورۂ انفال والی آیت میں ایک ہزار (1000) فرشتوں کے ذکر کے بعد مُرْدِفِينَ کا لفظ آیا ہے، یعنی ایک ہزار (1000) کے بعد مزید فرشتے آئیں گے۔ ربیع بن انس کا قول ہے کہ اللہ تعالیٰ نے پہلے اُن کی ایک ہزار (1000) کے ذریعہ مدد کی، پھر تین ہزار (3000) کے ذریعہ، پھر جب صبر اور تقویٰ کا مظاہرہ کیا تو پانچ ہزار (5000) کے ذریعے اور اس کی تائید ا س سے بھی ہوتی ہے کہ سورۂ انفال میں واقعۂ بدر سے متعلق سیاق کلام، بالکل ان آیتوں کے سیاق کلام کے مشابہ ہے، یعنی دونوں ہی سیاقِ کلام واقعۂ بدر سے متعلق ہے۔\nیہ جملہ معترضہ ہے،جس سے مقصود نبی کریم صلی اللہ علیہ وسلم کو متنبہ کرنا ہے کہ کہیں آپ صلی اللہ علیہ وسلم کے ذہن و دماغ میں یہ بات نہ آجائے کہ آپ کی ذات بھی کچھ مؤثر ہے اور آپ صلی اللہ علیہ وسلم کے عقیدۂ توحید میں فرق آجائے، آپ تو ایک انسان ہیں آپ کا کام اللہ کے حکم کے مطابق انسانوں کو ڈرانا ہے، ان کی بخشش یا عذاب کا معاملہ تو صرف اللہ کے اختیار میں ہے۔\nامام بخاری رحمہ اللہ نے ابوہریرہ رضی اللہ عنہ سے روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم کسی کسی دن فجر کی نماز میں کہا کرتے تھے کہ اے اللہ! فلاں اور فلاں قبائل عرب پر لعنت بھیج، تو یہ آیت اتری: ﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ﴾\nابن عمر رضی اللہ عنہما سے بخار ی اور احمد رحمہم اللہ نے روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم فجر کی دوسری رکعت میں حارث بن ہشام، سہیل بن عمروا ور صفوان بن امیہ پر لعنت بھیجتے تھے، تو یہ آیت نازل ہوئی، بخاری کی روایت میں ہے کہ ان لوگوں نے اس کے بعد توبہ کی اور اللہ نے ان کی توبہ قبول کی۔\nانس رضی اللہ عنہ بن مالک سے امام احمد رحمہ اللہ نے روایت کی ہے کہ جب جنگ احد میں آپ صلی اللہ علیہ وسلم زخمی ہوئے، تو کہا کہ وہ قوم کیسے فلاح پائے گی جس نےا پنے نبی کے ساتھ ایسا کیا، تو یہ آیت اتری۔\nآیت (129) میں اسی مضمون کی تائید ہے، کہ آسمانوں اور زمین کی ہر چیز کا مالک اللہ ہے، وہ جسے چاہے گا معاف کر دے گا، اور جسے چاہے گا عذاب دے گا۔ کسی بندے کو، وہ چاہے وہ نبی مرسل ہو یا ولی مکرم، یہ اختیار حاصل نہیں کہ کسی کی قسمت کا فیصلہ کرے اور کسی کو جنت میں بھیج دے اور کسی کو جہنم میں۔"],[872,"§کیا غزوہ اُحدمیں فرشتے نازل ہوئے تھے؟\nجب مذکورہ بالا دوقبیلوں نے کمزوری دکھائی تو اس وقت آپ صلی اللہ علیہ وسلم نے ان کی اور دوسرے مسلمانوں کی ڈھارس بندھاتے ہوئے فرمایا: کیا تمھارے لیے یہ بات کافی نہیں کہ اللہ تعالیٰ تین ہزار فرشتے بھیج کر تمھاری مدد فرما دے۔ جیسا کہ میدان بدر میں تمھاری مدد فرمائی تھی۔\nابھی لڑائی شروع بھی نہ ہوئی تھی کہ یہ افواہ پھیل گئی کرزبن جابر بہت بڑی کمک لےکر مشرکین کی مدد کے لیے آرہا ہے۔ اس افواہ سے مسلمانوں میں مزید اضطراب پھیل گیا۔ اس وقت اللہ تعالیٰ نے مسلمانوں سے فرمایا اگر کفار کو ہنگامی طور پر کمک مل جانے سے ڈرتے ہو تو اللہ تعالیٰ بھی اپنے فرشتوں کی کمک میں اضافہ کر دے گا۔ لہٰذا صبر و استقامت سے کام لو اور کافروں سے نہیں بلکہ اللہ سے ڈرتے رہو۔\nبعض مفسرین نے تین ہزار اور پانچ ہزار فرشتوں سے مدد کے وعدہ کو جنگ بدر سے متعلق کیاہے۔ اس لحاظ سے یہ بیان آیت نمبر 123کے بیان کے ساتھ مسلسل ہے۔ ہوایہ تھا جنگ بدر میں قلیل تعداد اور کمزور اور نہتے مسلمانوں کو ڈھارس بندھانے کی خاطر اللہ نے ایک ہزار فرشتے میدان بدر میں بھیج دیے۔ جیسا کہ سورہ انفال کی آیت :﴿فَاسْتَجَابَ لَكُمْ اَنِّيْ مُمِدُّكُمْ بِاَلْفٍ مِّنَ الْمَلٰٓىِٕكَةِ مُرْدِفِيْنَ﴾ (الانفال : 9)سے معلوم ہوتاہے۔ پھر جب جنگ بدر میں ہی یہ مشہور ہوا کہ مکہ سے مزید کمک پہنچ رہی ہے تو اللہ تعالیٰ نے فرمایا کہ ایسی صورت میں ہم تین ہزار یا پانچ ہزار فرشتے بھیج دیں گے۔ پھر چونکہ کافروں کے لیے مکہ سے کوئی مزید کوئی کمک نہ پہنچی تو اور فرشتے بھی نہ آئے۔ البتہ ایک ہزار فرشتوں کی میدان بدر میں شرکت قرآن پاک سے ثابت ہے۔ نیز اس کی صحیحین اور دوسری کتب احادیث میں اس قدر روایات مذکور ہیں جو حد تواتر کو پہنچتی ہیں۔ لیکن جنگ اُحد میں فرشتوں کی کمک صحیح روایات سے ثابت نہیں ہوتی۔ لہٰذا یہی توجیہ زیادہ درست معلوم ہوتی ہے۔"],[873,"§معتزلہ کا میدان بدر میں بھی نزول ملائکہ سے انکار اور ان کی تاویلات\nاس سب باتوں کے علی الرغم معتزلہ اور ان کے جانشینوں نے بدر میں فرشتوں کی آمد سے انکار کیاہے۔ یہ لوگ احادیث کو درخور اعتناء سمجھتے ہی نہیں اور قرآن کی آیات کی یہ تاویل کر لیتے ہیں کہ قرآن میں تو کہیں نہیں کہ اللہ تعالیٰ نے فی الواقع فرشتے بھیجے تھے بلکہ رسول صلی اللہ علیہ وسلم کا قول نقل کیا ہے کہ جنگ کے وقت رسول نے مسلمانوں سے اللہ تعالیٰ پر توکل کرنے کی خاطر یہ فرمایا تھا کہ اللہ تعالیٰ ایسا بھی کر سکتا ہے۔ پھر اس کے بعد جو عقلی دلائل دیتے ہیں وہ اس قسم کے ہیں کہ کسی قوم کو ہلاک کرنے کے لیے تو ایک فرشتہ بھی کافی ہے پھر ہزاروں کی کیا ضرورت تھی؟ یا یہ کہ اگر فرشتوں سے ہی کام لینا تھا تو صرف ملک الموت ہی کافی تھا، جو سب کی روحیں قبض کر لیتا بلکہ اگر ایساہی معاملہ تھاتو اللہ تعالیٰ نے کافر پیدا ہی کیوں کیے؟ یا یہ کہ فرشتے اگر اجسام کثیفہ تھے تو ضرور سب کو نظر آتے، حالانکہ ایسا نہیں ہوا اور اگر اجسام لطیفہ تھے تو ان میں طاقت ہی کیا تھی جو کسی کو قتل کرتے۔”وغیر ذالک من الخیرافات“ ان دلائل میں جتنا وزن ہے وہ آپ بھی دیکھ رہے ہیں۔ لہٰذا ہم ان کے جواب میں وقت ضائع نہیں کر نا چاہتے، جو اللہ کی حکمت بالغہ کے منافی ہیں اور ایسے اعتراضات تو شریعت کی ایک ایک بات پر کیے جا سکتے ہیں۔ معلوم نہیں کہ ان لوگوں کا اللہ اور اللہ کے کلام پر ایمان کس قسم کا ہے؟"],[874,"§غزوۂ بدر میں مسلمانوں کی چار طرح سے مدد الٰہی\nمیدان بدر میں اللہ نے جو نزول ملائکہ کی تمھیں خوشخبری دی تھی وہ تو محض اس لیے تھی کہ تمھارے دل مضبوط ہوجائیں اورتم پورے وثوق کے ساتھ جم کر لڑائی کے میدان میں اُترو اورفرشتوں پر ہی کیا منحصرہے مدد کی جو بھی صورت ہو وہ اللہ ہی کی طرف سے ہوتی ہے۔ چنانچہ بدر کے میدان میں اللہ نے چار طرح سے مسلمانوں کی مدد فرمائی تھی۔ مثلاً (1)اللہ نے ہوا کا رخ کفار کے لشکر کی طرف موڑ دیا اور ریت نے اُڑاُڑ کر ان کے لشکرکو بدحال بنا دیا۔ (2)بارش کا نزول جس سے کفار کے پڑاؤ میں تو پھسلن اور دلدل مچ گئی۔ جبکہ مسلمانوں کے پڑاؤ میں ریت جم کربیٹھ گئی۔ نیز انھیں استعمال کے لیے وافر پانی میسر آگیا۔ (3)فرشتوں کا نزول چنانچہ سیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ آپ صلی اللہ علیہ وسلم نے بدر کے دن فرمایا: یہ جبریل علیہ السلام آن پہنچے اپنے گھوڑے کا سرتھامے ہوئے، لڑائی کےہتھیار لگائے ہوئے۔“ (بخاری، کتاب المغازی، باب شہود الملائکۃ بدرا)نیز سیدنا رفاعہ رضی اللہ عنہ کہتے ہیں کہ ایک دفعہ جبریل علیہ السلام رسول اللہ صلی اللہ علیہ وسلم کے پاس آکر کہنے لگے: آپ صلی اللہ علیہ وسلم اہل بدر کو کیسا سمجھتے ہیں؟“ آپ صلی اللہ علیہ وسلم نے جواب دیا: ”سب مسلمانوں سے افضل“ یا کوئی ایسا ہی کلمہ کہا: جبریل کہنے لگے : اسی طرح وہ فرشتے جو غزوہ بدر میں حاضر ہوئے تھے دوسرے فرشتوں سے افضل ہیں۔“ (بخاری، حوالہ ایضاً)اور (4)مسلمانوںکی مدد کا چوتھا طریقہ یہ تھا کہ کفار کو مسلمان مجاہدین کی تعداد اصل تعداد سے دوگنی نظر آنے لگی تھی۔\nاللہ کی مدد کا مقصد یہ تھا کہ کفر کا زور ٹوٹ جائے اور یہ مقصد مکمل طور پر حاصل ہوگیا۔ کافروں کے ستر سردار معہ ابو جہل سالار لشکر اس جنگ میں مارے گئے، اتنے ہی قید ہو گئے اور باقی لشکر ذلیل و خوار ہو کر بھاگ کھڑا ہوا جس کے سوا ان کے لیے کوئی چارہ کار ہی نہ رہ گیا تھا۔"],[875,"§کیا اُحد میں فرشتوں کا نزول ہوا تھا؟\nیہاں ایک سوال پیداہوتا ہے کہ آیا فرشتوں کا نزول بدر اور اُحد دونوں میدانوں میں ہوا تھا؟ تو اس کا جواب یہ ہے کہ بدر میں فرشتوں کا نزول یقینا ہوا تھا اور وہ کتاب و سنت سے ثابت شدہ ہے۔ بعض لوگوں کا خیال ہے کہ میدان اُحد میں بھی نزول ہوا تھا جیسا کہ مذکورہ آیات سے اشارہ ملتاہے۔ میرا ذاتی خیال یہ ہے کہ اس میدان میں مسلمانوں سےرسول اللہ صلی اللہ علیہ وسلم کی نافرمانی کی بنا پر ایک شدید جنگی غلطی ہو گئی تھی جس نے ایک بار مسلمانوں کو شکست سے بھی دوچار کر دیا تھا اور چونکہ اس غلطی کی وجہ محض حرص و طمع تھی۔ لہٰذا اللہ تعالیٰ نے اس غلطی پر عتاب بھی فرمایا۔ تاہم ان کی یہ غلطی اللہ تعالیٰ نے معاف فرما دی تھی۔ اس بے صبری کی وجہ سے میدان اُحد میں فرشتوں کا نزول نہیں ہوا۔ اگر مسلمان ایسا بے صبری کا مظاہرہ نہ کرتے تو اللہ تعالیٰ یہاں بھی فرشتے بھیج دیتے۔ واللہ اعلم بالصواب"],[876,"§آپ صلی اللہ علیہ وسلم کی زخمی کرنے والوں کے لیے بددعاء\nمیدان اُحد کے مزید حالات تو آگے چل کر مذکور ہوں گے۔ یہاں صرف ایک واقعہ کی طرف اشارہ کیا گیا ہے جو اس آیت کے نزول کا سبب بنا۔ وہ واقعہ یہ تھا کہ جنگ اُحد میں رسول اللہ صلی اللہ علیہ وسلم کا اگلا دانٹ ٹوٹ گیا اور سر زخمی ہو گیا۔ آپ صلی اللہ علیہ وسلم اپنے چہرے سے خون پونچھتے جاتے اور فرماتے، وہ قوم کیسے فلاح پائے گی جس نے اپنے نبی کا سرزخمی کر دیا اور دانت توڑ دیا۔ حالانکہ وہ انھیں اللہ کی طرف دعوت دے رہا تھا“ تو اس موقع پر یہ آیت نازل ہوئی۔(مسلم، کتاب الجہاد، باب غزوہ اُحد) چنانچہ اس موقع پر چند نامور مشرکین کا نام لے لے کر انھیں بددعا دی۔ مگر اللہ تعالیٰ کو کچھ اور ہی منظور تھا۔ چند ہی روز گزرے تھے کہ جن مشرکوں کے حق میں آپ صلی اللہ علیہ وسلم نے یہ بددعا کی تھی، انھیں اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کے قدموں پر لاڈالا اور اسلام کے جانباز سپاہی بنا دیا۔\n﴿اِذْ تَقُوْلُ لِلْمُؤْمِنِيْنَ۠﴾ غزوۂ بدر میں رسول اللہ صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے ساتھ صحابہ کرام رضی اللہ عنہم کو بوجہ ان کے صبر اور تقویٰ کے کامیابی حاصل ہوئی تو اللہ پاک رسول اللہ صلی اللہ علیہ وسلم کو مخاطب کرکے مطلع کر رہے ہیں کہ معرکہ بدر میں انہیں اطلاع ملی کہ (کرزبن جابر محاربی) چاہتا ہے کہ مشرکین کی مددکے لیے کچھ افراد بھیجے وہ ان کے ساتھ برسرپیکار ہوں تو یہ خبر ایمان داروں پر شاق گزری اس وقت آپ نے ایمان والوں کو مخاطب کرتے ہوئے فرمایا کیا تمہیں یہ بات کفایت نہیں کرتی کہ تمہارا پروردگار تمہاری مدد کے لیے تین ہزار (3000) فرشتے بھیج دے جوآسمان سے نازل ہوں گے۔ یقیناً تمہارے لیے یہ بات کافی ہے کہ اگر تم صبر کے دامن کو تھامے رکھو اور تم میں تقویٰ کارفرما ہو اور تمہارا دشمن جلدی میں تم پر حملہ آور ہو تو تمہارا پروردگار ان کے مقابلہ میں تمہاری مدد کے لیے پانچ ہزار (5000) فرشتے اُتار دے گا جو امتیازی وصف کے ساتھ موصوف ہوں گے لیکن (کرزبن جابر) اپنے پروگرام میں کامیاب نہ ہو سکا اس نے خاموشی اختیا رکی تو اللہ تعالیٰ نے رسول اکرم صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے رفقاء کی مدد میں صرف ایک ہزار (1000) فرشتے نازل فرمائے جیسا کہ سورۂ انفال میں ارشاد ربانی ہے :\n﴿اِذْ تَسْتَغِيْثُوْنَ۠ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ اَنِّيْ مُمِدُّكُمْ بِاَلْفٍ مِّنَ الْمَلٰٓىِٕكَةِ﴾ (الانفال :9) ’’جب تم اپنے پروردگار سے مدد طلب کررہے تھے تو اللہ پاک نے تمہاری اِستدعاء کو شرف قبولیت عطا فرماتے ہوئے پیغام دیا کہ میں ایک ہزار (1000) فرشتوں کو تمہاری مدد کے لیے بھیج رہا ہوں۔‘‘\nچنانچہ ایک ہزار فرشتے مدد کے لیے نازل ہوئے انہوں نے ایمان والوں کے ساتھ مل کر کفار کے ساتھ لڑائی کی اس کا مشاہدہ بھی کیا گیا اور اس کے یقینی ہونے میں ہر گزشبہ نہیں لیکن ایک ہزار (1000) سے زائد تعداد میں فرشتوں کی امداد نہیں ہوئی اس لیے کہ زائد تعداد میں فرشتوں کی امداد کو (کرزبن جابر) کی عملاً قریش کے ساتھ معاونت پر موقوف رکھا گیا تھا جب اس نے ان کی مدد نہ کی تو اللہ تعالیٰ نے ایک ہزار(1000) سے زائد فرشتوں کی امداد کو جاری نہیں فرمایادراصل فرشتوں کی امداد کاذکرتمہارے لیے خوشی کا باعث بنا اس سے تمہارے دلوں میں اطمینان کی لہر دوڑ گئی اور اضطرابی کیفیت ختم ہو گئی اللہ پاک کی جانب سے اس امداد کا یہ فائدہ ہوا کہ ستر کی تعداد میں مشرکین قتل ہو گئے اور ستر کی تعداد میں قیدی ہوئے۔چنانچہ وہ نہایت مایوس ہو کر واپس چلے گئے انہیں کامیابی تو کیا حاصل ہونا تھی اس کے خلاف وہ شکست خوردہ ذہنیت کے ساتھ واپس گئے۔ (ایسر التفاسیر : 211/1)\nبخاری شریف میں ابن عباس رضی اللہ عنہما بیان کرتے ہیں جنگ بدر کے موقع پر نبی صلی اللہ علیہ وسلم نے فرمایا یہ جبرئیل علیہ السلام، فرشتہ ہے اس نے اپنے گھوڑے کے سرکو پکڑا ہوا ہے اس کے جسم پر لڑائی کے ہتھیار ہیں۔ (فتح الباری : 212/7)\nغزوۂ بدر پہلی اسلامی جنگ ہے جس میں مسلمانوں کوزبردست کا میابی حاصل ہوئی اور کفار کو عبرتناک شکست سے دوچار ہونا پڑا جب کہ ان کی تعداد بھی بہت زیادہ تھی اور اسلحہ بھی تھا۔ دراصل رسول اکرم صلی اللہ علیہ وسلم کی دعا کا نتیجہ ہے کہ مسلمانوں کو کامیابی نصیب ہوئی اور مشرکین کے لیڈر اُمیہ، ابو جہل وغیرہ جہنم رسید ہوئے۔ آپ صلی اللہ علیہ وسلم کی دعا کے کلمات کا ترجمہ ملاحظہ فرمائیں:\n’’اے اللہ ! میں تجھے تیرے عہد کا واسطہ دیتا ہوں جب کہ قریش نہایت فخر و طمطراق کے ساتھ گھروں سے نکلے ہیں وہ تیرے پیغمبر صلی اللہ علیہ وسلم کی تکذیب کرتے ہیں تجھ سے جھگڑا کررہے ہیں اے اللہ ! تو ان کی مدد فرما جس کا تونے مجھ سے وعدہ کیا اے اللہ ! اگر صحابہ کرام رضی اللہ عنہم کی یہ جماعت آج قتل ہوجاتی ہے تو ان کے بعد زمین پر تیری عبادت نہ ہوگی۔‘‘\nدراصل جب آپ صلی اللہ علیہ وسلم نے دیکھا کہ فرشتے مدد کے لیے نازل ہوئے ہیں تو آپ صلی اللہ علیہ وسلم نے نہایت الحاح کے ساتھ دعا فرمائی بالآخر ابو بکر صدیق رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کے ہاتھ پکڑے اور عرض کیا آپ صلی اللہ علیہ وسلم کے دعائیہ کلمات کافی ہیں مزید دعا نہ فرمائیں۔ (فتح الباری : 289/7)\nغزوۂ بدر میں صحابہ کرام رضی اللہ عنہم کی تعداد تین سو تیرہ (313)تھی جب کہ کفار کے لشکر کی تعداد ایک ہزار (1000) تھی ان میںستر (70) افراد قتل ہوئے اور ستر (70) کو قیدی بنا لیا گیا۔ (فتح الباری : 307/7)غزوۂ بدر کے سلسلہ میں مزید احادیث کو سورۂ انفال کی تفسیر میں ذکر کیاجائے گا۔ ان شاء اللہ۔\n﴿لِيَقْطَعَ طَرَفًا مِّنَ الَّذِيْنَ كَفَرُوْۤا﴾ غزوۂ اُحد میں بھی آغاز جنگ میں کفار کے لشکر سے کچھ لوگ قتل ہوئے ابن جریر رحمہ اللہ نے اٹھارہ (18) کفار کا ذکر کیا ہے جب کہ اس سے زیادہ تعداد میں قتل ہوئے ہیں مشرکین نے مقتولوں کو دفن کر دیا تاکہ مسلمان ان کی نعشوں کاکہیں مثلہ نہ کر دیں جیسا کہ انہوں نے مسلمانوں کی نعشوں کا مثلہ کیا اس کی مثال حمزہ رضی اللہ عنہ کی شخصیت کی ہے کہ ابوسفیان کی بیوی ’’ہندہ‘‘ نامی عورت نے ان کا پیٹ چاک کرکے ان کا جگر نکال کر دانتوں میں چبایا لیکن نگل نہ سکی۔ کچھ لوگوں کو ذلیل کیا اور ان کے اعضاء کوکاٹالیکن وہ ناکام واپس لوٹے۔\n﴿لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ﴾ اس آیت کا تعلق بھی غزوۂ اُحد سے ہے اس کا شان نزول امام بخاری، ترمذی اور امام نسائی نےبیان کیا ہے۔ ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اُحد کے دن کفار کے لیے بددعاکرتے ہوئے ذیل کے کلمات کہے :\n’’اے اللہ ! ابوسفیان پر لعنت فرما، اے اللہ حارث بن سلیمان پرلعنت کر اور اے اللہ ! صفوان بن اُمیہ اور سہیل بن امیہ پر لعنت بھیج۔‘‘ چونکہ ان تمام کی توبہ قبول ہو گئی اس لیے یہ آیت نازل ہوئی کہ آپ صلی اللہ علیہ وسلم کو کچھ اختیار نہیں ہے کہ اللہ تعالیٰ کسی کی توبہ قبول کرے یا عذاب دے کہ وہ ظالم ہے یہ اختیار اللہ تعالیٰ کو ہے اس طرح بخاری و مسلم میں انس رضی اللہ عنہ سے روایت ہے کہ اُحد کے دن آپ صلی اللہ علیہ وسلم کا رباعیہ دانت ٹوٹ گیا اور آپ صلی اللہ علیہ وسلم کا چہرہ زخمی ہو گیا اور آپ صلی اللہ علیہ وسلم کے چہرے مبارک سے خون بہنے لگا اس حالت میں آپ صلی اللہ علیہ وسلم کی زبان پر یہ کلمات آئے کہ وہ لوگ کیسے نجات پا سکتے ہیں جنہوں نے اپنے پیغمبر صلی اللہ علیہ وسلم کو زخمی کیا جب کہ پیغمبر صلی اللہ علیہ وسلم انہیں اپنے پروردگار کی طرف دعوت دے رہا ہے تو ا س واقعہ پر اللہ تعالیٰ نے یہ حکم نازل کیا کہ آپ صلی اللہ علیہ وسلم کو ہر گز کچھ اختیار حاصل نہیں ہے۔ اس حقیقت سے انکار ممکن نہیں ہے کہ مخلوق کے کسی معاملہ میں کسی فرد کو کچھ اختیار نہیں ہے صرف خالق حقیقی کو تمام اختیارات حاصل ہیں اور اسی کا حکم نافذ ہوگا ممکن ہے کہ اللہ تعالیٰ کسی کو توبہ کی توفیق عطا فرما دے تو ایسی حالت میں کسی انسان کا ان پر لعنت بھیجنا درست نہیں ہے۔\nغور فرمائیں جب آخر الزمان پیغمبر صلی اللہ علیہ وسلم کو یہ مقام حاصل نہیں ہے اور انہیں کچھ اختیار نہیں ہے تو پھر آپ صلی اللہ علیہ وسلم کے علاوہ کس کو یہ بات زیب دیتی ہے کہ وہ دین کے معاملات میں جن کا تعلق بندوں سے ہے ان میں کچھ اختیارات انہیں حاصل ہوں چہ جائیکہ جو لوگ فوت ہو چکے ہیں اور قبروں میں مدفون ہیں اگرچہ جب وہ زندہ تھے تو ان کا شمار اولیاء اللہ میں ہوتا تھا کیسے ممکن ہے کہ کائنات کے معاملات میں وہ دخل دے سکیں، تصرف کر سکیں، کسی کو کامیاب کریں کسی کو ناکام کریں، کسی کو بیمار کریں، کسی کو شفایاب کریں، کسی کو افلاس سے دوچار کریں ہر گز اسلام کا یہ منشاء نہیں ہے بلکہ تمام معاملات صرف اور صرف اللہ تعالیٰ کے اختیارات ہی میں ہیں۔\n﴿وَلِلّٰهِ مَا فِي السَّمٰوٰتِ وَمَا فِي الْاَرْضِؕ يَغْفِرُ لِمَنْ يَّشَآءُ وَيُعَذِّبُ مَنْ يَّشَآءُؕ وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌࣖ۰۰۱۲۹﴾ جو ذات آسمانوں اور زمین کی بادشاہت کا استحقاق رکھتی ہے اسی کے اختیار میں آسمان و زمین کے تمام معاملات ہیں اللہ تعالیٰ کی ذات کے ساتھ ہرگز کسی کو شریک نہیں بنایا جا سکتا نہ کسی کی رائےکو دخل ہے اگرچہ اس کی حیثیت مقرب فرشتہ کی یا پیغمبر کی ہے۔ تمام نظام اللہ تعالیٰ کی قدرت اور اس کی مشیت کے ساتھ مربوط ہے دراصل اللہ پاک نے رسول اکرم صلی اللہ علیہ وسلم کو آگاہ کیا ہے اور ادب سکھلایا ہے کہ مشرکین پر لعنت بھیجنا ان کے حق میں بددعا کرنا آپ کے لیے مناسب نہیں ہے۔ آسمان و زمین بلکہ مکمل عالم کا نظام مشرق سے مغرب تک صرف اور صرف اللہ پاک کی ذات کے لیے خاص ہے اسی کے فیصلے نافذ ہوں گے وہ جس شخص کی توبہ کو قبول کرنا چاہے گا قبول کرے گا اور جس کو چاہے گا عذاب میں مبتلا کر ے گا اور جس سے چاہے گا انتقام لے گا اور اس کی مشیت جس شخص کے بارے میں فیصلہ کرے گی کہ اس کے گناہوں پر پردہ ڈالے اور اسے رسوائی سے محفوظ کرے تو وہ قادر مطلق ہے مختار ہے جو اللہ پاک چاہتا ہے وہی کچھ ہوتا ہے اور جو نہیں چاہتا وہ نہیں ہوتا یہ سب اس کا فضل و کرم ہے لیکن مغفرت یا عذاب دینے کی مشیت، حکمت و مصلحت کے تابع ہے۔ (المنار : 118/4-120، صحیح ترمذی، علامہ البانی :30/3)\n﴿يٰۤاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تَاْكُلُوا الرِّبٰۤوا اَضْعَافًا مُّضٰعَفَةً١۪ࣕ وَّاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُفْلِحُوْنَۚ۰۰۱۳۰ وَاتَّقُوا النَّارَ الَّتِيْۤ اُعِدَّتْ لِلْكٰفِرِيْنَۚ۰۰۱۳۱ وَاَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ لَعَلَّكُمْ تُرْحَمُوْنَۚ۰۰۱۳۲ وَسَارِعُوْۤا اِلٰى مَغْفِرَةٍ مِّنْ رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمٰوٰتُ وَالْاَرْضُۙ اُعِدَّتْ لِلْمُتَّقِيْنَۙ۰۰۱۳۳ الَّذِيْنَ يُنْفِقُوْنَ فِي السَّرَّآءِ وَالضَّرَّآءِ وَالْكٰظِمِيْنَ الْغَيْظَ وَالْعَافِيْنَ عَنِ النَّاسِؕ وَاللّٰهُ يُحِبُّ الْمُحْسِنِيْنَۚ۰۰۱۳۴ وَالَّذِيْنَ اِذَا فَعَلُوْا فَاحِشَةً اَوْ ظَلَمُوْۤا اَنْفُسَهُمْ ذَكَرُوا اللّٰهَ فَاسْتَغْفَرُوْا۠ لِذُنُوْبِهِمْ١۪ࣞ وَمَنْ يَّغْفِرُ الذُّنُوْبَ اِلَّا اللّٰهُ١۪۫ࣕࣞ وَلَمْ يُصِرُّوْا عَلٰى مَا فَعَلُوْا وَهُمْ يَعْلَمُوْنَ۰۰۱۳۵ اُولٰٓىِٕكَ جَزَآؤُهُمْ مَّغْفِرَةٌ مِّنْ رَّبِّهِمْ وَجَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَاؕ وَنِعْمَ اَجْرُ الْعٰمِلِيْنَؕ۰۰۱۳۶﴾\nاے لوگو جو ایمان لائے ہو! بڑھا چڑھا کر سود نہ کھائو، اور اللہ تعالیٰ سے ڈرو تاکہ تمہیں نجات مل سکے اور اس آگ سے ڈرو جو کافروں کے لیے تیار کی گئی ہے اور اللہ اور اس کے رسول کی فرمانبرداری کرو تاکہ تم پر رحم کیا جائے اور اپنے رب کی بخشش اور اس جنت کی طرف دوڑو جس کی چوڑائی آسمانوں اور زمین کے برابر ہے جو پرہیز گاروں کے لیے تیار کی گئی ہے\nوہ لوگ جو خوشی اور سختی کے موقع پر (اللہ کی راہ میں) خرچ کرتے ہیں اور غصہ پی جانے والے اور لوگوں کو معاف کر دینے والے ہیں۔ اور اللہ نیکو کاروں کو پسند کرتا ہے\nاور وہ لوگ جب کوئی برا کام کر بیٹھتے ہیں یا اپنے آپ پر ظلم کر گزرتے ہیں تو اللہ کو یاد کرتے، پھر اپنے گناہوں کی بخشش مانگتے ہیں اور اللہ کے سوا کون گناہوں کو بخشتا ہے؟ اور وہ اپنے کیے پر جان بوجھ کر اصرار نہیں کرتے\nوہی لوگ ہیں جن کا بدلہ ان کے رب کی طرف سے بخشش اور جنت کے باغ ہیں جن کے نیچے نہریں بہتی ہیں، وہ (ان باغوں)\nمیں ہمیشہ رہیں گے اور عمل کرنے والوں کے لیے (اللہ کے ہاں) اچھا اجر ہے"],[877,"§سود مطلقاً حرام ہے\nاللہ تعالیٰ نے اپنے مومن بندوں کو سود کے لین دین اور اسے دُگنا چوگنا کھانے سے منع فرمایا ہے۔ زمانۂ جاہلیت میں جب قرض واپس کرنے کی مدت آجاتی تو وہ مقروض سے کہتے کہ یاتو وہ قرض ادا کرے یا وہ اضافہ کردے، اگر وہ قرض ادا کردیتا تو ٹھیک ورنہ وہ قرض اد ا کرنے کی مدت میں اضافہ کر دیتا تو دوسرا قرض کی مقدار میں اضافہ کر دیتا اور اسی طرح ہر سال ہوتا جس کی وجہ سے بسااوقات قرض کی معمولی رقم بڑھتے بڑھتے بہت زیادہ رقم کی صورت اختیار کر جاتی تھی۔ اللہ تعالیٰ نے اپنے بندوں کو اس سلسلے میںتقویٰ اختیار کرنے کا حکم دیاتاکہ وہ دنیا و آخرت میں کامیابی و کامرانی حاصل کرلیں اور ایسا نہ کرنے کی صورت میں جہنم کی آگ سے ڈراتے ہوئے فرمایا:﴿وَاتَّقُوا النَّارَ الَّتِيْۤ اُعِدَّتْ لِلْكٰفِرِيْنَۚ۰۰۱۳۱ وَاَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ لَعَلَّكُمْ تُرْحَمُوْنَۚ۰۰۱۳۲﴾ ’’اور (دوزخ کی) آگ سے بچو جو کافروں کے لیے تیار کی گئی ہے اور اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت کرو تاکہ تم پررحمت کی جائے۔‘‘"],[878,"§نیک کاموں اور حصولِ جنت کی ترغیب\nپھر اللہ تعالیٰ نے نیک اور تقربِ الٰہی کے حصول کے کاموں کی ترغیب دیتے ہوئے فرمایا:﴿وَسَارِعُوْۤا اِلٰى مَغْفِرَةٍ مِّنْ رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمٰوٰتُ وَالْاَرْضُۙ اُعِدَّتْ لِلْمُتَّقِيْنَۙ۰۰۱۳۳﴾ ’’اور اپنے پروردگار کی بخشش اور بہشت (جنت) کی طرف لپکو جس کا عرض (چوڑائی) آسمانوں اور زمین کے برابر ہے اور جو (اللہ سے) ڈرنے والوں کے لیے تیار کی گئی ہے۔ ‘‘جس طرح دوزخ کوکافروں کے لیے تیار کیا گیا ہے۔ (دیکھئے :البقرۃ : 24)\nکہا گیا ہے کہ ﴿عَرْضُهَا السَّمٰوٰتُ وَالْاَرْضُۙ﴾ ’’جس کا عرض آسمانوں اور زمین کے برابر ہے۔ ‘‘ سے جنت کے طول کی وسعت کی طرف اشارہ ہے جس طرح جنت کے بچھونوں کے بارے میں فرمایا:﴿بَطَآىِٕنُهَا مِنْ اِسْتَبْرَقٍؕ﴾ (الرحمٰن:54) ’’ان کے استرد بیزر یشم کے ہیں۔ ‘‘ تو ان کے اوپر کے غلافوں کے بارے میں تمہارا کیا خیال ہے ؟ یہ بھی کہا گیا ہے کہ جنت کا عرض بھی اس کے طول ہی کی طرح ہے کیونکہ یہ عرش الٰہی کے تلے ایک قبے کی صورت میں ہے اور گول چیزکا عرض، طول ہی کی طرح ہوتا ہے۔ اس کی تائید صحیح بخاری کی اس حدیث سے ہوتی ہے : ’’جب تم اللہ تعالیٰ سے (جنت کا) سوال کرو تو اس سے جنت الفردوس کا سوال کرو، یہ سب سے اعلیٰ اور افضل جنت ہے، اس سے جنت کی نہریں جاری ہوتی ہیں اور اس کے اوپر رحمٰن کا عرش ہے۔ ‘‘(صحیح البخاری : 7423)\nیہ آیت اسی طرح ہے جیسا کہ سورۂ حدید کی یہ آیت ہے :﴿سَابِقُوْۤا اِلٰى مَغْفِرَةٍ مِّنْ رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَآءِ وَالْاَرْضِۙ﴾ (الحدید:21) ’’(بندو!) اپنے پروردگار کی بخشش کی طرف اور جنت کی (طرف)، جس کا عرض آسمان اور زمین کے عرض کا سا ہے، لپکو۔‘‘ امام بزار رحمہ اللہ نے سیدنا ابوہریرہ رضی اللہ عنہ کی اس حدیث کو بیا ن کیاہے کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم ! ارشاد باری تعالیٰ ہے : ﴿وَجَنَّةٍ عَرْضُهَا السَّمٰوٰتُ وَالْاَرْضُۙ﴾ ’’اور جنت جس کا عرض آسمانوں اور زمین کے برابر ہے۔ ‘‘ تو سوال یہ ہے کہ پھر جہنم کہاں ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:’’کیا تم نے دیکھا ہے کہ جب رات آتی ہے تو ہر چیز پر چھا جاتی ہے تو اس وقت دن کہاں ہوتا ہے؟ اس نے جواب دیا : جہاں اللہ چاہے، آپ صلی اللہ علیہ وسلم نے فرمایا:اسی طرح جہنم کو بھی اللہ تعالیٰ جہاں چاہتا ہے رکھتا ہے۔‘‘\n(صحیح ابن حبان : 103)\nاس ارشاد نبوی صلی اللہ علیہ وسلم کے دو معنی ہو سکتے ہیں : (1)جب دن آتا ہے تو رات کے عدم مشاہدہ سے یہ لازم نہیں آتا کہ اس وقت رات کسی جگہ بھی نہیں ہے، رات کہیں نہ کہیں موجود ہوتی ہے،خواہ ہمیں اس کا علم نہ ہو، اس طرح جہنم بھی وہیں ہوتی ہے جہاں اللہ تعالیٰ اسے رکھتا ہے۔ (2)دوسرے اس کے یہ معنی ہو سکتے ہیںکہ جب دن اس طرف سے روئے زمین کو ڈھانپ لیتا ہے تو رات اس کے دوسری طرف ہوتی ہے، اسی طرح جنت اعلیٰ علیین میں آسمانوں کے اوپر اور عرش کے نیچے ہے اور اس کا عرض حسب فرمان باری تعالیٰ آسمانوں اور زمین کے برابر ہے جبکہ جہنم اسفل سافلین میں ہے، لہٰذا جنت کے عرض کے آسمانوں اور زمین کے برابر ہونے اور جہنم کے موجودہونے میں کوئی تضاد نہیں ہے۔ واللہ اعلم\nپھر اللہ تعالیٰ نے اہل جنت کے اوصاف کا تذکرہ کرتے ہوئے فرمایا: ﴿الَّذِيْنَ يُنْفِقُوْنَ فِي السَّرَّآءِ وَالضَّرَّآءِ﴾ ’’جو آسودگی اور تنگی میں (اپنا مال اللہ کی راہ میں) خرچ کرتے ہیں۔‘‘ یعنی تنگی اور خوش حالی میں، خوشی و ناخوشی میں، صحت و بیماری میں اور ہر حال میں اپنا مال اللہ تعالیٰ کی راہ میں خر چ کرتے رہتے ہیں جیسا کہ ارشاد باری تعالیٰ ہے : ﴿اَلَّذِيْنَ يُنْفِقُوْنَ اَمْوَالَهُمْ بِالَّيْلِ وَالنَّهَارِ سِرًّا وَّعَلَانِيَةً﴾ (البقرۃ:274) ’’جو لوگ اپنا مال رات اور دن، پوشیدہ اور ظاہر (اللہ کی راہ میں) خرچ کرتے رہتے ہیں۔‘‘ یعنی انہیں کوئی امر بھی اللہ تعالیٰ کی اطاعت، اس کی مرضی کے کاموں میں مال خرچ کرنے، اپنے قریبی رشتے داروں اور اللہ تعالیٰ کی دیگر مخلوق کے ساتھ احسان کرنے اور نیکی کے دیگر کام بجالانے سے روکتا نہیں ہے۔\n﴿وَالْكٰظِمِيْنَ الْغَيْظَ وَالْعَافِيْنَ عَنِ النَّاسِؕ﴾ ’’اور غصے کو روکتے اور لوگوں کے قصور معاف کرتے ہیں۔‘‘ جب انہیں غصہ آئے تو اسے پی جاتے ہیں، یعنی اسے چھپالیتے ہیںاور اس کا اظہار نہیں کرتے اور جو ان کے ساتھ بُراسلوک کرے اسے معاف کر دیتے ہیں۔ امام احمد رحمہ اللہ نے سیدنا ابوہریرہ رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، وَلٰكِنَّ الشَّدِيْدَ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ»’’بہادر وہ نہیں ہے جو پچھاڑ دے بلکہ بہادر تو وہ ہے جو غصے کے وقت اپنے آپ پر قابو رکھے۔‘‘ (مسند أحمد)اسے امام بخاری اور امام مسلم رحمہما اللہ نے بھی روایت کیا ہے۔ (صحیح البخاری : 6114 و صحیح مسلم : 2609)\nامام احمد رحمہ اللہ نے سہل بن معاذ بن انس رضی اللہ عنہ کی اپنے باپ سے روایت کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے غصے کو پی لیا، حالانکہ وہ اس کے اظہار کرنے پر قادر تھا تو اسے اللہ تعالیٰ تمام مخلوقات کے سامنے بلائے گا اور اختیار دے دے گا کہ جس حور کو چاہو اپنے لیے منتخب کرلو۔‘‘(مسند أحمد)اس روایت کو امام ابوداؤد، ترمذی اور ابن ماجہ رحمہ اللہ نے روایت کیا ہے اور امام ترمذی رحمہ اللہ نے حسن غریب کہا ہے۔ (سنن أبی داؤد : 4777، جامع الترمذی: 2021)\nابن مردویہ رحمہ اللہ نے حضرت عبداللہ بن عمر رضی اللہ عنہما کی اس حدیث کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بندے نے کبھی ایسا گھونٹ نہیں پیا جو اس غصے کے گھونٹ سے افضل ہو جسے بندہ اللہ تعالیٰ کی رضا کے حصول کے لیے پیتا ہے۔‘‘(مسند أحمد)اسے امام ابن ماجہ رحمہ اللہ نے بھی روایت کیا ہے۔(سنن ابن ماجہ : 4189) اور فرمان الٰہی : ﴿وَالْكٰظِمِيْنَ الْغَيْظَ﴾ ’’اور غصے کو روکتے ہیں۔ ‘‘ یعنی لوگوں میں اپنے غصے کے مطابق عمل نہیں کرتے بلکہ ان سے اپنے شر کو روک لیتے ہیںاور اللہ تعالیٰ سے اس کے اجر و ثواب کی اُمید رکھتے ہیں۔\n﴿وَالْعَافِيْنَ عَنِ النَّاسِؕ﴾ ’’اورلوگوں کے قصور معاف کرتے ہیں۔‘‘ یعنی شر کو روکنے کے ساتھ ساتھ ان لوگوں کو معاف کر دیتے ہیں جو ان پر ظلم کریں اور کسی پر بھی وہ ناراضی کا اظہار نہیں کرتے۔ یہ اخلاق کی بلندی کی اکمل حالت ہے۔ اسی لیے فرمایا:﴿وَاللّٰهُ يُحِبُّ الْمُحْسِنِيْنَۚ۰۰۱۳۴﴾ ’’ اور اللہ نیکوکاروں کو دوست رکھتا ہے۔‘‘ یہ مقاماتِ احسان میں سے ہے۔حدیث میں ہے : ’’تین باتوں (کی حقیقت) پر میں قسم کھاتا ہوں : (1)صدقہ کرنے سے بندے کامال کم نہیں ہوتا۔ (2)معاف کر دینے سے اللہ بندے کی عزت میں اضافہ فرما دیتا ہے اور (3)جو اللہ تعالیٰ کے لیے تواضع اور انکسار سے کام لے، اللہ اسے سربلندی عطا فرماتا ہے۔ ‘‘(ابتدائی حصہ جامع الترمذی : 2325و مسند أحمد اور دوسرا حصہ صحیح مسلم : 2588)\nارشاد باری تعالیٰ ہے : ﴿وَالَّذِيْنَ اِذَا فَعَلُوْا فَاحِشَةً اَوْ ظَلَمُوْۤا اَنْفُسَهُمْ ذَكَرُوا اللّٰهَ فَاسْتَغْفَرُوْا۠ لِذُنُوْبِهِمْ١۪﴾ ’’اور جب کوئی کھلا گناہ یا اپنے حق میں کوئی اور برائی کر بیٹھتے ہیں تو اللہ تعالیٰ کو یاد کرتے اور اپنے گناہوں کی بخشش مانگتے ہیں۔‘‘ یعنی جب ان سے کوئی گناہ صاد ر ہو جائے تو توبہ واستغفار کرلیتے ہیں۔ امام احمد رحمہ اللہ نے سیدنا ابوہریرہ رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ایک بندے نے ایک گناہ کیا،پھر عرض کی: میرے رب ! میں نے ایک گناہ کیا ہے یا گناہ کا کام کیا ہے تو اسے معاف فرما دے تو اللہ عزوجل نے فرمایا: کہ میرے بندےنے گناہ کیا ہے تو کیا اسے یہ علم ہے کہ اس کا ایک رب ہے جو گناہ کومعاف کرتا ہے اور اس کی وجہ سے گرفت بھی کرتا ہے، میں نے اپنے بندے کو معاف کر دیا،پھر اس نے گناہ کا کام کیا یا ایک اور گناہ کیا اور عرض کی : میرے رب! میں نے ایک گناہ کیا ہے تو اسے معاف فرما دے، اللہ تبارک و تعالیٰ فرماتاہے : کیا میرے بندے کو یہ علم ہے کہ اس کا ایک رب ہے جو گناہ کو معاف کرتا اور اس کی وجہ سے گرفت بھی کرتاہے، میں نے اپنے بندے کومعاف کر دیا، پھر اس نے گناہ کا کام کیا یا ایک اور گناہ کیا اور عرض کی : یا رب! میں نے ایک گناہ کیا ہے تو میرا یہ گناہ معاف فرما دے تو اللہ عزوجل فرماتا ہے کہ میرے بندے کو یہ معلوم ہے کہ اس کا ایک رب ہے جو گناہ معاف فرماتا اور اس کی وجہ سے گرفت بھی کرتا ہے، میں نے اپنے بند ے کومعاف فرما دیا، پھر اس نے گناہ کا کام کیا یا وہ کہتا ہے میں نے ایک اور گناہ کیا ہے اور عرض کی : یا رب! میں نے گناہ کیا ہے تو میرے اس گناہ کو معاف فرما دے تو اللہ تعالیٰ نے فرمایا: کہ میرے بندے کو معلوم ہے کہ اس کا ایک رب ہے جو گناہ کو معاف فرماتا اور اس کی بنیاد پر گرفت بھی کرتا ہے، میں تمہیں گواہ بنا کر کہتاہوں کہ میں نے اپنے بندے کو معاف کر دیا، وہ جو چاہے عمل کرے۔ ‘‘(مسند أحمد) امام بخاری نے بھی اپنی صحیح میں اس حدیث کو تقریباً اسی طرح بیان فرمایا ہے۔ (صحیح البخاری : 7507، و صحیح مسلم : 2758)\nامام عبدالرزاق رحمہ اللہ نے سیدنا انس بن مالک رضی اللہ عنہ سے مروی حدیث کو بیان کیا ہے کہ مجھے یہ بات پہنچی ہے کہ جب یہ آیت کریمہ نازل ہوئی : ﴿وَالَّذِيْنَ اِذَا فَعَلُوْا فَاحِشَةً اَوْ ظَلَمُوْۤا اَنْفُسَهُمْ ذَكَرُوا اللّٰهَ فَاسْتَغْفَرُوْا۠ لِذُنُوْبِهِمْ١۪﴾ ’’اور وہ لوگ جب کوئی بُرا کام کر بیٹھتے ہیں یا اپنے نفسوں پر ظلم کر گزرتے ہیں تو اللہ تعالیٰ کو یاد کرتے ہیں، پھر اپنے گناہوں کی بخشش مانگتے ہیں۔‘‘ تو ابلیس بہت رویا تھا۔ (تفسیر عبدالرزاق : 414/1)﴿وَمَنْ يَّغْفِرُ الذُّنُوْبَ اِلَّا اللّٰهُ١۪۫﴾ ’’اور اللہ تعالیٰ کے سوا گناہ بخش بھی کون سکتا ہے ؟‘‘ یعنی اس کے سوا اور کوئی نہیں بخش سکتا۔ ﴿وَلَمْ يُصِرُّوْا عَلٰى مَا فَعَلُوْا وَهُمْ يَعْلَمُوْنَ۰۰۱۳۵﴾ یعنی وہ اپنے گناہوں سے توبہ کر لیتے ہیں، اللہ تعالیٰ کی طرف جلد ہی رجوع کر لیتے ہیں، معصیت پر اڑے نہیں رہتے اور نہ اس پر اصرار کرتے ہیں، خواہ ان سے بار بار گناہ ہو، پھر بھی اس سے توبہ کر لیتے ہیں۔ ﴿وَهُمْ يَعْلَمُوْنَ۰۰۱۳۵﴾ ’’اور وہ جانتے ہیں۔‘‘\nمجاہد اور عبداللہ بن عبید بن عمیر رحمہ اللہ نے کہا ہے کہ وہ یہ جانتے ہیں کہ جو اللہ تعالیٰ کے حضور توبہ کرلے تو اللہ تعالیٰ اس کی توبہ قبول فرمالیتا ہے۔(تفسیر ابن أبی حاتم : 767/7) جیسا کہ اللہ تعالیٰ نے فرمایا ہے : ﴿اَلَمْ يَعْلَمُوْۤا اَنَّ اللّٰهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهٖ﴾ (التوبۃ:104) ’’کیا یہ لوگ نہیں جانتے کہ بے شک اللہ تعالیٰ ہی اپنے بندوں سے توبہ قبول فرماتاہے؟‘‘ اورفرمایا:﴿وَمَنْ يَّعْمَلْ سُوْٓءًا اَوْ يَظْلِمْ نَفْسَهٗ ثُمَّ يَسْتَغْفِرِ اللّٰهَ يَجِدِ اللّٰهَ غَفُوْرًا رَّحِيْمًا۰۰۱۱۰﴾ (النساء:110) ’’اور جو شخص کوئی بُرا کام کر بیٹھے یا اپنے حق میں ظلم کر لے، پھر اللہ تعالیٰ سے بخشش مانگے تو اللہ تعالیٰ کو بخشنے والا (اور) مہربان پائے گا۔‘‘ اسی کی نظیر اور بھی بہت سی آیات ِ کریمہ ہیں۔\nامام احمد رحمہ اللہ نے حضرت عبداللہ بن عمرو رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے منبر پر فرمایا:’’تم رحم کرو تم پر بھی رحم کیا جائے گا، تم معاف کرو تمہیں بھی معاف کیا جائے گا، ان لوگوں کے لیے تباہی و بربادی ہے جو بات کو سنتے تو ہیں مگر اسے یاد نہیں رکھتے (توجہ نہیں دیتے) اور ان اصرار کرنے والوں کے لیے بھی ہلاکت ہے جو جانتے بوجھتے ہوئے بھی اپنے گناہوں پر اصرار کرتے ہیں۔(مسند أحمد و شعب الإیمان للبیہقی : 7236) پھر اللہ تعالیٰ نے اپنے ان بندوں کے اوصاف کو بیا ن کرنے کے بعد فرمایا ہے :﴿اُولٰٓىِٕكَ جَزَآؤُهُمْ مَّغْفِرَةٌ مِّنْ رَّبِّهِمْ﴾ ’’وہی لوگ ہیں جن کا صلہ ان کے رب کی طرف سے بخشش ہے۔ ﴿وَجَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ﴾اور باغ ہیں جن کے نیچے نہریں بہہ رہی ہیں۔‘‘ جو انواع واقسام کے مشروبات کی ہوں گی ﴿خٰلِدِيْنَ فِيْهَاؕ﴾ ’’(وہ) ان میں ہمیشہ (بستے) رہیں گے۔﴿وَنِعْمَ اَجْرُ الْعٰمِلِيْنَؕ۰۰۱۳۶﴾اور (اچھے) کام کرنے والوں کا بدلہ بہت اچھا ہے۔ ‘‘ یہ اللہ تعالیٰ نے جنت کی تعریف بیان فرمائی ہے۔\nپھر اللہ تبارک و تعالیٰ نے مغفرت اور جنت کی طرف سبقت کرنے کا حکم دیا ہے جس کی چوڑائی زمین و آسمان کے برابر ہے، تب اس کی لمبائی کا کیا حال ہوگا، اللہ تعالیٰ نے اس کو متقین کے لیے تیار کر رکھاہے۔ متقین ہی اس جنت کے وارث ہیں اور اعمال تقویٰ ہی جنت تک پہنچاتے ہیں۔ پھر اللہ تعالیٰ نے متعین اور ان کےا عمال کا وصف بیان کرتے ہوئےفرمایا: ﴿الَّذِيْنَ يُنْفِقُوْنَ فِي السَّرَّآءِ وَالضَّرَّآءِ﴾ ’’یعنی وہ تنگی اور فراخی میں اللہ تعالیٰ کے راستے میں خرچ کرتے ہیں۔‘‘ یعنی جب وہ مال دار ہوتے ہیں تو اللہ تعالیٰ کے راستے میں کثرت سے خرچ کرتے ہیں اور جب تنگدست ہوتے ہیںتو وہ نیکی کے کسی کام کو حقیر نہیں سمجھتے خواہ وہ کتنا ہی معمولی کیوں نہ ہو۔ ﴿وَالْكٰظِمِيْنَ الْغَيْظَ﴾ یعنی جب ان کو دوسروں کی طرف سے کوئی ایسی تکلیف پہنچتی ہےجو ان کے غصے کا موجب ہوتی ہے۔ یہاں (غَيْظٌ) سے مراد ان کے دلوں کا ایسے غصے سے لبریز ہونا ہے جو قول و فعل کے ذریعے سے انتقام کا موجب ہوتا ہے۔ یہ اہل تقویٰ طبائع بشری کے ان تقاضوں پر عمل نہیں کرتے بلکہ ان کے دلوں میں جو غصہ ہوتا ہے اسے دبا دیتے ہیں اور برا سلوک کرنے والے کے مقابلے میںصبر سے کام لیتے ہیں۔ ﴿وَالْعَافِيْنَ عَنِ النَّاسِؕ﴾ لوگوںکو معاف کر دینے میں ہر اس شخص کو معاف کر دینا شامل ہے جو آپ کے ساتھ قول و فعل کے ذریعے سے برائی سے پیش آتا ہے۔\n(عفو) (کظم) سے زیادہ بلیغ ہے کیونکہ ’’عفو‘‘ برائی کرنے والے سے درگزر کرنے کے ساتھ، مؤاخذہ ترک کرنے کا نام ہے۔ یہ سب کچھ وہی شخص کر سکتا ہے جس نے اپنے آپ کو اخلاق جمیلہ سے آراستہ اور عادت رزیلہ سے پاک کر لیا ہو اور وہ ان میں سے جس کی تجارت اللہ تعالیٰ کے ساتھ ہو۔ جو اللہ کےبندوں پرر حم اور احسان کرتے ہوئے اور اس خوف سے کہ کہیں ان کو برائی نہ پہنچے ان کو معاف کر دیتا ہے تاکہ اللہ تعالیٰ اسے معاف کر دے اور اس کا اجر اس کے رب کریم پر واجب ہو، نہ کہ اس بندۂ فقیر پر۔ جیسا کہ اللہ تعالیٰ فرماتا ہے: ﴿فَمَنْ عَفَا وَاَصْلَحَ فَاَجْرُهٗ عَلَى اللّٰهِؕ﴾ (الشوریٰ : 40) ’’جو کوئی معاف کر دےا ور معاملے کی اصلاح کر دے تو اس کا اجر اللہ کے ذمے ہے۔‘‘\nپھر اللہ تعالیٰ نے (بندۂ مومن کے) ایسے حال کا ذکر فرمایا ہے جو دیگر احوال سے زیادہ عام، احسن و اعلیٰ اور زیادہ جلیل القدر ہے اور وہ ہے احسان۔ فرمایا ﴿وَاللّٰهُ يُحِبُّ الْمُحْسِنِيْنَۚ۰۰۱۳۴﴾ ’’اللہ احسان کرنے والوں کو پسند فرماتا ہے۔‘‘ احسان کی دو قسمیں ہیں۔ (1) اللہ تعالیٰ کی عبودیت میں احسان۔ (2) اللہ تعالیٰ کی مخلوق کے ساتھ احسان۔\nخالق کی عبودیت میں احسان کی تفسیر رسول اللہ صلی اللہ علیہ وسلم نے ان الفاظ میں کی ہے: «اَنْ تَعْبُدَ اللهَ كَاَنَّكَ تَرَاهُ فَاِنْ لَمْ تَكُنْ تَرَاهُ فَاِنَّهُ يَرَاكَ» (صحیح البخاری : 50، و صحیح مسلم : 1) ’’احسان یہ ہے کہ تو اللہ کی بندگی اس طرح کرے گویا کہ تو اسے دیکھ رہا ہے اور اگر تو اسے دیکھ نہیں رہا تو پھر وہ تجھے دیکھ رہا ہے۔‘‘ رہا مخلوق کے ساتھ احسان تو یہ ان کو دینی اور دنیاوی نفع پہنچانے اور ان سے دینی اور دنیاوی شر کو ہٹانے اور دور کرنے کانام ہے۔ چنانچہ امر بالمعروف، نہی عن المنکر، جاہل کو تعلیم دینا، غافل کو وعظ ونصیحت کرنا، مسلمان عوام اور خواص کی خیر خواہی کرنا اور ان کو متحد رکھنے کی کوشش کرنا یہ تمام امور مخلوق کے ساتھ احسان کے زمرے میں آتے ہیں۔ نیز لوگوں کے مختلف احوال اور متباین اوصاف کے مطابق ان تک واجب اور مستحب صدقات وغیرہ پہنچانا بھی احسان ہی میں شامل ہے۔ پس سخاوت کرنا، لوگوں کی تکالیف رفع کرنا خود تکالیف برداشت کرنا احسان ہے۔ جیسا کہ انہی آیات کریمہ میں اللہ تعالیٰ نے اہل تقویٰ کا وصف بیان فرمایا ہے۔ پس جس نے مذکورہ بالا امور کو قائم کیا اس نے اللہ اور اس کے بندوںکے حقوق کو ادا کیا۔\nپھر اللہ تعالیٰ نےا ہل ایمان کی اس معذرت کا ذکر فرمایا جو وہ اپنے جرائم اور گناہوں کے بارے میں اپنے رب کے سامنے پیش کرتے ہیں ﴿وَالَّذِيْنَ اِذَا فَعَلُوْا فَاحِشَةً اَوْ ظَلَمُوْۤا اَنْفُسَهُمْ﴾ یعنی جب کبھی ان سے کوئی بڑا یا چھوٹا گناہ صادر ہو جاتا ہے تو وہ فوراً توبہ اور استغفار کرتے ہیں، اور اپنے رب اور اس کی وعید کو یاد کرتے ہیں جو اس نے نافرمانوں کو سنا رکھی ہے اور اپنے رب کے اس وعدے کو یاد کرتے ہیں جو اس نے اہل تقویٰ سے کر رکھا ہے۔ پس وہ گناہوں کو ترک کرنے اور ان پر نادم ہونے کے ساتھ ساتھ اللہ تعالیٰ سے اپنے ان گناہوں کی مغفرت طلب کرتے ہیں اور اس سے اپنے عیوب پر پردہ پوشی کا سوال کرتے ہیں۔ بنا بریں اللہ تعالیٰ نے فرمایا: ﴿وَلَمْ يُصِرُّوْا عَلٰى مَا فَعَلُوْا وَهُمْ يَعْلَمُوْنَ۰۰۱۳۵﴾ ’’اور وہ جانتے ہوئے اپنی بداعمالیوں پر اڑتےنہیں ہیں‘‘ ﴿اُولٰٓىِٕكَ﴾ یعنی وہ لوگ جو ان صفات سے متصف ہیں ﴿جَزَآؤُهُمْ مَّغْفِرَةٌ مِّنْ رَّبِّهِمْ﴾ ’’ان کی جزا مغفرت ہے ان کے رب کی طرف سے۔‘‘ اور یہ مغفرت ان کے ہر گناہ کو زائل کر دے گی۔ ﴿وَجَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ﴾ ان جنتوں میں ہمیشہ رہنےو الی نعمتیں، شادمانی، خوبصورتی، رونق، بھلائی، مسرت، عالی شان محل، خوبصورت اور بلند منازل، پھلوں سے لدے ہوئے خوش کن درخت، اور ان خوبصورت مساکن و منازل میں نہریں بہہ رہی ہوں گی ﴿خٰلِدِيْنَ فِيْهَاؕ﴾ وہ ان جنتوںمیں ہمیشہ رہیں گے انہیں وہاں سے نکالا جائے گانہ وہ ان جنتوں کے بدے میں کچھ اور چاہیں گے اور نہ ان نعمتوں کو، جن میں وہ رہتے ہوں گے بدلہ جائے گا۔ ﴿وَنِعْمَ اَجْرُ الْعٰمِلِيْنَؕ۰۰۱۳۶﴾ ’’اور عمل کرنے والوں کا اجر اچھا ہے‘‘ یعنی انہوں نے اللہ تعالیٰ کی خاطر تھوڑا عمل کیا مگر ان کو بہت زیادہ اجر عطا ہوا۔ مشقت برداشت کرنے کے بعد ہی رحمت کی امید ہوتی ہے اور جزا کے وقت ہی عمل کرنے والے کو اپنے عمل کا پورا اور وافر بدلہ عطاہوتاہے۔\nیہ آیات کریمہ مرجئہ کے برعکس اہل سنت والجماعت کے اس موقف پر دلالت کرتی ہیں کہ اعمال ایمان میں داخل ہیں اور آیت کریمہ سے استدلال کا پہلو سورۃ الحدید کی اس آیت کو ملا کر مکمل ہوتا ہے جو کہ اس آیت کی نظیر ہے ﴿سَابِقُوْۤا اِلٰى مَغْفِرَةٍ مِّنْ رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَآءِ وَالْاَرْضِۙ اُعِدَّتْ لِلَّذِيْنَ اٰمَنُوْا بِاللّٰهِ وَرُسُلِهٖؕ﴾ (الحدید: 21) ’’اپنے رب کی بخشش اور جنت کی طرف لپکو جس کی چوڑائی زمین و آسمان کی چوڑائی کی مانند ہے جسے ان لوگوں کے لیے تیار کیا گیا ہے جو اللہ اور اس کے رسولوں پر ایمان لائے ہیں۔‘‘\nاس آیت کریمہ میں صرف اللہ تعالیٰ اور اس کے رسولوں پر ایمان کا ذکر کیا گیا ہے جبکہ یہاں اللہ تعالیٰ نے فرمایا: ﴿اُعِدَّتْ لِلْمُتَّقِيْنَۙ۰۰۱۳۳﴾ ’’جنت متقین کے لیے تیار کی گئی ہے‘‘ پھر متقین کے اعمال عالیہ اور اعمال بدنیہ بیان فرمائے۔ جس سے ثابت ہوا کہ وہ متقین، جو ان صفات سے متصف ہیں، وہی مومن ہیں۔\nواقعہ اُحد کے بیان میں ’’سُود‘‘ کا بیان اچانک آگیا ہے، اس کا سبب یہ معلوم ہوتا ہے کہ ابھی آیت (120) اور (125) میںیہ بتایا گیا ہے کہ فتح و نصرت کاراز صبر و تقویٰ میں مضمر ہے، اور تقویٰ ہی دنیا وآخرت کی ہر کامیابی کا ذریعہ تو طبعی طور پر ذہنوں میں تقویٰ کی صفات جاننے کا شوق پیدا ہوا، اس لیے اللہ تعالیٰ نے (جنگ اُحد کی مزید تفصیلات بیان کرنے سے پہلے) تقویٰ کی اہم صفات کو بیان کیا اوریہی وجہ ہے کہ یہاں سود سے متعلق آیتوں میں تین بار لفظ (تقویٰ) کو دہرایا گیا ہے، گویا سود نہ لینا تقویٰ کی اہم صفت ہے۔ ایک دوسرا سبب یہ بھی معلوم ہوتا ہے کہ جنگ اُحد میں فتح، شکست میں اس وجہ سے بدل گئی کہ تیر انداز مسلمان مال کی لالچ میں پڑ گئے، اور لالچ اور دولت پرستی کی سب سے گھنائونی صورت ’’سود‘‘ ہے، اسی لیے اللہ نے اس سے منع فرمایا اور اپنی راہ میں خرچ کرنے والوں کی فضیلت بیان کی۔\nزمانۂ جاہلیت میں جب قرض کی مدت پوری ہوجاتی، تو قرض والا کہتا کہ تم میری رقم واپس کر و، یا میں مدت بڑھا دیتا ہوں اور تم رقم میں اضافہ کرو۔ آیت میں لفظ ’’ایمان‘‘ کے ساتھ خطاب سے اس طرف اشارہ ہے، کہ ایمان کا تقاضا سود کو چھوڑ دینا ہے اور سورۂ بقرہ میں سودی کاروبار کو اللہ کے رسول سے جنگ کہا گیا ہے۔ کئی گنا بنا کر سود لینے کاذکر، زمانۂ جاہلیت کی عادت بیان کرنے کے لیے کیا گیا ہے، کہ وہ لوگ ایسا کرتےتھے۔ ورنہ سود تو ہر حال میں حرام ہے، چاہے کم ہو یا زیادہ، اور تقویٰ کا تقاضا یہی ہے کہ سود نہ لیا جائے۔\nآیت (131) میں سود خوروں کو اُس آگ سے ڈرایا گیا ہے جو کافروں کے لیے تیار کی گئی ہے۔ معلوم ہوا کہ سود خوری کبھی آدمی کو کفر تک لے جا سکتی ہے۔ امام ابو حنیفہ رحمہ اللہ سے مروی ہےوہ کہتے تھے کہ قرآن کریم میں یہ آیت سب سے زیادہ خوف دلانے والی ہے، کہ اگر مسلمانوں نے تقویٰ کی راہ اختیار نہ کی تو اس آگ کا سامنا کرنا پڑے گا جو کافروں کے لیے تیار کی گئی ہے۔\nآیت (132) میں مزید تاکید کے طور پر اللہ نے ایمان والوں کو حکم دیا کہ وہ اللہ اور اس کےر سول کی اطاعت کریں اور سود لینا یکسر بند کر دیں، تاکہ اللہ کی رحمت ان کے شامل حال ہو۔\nآیت (133) میںاللہ تعالیٰ نے نصیحت کی ہے کہ ایمان والے ان اعمال صالحہ کی طرف سبقت کریں جو اللہ کی مغفرت کا سبب بنتے ہیں اور جن کی وجہ سے اللہ اپنے فضل و کرم سے انہیں اس جنت میں داخل کرے گا جس کی وسعت آسمانوں اور زمین کے برابر ہے اور جو متقیوں کے لیے تیار کی گئی ہے۔\nیہاں جنت کی وسعت آسمانوں اور زمین کے برابر بتائی گئی ہے۔ بعض نے کہا ہے کہ یہ جنت کی حقیقی وسعت ہے اور اس کا ذکر یہاں اس لیے آیا ہے تاکہ معلوم ہو کہ اس کا طول اس کے عرض سے یقینا زیادہ ہوگا۔ دوسرا قول یہ ہے کہ یہاں مقصود صرف یہ بتانا ہے کہ اللہ کی جنت ہمارے گمان سے بہت ہی زیادہ وسیع ہوگی۔\nآیت (134) میں اہل جنت کی صفت بیان کی گئی ہے کہ وہ لوگ وسعت اور تنگی ہر حال میں اللہ کی راہ میں خرچ کرتے ہیںاور جب انہیں غصہ آتا ہے تو اسے پی جاتے ہیں اور ا س پر عمل نہیں کرتے۔ امام احمد رحمہ اللہ نے جاریہ بن قدامہ السندی رحمہ اللہ سے روایت کی ہے، انہو ں نے رسول اللہ صلی اللہ علیہ وسلم سے کہا کہ ’’اے اللہ کےر سول! مجھے کوئی نفع بخش بات بتائیے، لیکن لمبی بات نہ ہو تاکہ میں اسے یاد کر لوں، توآپ صلی اللہ علیہ وسلم نے فرمایا: غصہ مت کرو، صحابی نے بار بار اپنا سوال دہرایا، اور ہر بار آپ صلی اللہ علیہ وسلم نے ان سے یہی کہا: غصہ مت کرو۔‘‘ اہل جنت کی صفات میں سے یہ بھی ہے کہ اگر کوئی ان کے ساتھ بدسلوکی کرتا ہے تو اُسے معاف کر دیتے ہیں، اور اپنے دل میں اس کے خلاف کوئی بغض و کینہ نہیں رکھتے۔ اللہ تعالیٰ نے سورۂ شوریٰ آیت (37) میں فرمایا ہے: ﴿وَاِذَا مَا غَضِبُوْا هُمْ يَغْفِرُوْنَۚ۰۰۳۷﴾ کہ جب انہیں غصہ آتا ہے تو لوگوں کو معاف کر دیتے ہیں۔\nاہل جنت کی ایک اور صفت یہ بتائی گئی کہ جب ان سے کبیرہ یا صغیرہ گناہ کا ارتکاب ہو جاتا ہے، تو انہیں اللہ سے حیاآتی ہے، اور اس کے عقاب (عذاب و سزا) کا ڈر لاحق ہوجاتا ہے، تو فوراً اللہ سے معافی مانگتے ہیں، اور اللہ کے علاوہ گناہوں کو کون معاف کر سکتا ہے؟ اس کے سوا کسے اس کا اختیار حاصل ہے؟ امام احمد رحمہ اللہ نےابو سعید خدری رضی اللہ عنہ سے روایت کی ہے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے سنا ہے کہ ابلیس نے اپنے رب سے کہا تیری عزت و جلال کی قسم، میں بنی آدم کو جب تک ان کی سانس چلتی رہے گی گمراہ کرتا رہوں گا، تو اللہ نے کہا، میری عزت و جلال کی قسم! جب تک وہ مجھ سے مغفرت چاہتےر ہیں گے، میں انہیں معاف کرتارہوں گا۔\nاور اس طلب مغفرت والی صفت کی تکمیل یہ ہے کہ وہ جانتے ہوئےگناہ پر اصرار نہیں کرتے، یعنی اگر گناہ ہوجاتا ہے تو استغفار کرتے ہیں، کیونکہ دل سے استغفار کر لینے کے بعد اگر دوبارہ اسی گناہ کا ارتکاب ہوجاتا ہے تو اسے گناہ پر اصرار نہیں کہا جاتا۔ا بو داؤد، ترمذی، بزار اور ابویعلیٰ نے ابوبکر رضی اللہ عنہ سے روایت کی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کہ جس نے اللہ سے مغفرت مانگ لی اس نے گناہ پر اصرار نہیں کیا، چاہے وہ دن میں سو بار اس کا ارتکاب کرے۔ حافظ ابن کثیر رحمہ اللہ نے اس حدیث کو ’’حسن‘‘ کہا ہے۔ امام احمد رحمہ اللہ نے علی بن ابی طالب رضی اللہ عنہ سے اور انہوںنے ابوبکر رضی اللہ عنہ سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب کوئی آدمی گناہ کرتا ہے، تواس کے بعد اچھی طرح وضو کرتا ہے، پھر دو رکعت نماز پڑھ کر اللہ سے مغفرت طلب کرتا ہے تو اسے اللہ اسے معاف کر دیتا ہے۔\nآیت (136) میں مذکورہ بالا صفات والوں کے لیے یہ اجر و ثواب بتایا گیا ہے کہ اللہ ان کے تمام گناہ معاف کر دے گا، اور انہیں جنت میں داخل کر دے گا، جس کے نیچے نہریں جاری ہوں گی، جس میں وہ ہمیشہ کے لیے رہیں گے۔"],[879,"§سود کی حرمت میں تدریج\nسود کی حرمت کا ذکر سورۂ بقرہ کی آیات (278-279)میں گزر چکا ہے۔ یہ آیت اس سے پہلے کی نازل شدہ ہے۔ جبکہ مسلمانوں کو سود کی قباحتوں سے متعارف کرانا اس سے نفرت دلانا اور اس کو یکسر چھوڑ دینے کے لیے ذہنوں کو ہموار کرنا مقصود تھا۔ اس مقام پر سود کے ذکر کی وجہ مناسبت یہ معلوم ہوتی ہے کہ جنگ اُحد میں ابتداء ً مسلمان جو شکست سے دو چار ہوئے تو اس کا بڑا سبب یہ تھا کہ مسلمانوں کا وہ راستہ جو سیدنا عبداللہ بن جبیر رضی اللہ عنہ کی سرکردگی میں درہ کی حفاظت پر مامور تھا، اس نے جب فتح کے آثار دیکھے تو مال کے طمع سے مغلوب ہو گئے اور اپنے کام کو تکمیل تک پہنچانے کے بجائے غنیمت لوٹنے میں لگ گئے۔ اللہ تعالیٰ نے اس صورت حال کی اصلاح کے لیے زرپرستی کے سرچشمے پر بند باندھنا ضروری سمجھا کیونکہ سود کا خاصہ یہ ہے کہ وہ سود خوار میں حرص و طمع، بخل وبزدلی، خود غرضی اور زرپرستی جیسی رذیل صفات پیدا کر دیتاہے اور سود ادا کرنے والوں میں نفرت، غصہ، بغض و حسد جیسی صفات پیدا ہو جاتی ہیں، اور ایسی صفات ایک اسلامی معاشرہ کے لیے سم قاتل کی حیثیت رکھتی ہیں اور جہاد کی روح کے منافی ہیں اور آخرت میں اُخروی عذاب کا سبب بنتی ہیں۔ انھی وجوہ کی بنا پر سود کو بالآخر مکمل طورپر حرام قرار دیاگیا۔"],[880,"§سیدالاستغفار\nاللہ کی مغفرتکی طرف دوڑ کر جانے کا مطلب یہ ہے کہ ایسے کام بلا تاخیر کیے جائیں، جو اللہ کی مغفرت کا سبب بن سکتے ہیں اور وہ تمام اعمال صالحہ ہیں۔ علاوہ ازیں اللہ تعالیٰ سے استغفار کرنا بذات خود اللہ کی بخشش کا بہت بڑا سبب ہے۔ استغفار کے لیے کتاب و سنت میں بہت سی دعائیں منقول ہیں اور ایک دعائے استغفار کو تو رسول اللہ صلی اللہ علیہ وسلم نے سید الاستغفار فرمایا: آپ نے یہ استغفار صحابہ کرام کو سکھایا اور صبح و شام نمازوں کے بعد یہ استغفار پڑھا کرتے تھے۔ اس استغفار کے الفاظ یہ ہیں : «اللَّهُمَّ أَنْتَ رَبِّي، لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُبِكَ مِنْ شَرِّ مَا صَنَعْتُ، وَأَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِيْ، فَاغْفِرْ لِيْ فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ» ”اے اللہ تو ہی میرا پروردگار ہے۔ تیرے سوا کوئی الٰہ نہیں تو نے ہی مجھے پیدا کیا اور میں تیرا بندہ اور غلام ہوں اور جہاں تک مجھ سے ہوسکتا ہے میں تیرے عہد اور تیرے وعدے پر قائم ہوں اور جو کچھ میں کرتا ہوں اس کے برے پہلو سے تیری پناہ چاہتا ہوں۔ میں اپنے آپ پر تیری نعمتوں کا اقرار کرتا ہوں اور اپنے گناہوں کا بھی اعتراف کرتا ہوں۔ لہٰذا تو مجھے معاف فرما دے کیونکہ تیرے بغیر کوئی بھی گناہ معاف نہیں کر سکتا۔“\nاور جنت کی طرف دوڑ کر آنے کا بھی یہی مقصد ہے کہ ایسے کام کیے جائیں جن سے جنت کا حصول ممکن ہو جائے اور جنت کی صفت یہ بیان فرمائی کہ اس کا عرض آسمانوں اور زمین جیسا ہے اور عرض کا ایک معنی تو چوڑائی ہے۔ اس لحاظ سے اس کامطلب یہ ہوگا کہ جب آسمانوں اور زمین کی وسعت کا اندازہ کرنا انسان کی بساط سے باہر ہے تو پھر وہ جنت کی وسعت کا کیا اندازہ کر سکے گا۔ جس کی چوڑائی آسمانوں اور زمین کے برابر ہے گویا اس سے مقصود جنت کی ایسی لا محدود وسعت کا اظہار ہے جو انسان کے سان و گمان میں بھی نہیں آسکتی۔"],[881,"§جنت کی قدر و قیمت\nعرض کا دوسرا معنی قدر و قیمت ہے۔ کہتے ہیں ”اشتریت المتاع بعرض“اور ان معنوں میں یہ لفظ قرآن میں بھی مستعمل ہے۔ جب دنیا کی بے ثباتی کا اظہار مقصود ہو تو دنیوی سازوسامان کے لیے یہ لفظ استعمال ہوتاہے۔ اس لحاظ سے اس کا معنی یہ ہوگا کہ اس جنت کی طرف دوڑ کر آؤ جس کے مقابلہ میں یہ سارے آسمان اور زمین ہیچ ہیں اور جنت کی قدر و قیمت ان سب سے بڑھ کر ہے۔\nضمناً ایسی آیات سے یہ بھی معلوم ہوتا ہے کہ جنت اور دوزخ تیار کی جا چکی ہے اور اس میں ان لوگوں کا ردّ ہے جو اس بات کے قائل نہیں۔\nاگر قرآنی آیات کی ترتیب پر غور کیا جائے تو صاف معلوم ہوتا ہے کہ اللہ تعالیٰ نے اگر کہیں دوزخ کا ذکر فرمایا تو اس کے ساتھ ہی جنت کا ذکر فرمایا اور اس کے برعکس بھی اسی طرح اگر کہیں اسباب دخول دوزخ کا ذکر فرمایا تو اسی مناسبت سے اسباب دخول جنت کاذکر فرمادیا اور اس کے برعکس بھی۔ یہاں بھی یہی صورت حال ہے۔ سو د خواری، جو دوزخ میں دخول کا سبب ہے، کے بعد جنت اور اس میں داخل ہونے والے پرہیزگاروں کی چند صفات کا ذکر فرمایا۔ ان میں سب سے پہلی صفت انفاق فی سبیل اللہ ہے جو سود خوری کی عین ضد اور معاشرہ پر اس کے اثرات سود کے اثرات کے بالکل برعکس ہوتے ہیں۔ مثلاً سود خوری سے سود خوار میں حرص و طمع، بخل اور زرپرستی جیسی صفات پیدا ہوتی ہیں اور سود دینے والے میں سود خورکے خلاف نفرت، بغض اور حسد پیدا ہوتاہے اور یہ صورت حال معاشرہ میں طبقاتی تقسیم پیدا کرکے کسی بڑے فتنہ کا پیش خیمہ بن جاتی ہے جبکہ صدقہ و خیرات دینے سے دینے والے کے دل میں بخل کےبجائے سماحت اور خوشی پیداہوتی ہے تو لینے والے کےدل میں احسان مندی اور شکر گزاری کے احساسات پیدا ہوتے ہیں۔ جس سے پورے معاشرے میں ایک دوسرے سے ہمدردی، مروت اوراخوت، اتفاق اتحاد اورمحبت جیسی صفات پیدا ہوتی ہیں اور یہی چیز ایک اسلامی معاشرہ کی روح رواں ہے اور اسی لیے کتاب وسنت میں انفاق فی سبیل اللہ پر بہت زور دیا گیا ہے اور زکاۃ فرض کی گئی ہے۔ اس آیت میں یہ بتلایاگیا ہے کہ متقین کی پہلی صفت یہ ہے کہ خواہ خوشحالی کا دور ہویا تنگدستی کا وہ ہر حال میں اپنی حیثیت اور وقت کے تقاضے کے مطابق اللہ کی راہ میں ضرورخرچ کرتے ہیں۔ چنانچہ آپ صلی اللہ علیہ وسلم نے کئی مواقع پر غریب مسلمانوں کو صدقہ کی ترغیب دیتے ہوئے فرمایا کہ : «⁠اتقوا النارولو بشق تمرة» (بخاری،کتاب الادب، باب طیب الکلام...) یعنی دوزخ کی آگ سے بچو خواہ کھجور کا ایک ٹکڑا ہی صدقہ دے کر بچو اور اس ترغیب سے مقصود بخل اور حرص جیسی مہلک بیماریوں کا علاج ہے۔"],[882,"§غصہ پی جانا اور معاف کرنا الگ الگ صفات ہیں\nمتقین کی دوسری صفت یہاں یہ بیان کی گئی ہے کہ وہ غصہ کو پی جاتے اور لوگوں کو معاف کر دیتے ہیں، غصہ ہمیشہ ایسے شخص پر آتا ہے جو اپنے سے کمزور ہو اور انسان اس سے انتقام لینے کی قدرت رکھتا ہو۔ ایسے وقت میں غصہ کو برداشت کرجانا فی الواقع بڑے حوصلہ کا کام ہے۔ اسی لیےآپ صلی اللہ علیہ وسلم نے فرمایا کہ بہادر وہ نہیں جو کسی دوسرے کو لڑائی سے بچھاڑ دے بلکہ بہادر وہ ہے جو غصہ کو برداشت کرجائے۔ نیز ایک دفعہ ایک آدمی نے آپ صلی اللہ علیہ وسلم سے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم!”مجھے کچھ وصیت فرمائیے،آپ نے فرمایا: غصہ نہ کیا کرو۔“ اس نے بار باروصیت کی درخواست کی اور آپ صلی اللہ علیہ وسلم ہر بار یہی جواب دیتے رہے کہ غصہ نہ کیا کرو۔“ (بخاری، کتاب الادب، باب الحذر من الغضب)\nغصہ پی جانا اور معاف کر دینا دو الگ الگ کام ہیں۔ یہ ممکن ہے کہ کوئی شخص وقتی طور پر غصہ پی جائے اور بات دل میں رکھے اور پھر کسی وقت اس سے انتقام لے لے۔ گویا غصہ پی جانے کے بعد قصور وار کو معاف کر دینا ایک الگ اعلیٰ صفت ہے اور اللہ ایسے ہی نیکوکار لوگوں سے محبت رکھتاہے جس میں یہ دونوں باتیں پائی جاتی ہوں۔"],[883,"§توبہ کی اہم شرائط\nآیت کے الفاظ سے صاف واضح ہے کہ پرہیز گار لوگ دیدہ دانستہ نہ کوئی برا کام کرتے ہیں اور نہ اپنے آپ پر ظلم کرتے ہیں بلکہ سہواً بہ تقاضائے بشریت ان سے ایسے کام سر زد ہوجاتے ہیں اور جب انھیں اپنی غلطی کا احساس ہو جاتا ہے تو فوراً اللہ کی طرف رجوع کرتے ہیں اور معافی مانگنے لگتے ہیں اور ایسے لوگوں کو اللہ تعالیٰ یقینا معاف بھی کر دیتاہے۔ یہاں یہ بات ملحوظ رکھنی چاہیے کہ اگر اس برے کام یا غلطی کا اثر صرف اپنی ذات تک محدود ہو تو پھر اللہ تعالیٰ غفور ورحیم ہے۔ وہ یقینا معاف فرما دے گا۔ لیکن اگر اس کا اثر دوسروں کے حقوق پر پڑتا ہو تو اس کی تلافی کرنا یا اس شخص سے قصور معاف کر وانا ضروری ہے اور یہ استغفار کی ایک اہم شرط ہے۔"],[884,"§توبہ کی فضیلت\nگناہ پر اصرار کرنا یا استغفار کرنے کے بعد وہی گناہ پھر کرتے جانا اصل گناہ سے بڑا گناہ ہے اور جو لوگ یہ کام کریں وہ یقینا متقی نہیں ہوتے۔ ہاں یہ ہو سکتا ہے کہ ایک گناہ سرزد ہو گیا تو اس کی معافی مانگ لی، پھر دوسرا ہو گیا۔ اس کی بھی اللہ سے معافی مانگ لی، پھر کوئی اور ہو گیا اس کی بھی معافی مانگ لی۔ اس طرح اگر دن میں ستر بار بھی اللہ سے معافی مانگی جائے تو اللہ تعالیٰ معاف فرما دیتا ہے کیونکہ انسان خطا کا پتلا ہے اور اللہ تعالیٰ خطا کار کے معافی مانگنے پر صرف اسے معاف ہی نہیں فرماتا بلکہ اس سے خوش بھی ہوتاہے اور حقیقت یہ ہے کہ گناہ کے بعد اس کی معافی نہ مانگنا بھی اس پر اصرار کے مترادف ہے جیسا کہ حدیث میں آیا ہے کہ جس شخص نے اپنے گناہ کی معافی مانگ لی۔ اس نے ضد نہیں کی اور دوسری حدیث میں ہےجس نے توبہ کی گویا اس نے گناہ کیا ہی نہ تھا۔ (ابن ماجہ، ابواب الزہد، ذکر التوبۃ)\n﴿اَضْعَافًا مُّضٰعَفَةً١۪﴾ کی وضاحت کرتے ہوئے ابن جریر رحمہ اللہ فرماتے ہیں مسلمانو! تم اسلام لانے کے بعد سود کو دوگنا تگنا کرکے نہ کھاؤ جیسا کہ تم دورِ جاہلیت میں کیا کرتے تھے دورِ جاہلیت کی وضاحت ملاحظہ کریں :\nایک شخص نے دوسرے انسان سے قرض رقم لی ہے کہ فلاں وقت اس کو ادا کروں گا جب ادائیگی کا وقت آتا ہے تو اس سے کہتا ہے آپ ادا کرنے میں مجھے کچھ مہلت دیں۔ مہلت کے نتیجہ میں، میں تجھے اصل مال سے مزید اتنا مال دوں گا اس پر دونوں رضا مند ہوجاتے ہیں چنانچہ اسلام میں اللہ پاک نے اس سے منع فرمایا ہے دورِ جاہلیت کا سود دراصل مرکب سود ہے جسے ان کے ہاں (رِبًا نَسِيئه)اُدھار کے سبب سود کہاجاتا ہے مزید تاخیر سے اس میں اضافہ ہوتا جاتا ہے۔ (مراغی : 65/2)"],[885,"§علامہ بقاعی رحمہ اللہ کا تبصرہ\nعلامہ بقاعی رحمہ اللہ فرماتے ہیں دنیوی مال ومتاع کی جانب کشش کا ہوناآخرت سے روگردانی کے مترادف ہے بلکہ سود کے ذریعہ مال حاصل کرنے کی جانب رغبت دلاتا ہے جسے سورۂ بقرہ میں اللہ تعالیٰ کے ساتھ لڑائی کرنے سے تعبیر کیا گیا ہے اس لیے سودی مال کو حرام قرار دیا ہے کیا یہ حقیقت نہیں ہے کہ غزوۂ اُحد میں صحابہ کرام رضی اللہ عنہم کو شکست اس سبب سے ہوئی کہ وہ مال غنیمت فراہم کرنے میں محو ہو گئے، دشمن نے درہ کو خالی پاکر حملہ کردیا نتیجتاً فتح شکست سے تبدیل ہوگئی بلکہ ستر (70)صحابہ کرا م رضی اللہ عنہم شہید ہو گئے اس لیے مال سے نفرت دلاتے ہوئے فرمایا: کہ تم سودی مال کے فراہم کرنے سے خود کو دور رکھو۔(نظم الدرر : 64/5)\nسودی کاروبار کی حرمت واضح ہے اگر کوئی شخص موت سے پہلے اس کاروبار سے تائب ہو جاتا ہے تو اس کی توبہ اللہ تعالیٰ کے ہاں مقبول ہوگی۔ سنن ابوداؤدمیں عمرو بن اقیش رضی اللہ عنہ کے بارے میں ذکر ہے کہ دورِ جاہلیت میں اس نے لوگوں سے سودی مال لینا تھا، اسے پسند نہ تھا کہ وہ سودی رقم حاصل کیے بغیر اسلام قبول کرے۔ جنگ اُحد کے روز وہ آیا اس نے پوچھا میرے چچا زاد بھائی کہاں ہیں لوگوں نے بتایا وہ میدان اُحد میں ہیں کچھ اورلوگوں کے بارے میں بھی اس نے استفسار کیا اسے بتایا گیا کہ وہ میدان اُحد میں ہیں۔ اس پر اس نے اپنے سر پر لوہے کی ٹوپی رکھی، گھوڑے پر سوار ہوا میدان جنگ کی جانب روانہ ہوا جب صحابہ کرام رضی اللہ عنہم نے اسے دیکھا تو انہوں نے اس سے کہا اے عمرو ! آپ ہمارے قریب نہ آئیں اس نے جواب میں اپنے ایمان لانے کی خبر دی۔ چنانچہ اس نے اس روز بہادری کے ساتھ دشمن پر حملہ کیا یہاں تک کہ وہ زخمی ہو گیا زخمی حالت میں اسے گھر لایا گیا اس دوران سعد بن معاذ رضی اللہ عنہ اس کے پاس آئے اس نے اس کی ہمشیرہ سے کہا آپ اس سے استفسار کریں قومی حمیت کے پیش نظر یا اللہ پاک کی رضا جوئی کے لیے وہ لڑائی کرتا رہااس نے جواب دیا صرف اللہ تعالیٰ کی رضا کے لیے بعد ازاں وہ فوت ہو گیا اس کو جنت میں داخلہ ملا۔ حالانکہ اس نے ایک نماز بھی ادا نہیں کی۔\n(نظم الدرر : 67/5، صحیح بخاری، ص:32)\n﴿وَاتَّقُوا النَّارَ الَّتِيْۤ اُعِدَّتْ لِلْكٰفِرِيْنَۚ۰۰۱۳۱﴾ دوزخ سے خود کو تحفظ عطا کرو جو ان لوگوں کے لیے تیا رکی گئی ہے جو اللہ تعالیٰ اور اس کےآخر الزماں پیغمبر صلی اللہ علیہ وسلم کی تکذیب کرتے ہیں جب وہ ان کے احکام کی اطاعت نہیں کرتے تو گویا وہ تکذیب کررہے ہیں۔ ظاہر ہے کہ جھٹلا ناہی اطاعت سے روکتا ہے۔\n﴿وَاَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ لَعَلَّكُمْ تُرْحَمُوْنَۚ۰۰۱۳۲﴾ اللہ اور اس کے پیغمبر صلی اللہ علیہ وسلم کی اطاعت کا انہیں حکم دیا گیا ہے۔ اطاعت کے نتیجہ میں ان پر دنیا اور آخرت میں رحمت ہوگی دراصل ان لوگوں کی جانب اشارہ ہے جنہوںنے جنگ اُحد میں رسول اللہ صلی اللہ علیہ وسلم کے حکم کی نافرمانی کی ان سے مقصود وہ تیر انداز ہیں جو دفاعی مرکز پر قائم نہ رہے غنیمت کے لالچ میں مرکز چھوڑ دیا اس کے نتیجہ میں مسلمان بدترین قسم کی شکست سے دوچار ہوئے۔\nپرہیز گاروں کے بدلہ کا ذکر ہے جب وہ خود کو دوزخ سے تحفظ عطا کریں گے گویا کہ ڈرانے کے بعد ترغیب دلائی گئی ہے اللہ پاک کا یہی انداز ہے کہ تم اللہ تعالیٰ کی مغفرت اور جنت کی جانب جلدی کرو یعنی مغفرت اور جنت کے اسباب بروئے کار لاؤ یعنی گناہ سے توبہ کرو۔ سود کے لین دین سے مکمل بائیکاٹ کرو اور صدقات خیرات کے عمل کو برقرار رکھو حرف تشبیہ اورمشبہ کو حذف کرکے ذکر کیا گیا ہے اس میں مبالغہ کا رفرما ہے اصل عبارت یوں ہے :عَرْضُهَا كَعَرضِ السَّمٰوٰتِ وَالاَرضِ۔\n﴿اُعِدَّتْ لِلْمُتَّقِيْنَۙ۰۰۱۳۳﴾ جنت کو ان کے لیے مہیا کیا گیا ہے جو پرہیز گارہیں۔ معلوم ہوا جنت کا تعلق بھی مخلو ق سے ہے نیز اس عالم سے وہ الگ ہے۔\n﴿الَّذِيْنَ يُنْفِقُوْنَ فِي السَّرَّآءِ وَالضَّرَّآءِ﴾ پرہیز گاروں کے پانچ اوصاف کا ذکر ہے کہ وہ فراخی، تنگی دونوں حالتوں میں مال خرچ کرتے رہتے ہیں۔ خیال رہے کہ پرہیز گاروں کے اس وصف کا پہلے ذکر کیا ہے کہ وہ فراخی، تنگی دونوں حالتوں میں مال خرچ کرتے رہتے ہیں۔ دراصل یہاں مقابلہ سود کے ساتھ ہے جس سے روکا گیا ہے جس کا ذکر اس سے پہلی آیت میں ہے اس لیے کہ سود خور شخص فقیر، محتاج انسان کی حاجت کو آسان انداز سے پورا نہیں کرتا اس کا سود لینا بلامقابلہ ہے یعنی خون چوسنا ہے جب کہ صدقہ و خیرات میں ضرورت مند کی اعانت ہے یہ توسراسر سود کی ضد ہے۔ مزید توجہ کریں قرآن پاک میں جہاں بھی سود کا ذکر ہوا ہے اسے قبیح انداز میں ذکر کیا گیا ہے جبکہ صدقہ، زکوٰۃ کا تذکرہ مدح و ستائش کے انداز میں بیان ہوا ہے۔ ارشاد ِ باری ہے :﴿وَمَاۤ اٰتَيْتُمْ مِّنْ رِّبًا لِّيَرْبُوَاۡ فِيْۤ اَمْوَالِ النَّاسِ فَلَا يَرْبُوْا عِنْدَ اللّٰهِۚ وَمَاۤ اٰتَيْتُمْ مِّنْ زَكٰوةٍ تُرِيْدُوْنَ وَجْهَ اللّٰهِ فَاُولٰٓىِٕكَ هُمُ الْمُضْعِفُوْنَ۰۰۳۹﴾ (الروم :39) ’’اور جو تم سود دیتے ہو کہ لوگوں کے مال میں افزائش ہو تو اللہ تعالیٰ کے نزدیک اس میں افزائش نہیں ہوتی اور جو تم زکوٰۃ دیتے ہواور اس سے اللہ تعالیٰ کی رضا مندی طلب کرتے ہو تو (وہ موجب برکت ہے اور) ایسے ہی لوگ (اپنے مال کو) دو چند سہ چند کرنے والے ہیں۔ ‘‘\n﴿وَالْكٰظِمِيْنَ الْغَيْظَ وَالْعَافِيْنَ عَنِ النَّاسِؕ﴾ جب انہیں بدنی یا مالی نقصان پہنچتا ہے یا ان کی عزت پر کوئی شخص حملہ آور ہوتاہے تو وہ اپنے غصہ کو روک لیتے ہیں یعنی ان کے جوارح پر اس کے اثرات دکھائی نہیں دیتے وہ خود کو انتقام کے مقام پر بٹھانے سے دور رکھتے ہیں اور جو لوگ ان کےساتھ بداخلاقی کا انداز اختیار کرتے ہیں وہ انہیں معاف کر دیتے ہیں اگرچہ وہ انتقام کی قدرت رکھتے تھے۔ ارشاد نبوی صلی اللہ علیہ وسلم ہے :’’وہ شخص بہادر نہیں ہے جو اپنے کسی بھائی کو زمین پر پچھاڑ دیتا ہے البتہ وہ انسان بہادر ہے جو اپنے غصہ پر کنٹرول کرتا ہے۔‘‘(صحیح بخاری : 1311)\n﴿وَالَّذِيْنَ اِذَا فَعَلُوْا فَاحِشَةً﴾ محسنین کے اوصاف بیان ہو رہے ہیں کہ جب ان سے کبیرہ گناہ سرزد ہو جاتا ہے یا وہ خود پر ظلم کرتے ہیں تو اللہ تعالیٰ کی ڈانٹ کی جانب متوجہ ہوتے ہیں توبہ کی جانب لپکتے ہیں پشیمانی ان کے دامن کو تھام لیتی ہے وہ عزم کرتے ہیں کہ مستقبل میں وہ اس گناہ کا ہر گزار تکاب نہیں کریں گے۔\n﴿اُولٰٓىِٕكَ جَزَآؤُهُمْ مَّغْفِرَةٌ﴾ ان کے ایمان لانے، تقویٰ اختیار کرنے دیگر نفسانی کمالات روحانی پاکیزگی اختیار کرنے پر ان کے تمام گناہ معاف ہو جائیں گے۔مزید برآں ان کی رہائش جنات میں ہوگی جن کے نیچے نہریں جاری رہیں گی ہمیشہ ہمیشہ وہاں رہیں گے ان لوگوںکو کتنا اچھا اور بہتر بدلہ دیا گیا ہے جو اللہ تعالیٰ کی رضا کے حصول کے لیے زندگی بھر صراط مستقیم پر رواں دواں رہے اور ان کے اعمال کتاب و سنت کی روشنی میں انجام پائے۔\n﴿قَدْ خَلَتْ مِنْ قَبْلِكُمْ سُنَنٌۙ فَسِيْرُوْا فِي الْاَرْضِ فَانْظُرُوْا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِيْنَ۠۰۰۱۳۷ هٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَّمَوْعِظَةٌ لِّلْمُتَّقِيْنَ۠۰۰۱۳۸ وَلَا تَهِنُوْا وَلَا تَحْزَنُوْا وَاَنْتُمُ الْاَعْلَوْنَ اِنْ كُنْتُمْ مُّؤْمِنِيْنَ۰۰۱۳۹ اِنْ يَّمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ الْقَوْمَ قَرْحٌ مِّثْلُهٗؕ وَتِلْكَ الْاَيَّامُ نُدَاوِلُهَا بَيْنَ النَّاسِۚ وَلِيَعْلَمَ اللّٰهُ الَّذِيْنَ اٰمَنُوْا وَيَتَّخِذَ مِنْكُمْ شُهَدَآءَؕ وَاللّٰهُ لَا يُحِبُّ الظّٰلِمِيْنَۙ۰۰۱۴۰ وَلِيُمَحِّصَ اللّٰهُ الَّذِيْنَ اٰمَنُوْا وَيَمْحَقَ الْكٰفِرِيْنَ۰۰۱۴۱ اَمْ حَسِبْتُمْ اَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَعْلَمِ اللّٰهُ الَّذِيْنَ جٰهَدُوْا مِنْكُمْ وَيَعْلَمَ الصّٰبِرِيْنَ۰۰۱۴۲ وَلَقَدْ كُنْتُمْ تَمَنَّوْنَ الْمَوْتَ مِنْ قَبْلِ اَنْ تَلْقَوْهُ١۪ࣕ فَقَدْ رَاَيْتُمُوْهُ وَاَنْتُمْ تَنْظُرُوْنَࣖ۰۰۱۴۳﴾\nتم سے پہلے بھی ایسے واقعات گزر چکے ہیں، چنانچہ تم زمین میں چل پھر کر دیکھو کہ (نبیوں کو) جھٹلانے والوں کا انجام کیا ہوا؟\nیہ (قرآن) لوگوں کے لیے وضاحت اور پرہیز گاروں کے لیے ہدایت اور نصیحت ہے\nاور تم سستی نہ کرو، اور نہ غم کھائو، تم ہی غالب رہو گے اگرتم مومن ہو\nاگر تمہیں (احد میں) زخم لگے ہیں تو ایسے ہی زخم (بدر میں) کافروں کو بھی لگ چکے ہیں۔ ہم ان دنوں کو لوگوں کے درمیان ادل بدل کرتے رہتے ہیں۔ اور (تمہیں یہ زخم اس لیے لگے کہ) اللہ جاننا چاہتا تھا کہ کون ایمان والے ہیں؟ اور وہ تم میں سے بعض کو شہادت کا مرتبہ دینا چاہتا تھا اور اللہ ظالموں کو پسند نہیں کرتا\nاور (ایک وجہ یہ تھی کہ) اللہ ایمان والوں کو پاک صاف کر دینا اور کافروں کو مٹا دینا چاہتا تھا\nکیا تم یہ سمجھ بیٹھے ہو کہ تم (سیدھے) جنت میں داخل ہو جائو گے، حالانکہ ابھی اللہ نے یہ تو دیکھا ہی نہیں کہ تم میں سے کون لوگ اس کی راہ میں جانیں لڑانے والے اور صبر کرنے والے ہیں\nتحقیق تم جنگ سے پہلے ہی (شہادت کی) موت کی خواہش کرتے تھے، چنانچہ پس اب تم نے اسے اپنی آنکھوں سے\nاپنے سامنے دیکھ لیا ہے"],[886,"§یومِ اُحد کے مصائب کی حکمت\nاللہ تعالیٰ اپنے ان مومن بندوں سے جو اُحد کے دن مصائب میں مبتلا ہوئے اور جن میں سے ستر (70)شہیدبھی ہو گئے تھے، مخاطب ہوتے ہوئے فرما رہا ہے :﴿قَدْ خَلَتْ مِنْ قَبْلِكُمْ سُنَنٌۙ﴾ ’’تم لوگوں سے پہلے بھی بہت سے واقعات گزر چکے ہیں۔ ‘‘یعنی سابقہ انبیائے کرام علیہم السلام کی اُمتوں کو بھی اس طرح کے واقعات کا سامنا کرنا پڑا تھا مگر انجام کار اللہ تعالیٰ نے انہیں فتح و نصرت سے سرفراز فرمایا اور تباہی و بربادی کافروں ہی کا مقدر ٹھہری تھی۔ اسی لیے فرمایا:﴿فَسِيْرُوْا فِي الْاَرْضِ فَانْظُرُوْا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِيْنَ۠۰۰۱۳۷﴾ ’’تو تم زمین میں پھر دیکھ لوکہ جھٹلانے والوں کا کیسا انجام ہوا؟‘‘\nپھر اللہ تعالیٰ نے فرمایا ہے : ﴿هٰذَا بَيَانٌ لِّلنَّاسِ﴾ ’’یہ (قرآن) لوگوں کے لیے بیان صریح ہے۔‘‘ اس میں تمام امور و معاملات کا نہایت صریح اور واضح بیان کیا ہے اور بتایا گیا ہے کہ سابقہ اُمتیں اپنے دشمنوں کے ساتھ کس طرح تھیں۔ ﴿وَهُدًى وَّمَوْعِظَةٌ لِّلْمُتَّقِيْنَ۠۰۰۱۳۸﴾ ’’اور اہل تقویٰ کے لیے ہدایت اور نصیحت ہے۔‘‘ یعنی قرآن میں تم سے پہلے لوگوں کی خبریں بھی ہیں، تمہارے دلوں کے لیے ہدایت کا سامان بھی اورمتقین کے لیے نصیحت بھی کہ یہ قرآن حرام کاموں اور گناہ کی باتوں سے منع کرتا ہے۔\nپھر اللہ تعالیٰ نے مومنوں کو تسلی دیتے ہوئے فرمایا:﴿وَلَا تَهِنُوْا﴾ ’’اور بے دل نہ ہونا۔‘‘ یعنی جو کچھ ہوا اس کے سبب کمزور نہ پڑنا﴿وَلَا تَحْزَنُوْا وَاَنْتُمُ الْاَعْلَوْنَ اِنْ كُنْتُمْ مُّؤْمِنِيْنَ۰۰۱۳۹﴾ ’’اور نہ کسی طرح کا غم کرنا اگر تم مومن (صادق) ہو تو تم ہی غالب رہو گے۔ ‘‘ یعنی مومنو! انجام کار تمہارا ہی اچھا ہوگا اور بالآخر فتح و نصرت سے تمہی سرفراز کیے جاؤ گے۔ ﴿اِنْ يَّمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ الْقَوْمَ قَرْحٌ مِّثْلُهٗؕ﴾ یعنی اگر تمہیں زخم آئے ہیں اور تم میںسےکئی لوگ شہید ہوئے ہیں تو اس سے تھوڑا ہی عرصہ پہلے تمہارے دشمن کو بھی اسی طرح زخم آئے تھے اور ان کے بہت سے آدمی بھی اسی طرح مارے گئے تھے۔ ﴿وَتِلْكَ الْاَيَّامُ نُدَاوِلُهَا بَيْنَ النَّاسِۚ﴾ ’’اور یہ دن ہیں کہ ہم ان کولوگوں میں بدلتے رہتے ہیں۔‘‘ یعنی ہم کبھی تمہارے دشمنوں کو بھی تم پر غالب کر دیتے ہیں کیونکہ اس میں ہماری طرف سے کوئی نہ کوئی حکمت و مصلحت ضرور ہوتی ہے جبکہ انجام کار فتح و نصرت مسلمانوں ہی کی ہے۔ اسی لیے اللہ تعالیٰ نے فرمایا:﴿وَلِيَعْلَمَ اللّٰهُ الَّذِيْنَ اٰمَنُوْا﴾ ’’اور تاکہ اللہ ایمان والوں کو ممتاز کر دے۔‘‘ ابن عباس رضی اللہ عنہما نے اس طرح کی آیات کی تفسیر میں فرمایا ہے : تاکہ ہم یہ دیکھ لیں کہ دشمن کے مقابلے میں صبر کون کرتاہے!\nارشاد باری تعالیٰ ہے :﴿وَيَتَّخِذَ مِنْكُمْ شُهَدَآءَؕ﴾ ’’اور تم میں سے شہداء بنائے۔‘‘ جو اس کے راستے میں جہاد کریں اور اس کی رضا میں اپنے آپ کو کھپا دیں۔﴿وَاللّٰهُ لَا يُحِبُّ الظّٰلِمِيْنَۙ۰۰۱۴۰ وَلِيُمَحِّصَ اللّٰهُ الَّذِيْنَ اٰمَنُوْا﴾ ’’اور اللہ بے انصافوں کو پسند نہیں کرتا۔ اور تاکہ اللہ ایمان والوں کو نکھار دے۔ ‘‘ او ریہ بھی مقصود تھا کہ اللہ ایمان والوں کو اگر ان کے گناہ ہوں تو ان کے گناہوں کو مٹا دے ورنہ انہیں پہنچنے والی تکلیفوں کے باعث ان کے درجات میں اضافہ فرما دے۔ ﴿وَيَمْحَقَ الْكٰفِرِيْنَ۰۰۱۴۱﴾ ’’اور کافروں کو نابود کر دے۔ ‘‘ کیونکہ جب وہ کامیاب ہوتے ہیں تو بغاوت اور سرکشی کی روش اختیار کرتے ہیں اور یہ ان کی تباہی و بربادی، ناکامی ونامرادی اور ہلاکت کا سبب بنتی ہے۔\nپھر اللہ تعالیٰ نے فرمایا ہے : ﴿اَمْ حَسِبْتُمْ اَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَعْلَمِ اللّٰهُ الَّذِيْنَ جٰهَدُوْا مِنْكُمْ وَيَعْلَمَ الصّٰبِرِيْنَ۰۰۱۴۲﴾ ’’کیا تم یہ سمجھتے ہو کہ (بلا آزمائش) تم بہشت (جنت) میں داخل ہوجاؤ گے، حالانکہ ابھی اللہ تعالیٰ نے تم میں سے جہاد کرنے والوں کو تو (اچھی) طرح معلوم کیا ہی نہیں؟ اور (یہ بھی مقصود ہے کہ) وہ ثابت قدم رہنے والوں کو معلوم کرے۔ ‘‘ یعنی کیا تم یہ سمجھتے ہو کہ قتال اور آلام و مصائب میں مبتلا ہوئے بغیر جنت میں داخل ہوجاؤ گے ؟ جیسا کہ اللہ تعالیٰ نے سورۂ بقرہ میں فرمایا ہے :﴿اَمْ حَسِبْتُمْ اَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَاْتِكُمْ مَّثَلُ الَّذِيْنَ خَلَوْا مِنْ قَبْلِكُمْؕ مَسَّتْهُمُ الْبَاْسَآءُ وَالضَّرَّآءُ وَزُلْزِلُوْا﴾ (البقرۃ:214) ’’کیا تم یہ خیال کرتے ہو کہ (یوں ہی) بہشت (جنت) میں داخل ہوجاؤ گے اور ابھی تم کو پہلے لوگوں کی سی (مشکلیں) تو پیش آئی ہی نہیں ؟ ان کو (بڑی بڑی) سختیاں اور تکلیفیں پہنچیں اور وہ (صعوبتوں میں) ہلا ڈالے گئے۔‘‘ اور فرمایا:﴿الٓمّٓۚ۰۰۱ اَحَسِبَ النَّاسُ اَنْ يُّتْرَكُوْۤا اَنْ يَّقُوْلُوْۤا اٰمَنَّا وَهُمْ لَا يُفْتَنُوْنَ۰۰۲﴾ (العنکبوت:1-2) ’’الٓمّٓ۔ کیا لوگ یہ خیال کیے ہوئے ہیں کہ (صرف) یہ کہنے سے کہ ہم ایمان لے آئے چھوڑ دیے جائیں گے اوران کی آزمائش نہیں کی جائے گی؟ ‘‘\nصحیح بخاری و مسلم میں حدیث ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «لَاتَمَنَّوْا لِقَائَ الْعَدُوِّ، وَسَلُوا اللهَ الْعَافِيَةَ، فَإِذَا لَقِيتُمُوهُمْ فَاصْبِرُوا، وَاعْلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ» ’’دشمن سے مڈبھیڑ کی تمنا نہ کرو اور اللہ تعالیٰ سے عافیت کی دعا مانگتے رہا کرو۔ہاں، البتہ جب دشمن سے مقابلہ ہو جائے تو پھر صبر کا مظاہرہ کرو اور خوب جان لو کہ جنت تلواروں کے سائے تلے ہے۔ ‘‘(صحیح البخاری : 3025، صحیح مسلم : 1742) اسی لیے اللہ تعالیٰ نے فرمایا ہے :﴿فَقَدْ رَاَيْتُمُوْهُ﴾ ’’سو تم نے اس کو (آنکھوں سے) دیکھ لیا۔‘‘ یعنی تلواروں کی چمک، نیزوں کی دمک، بھالوں کے ٹکرانے اورمردوں کے جنگ کے لیے صف آراء ہونے کے وقت تم نے موت کا مشاہدہ کر لیا۔ اہل منطق و بلاغت اس کو تخییل کا نام دیتے ہیں۔ اور وہ ایک غیر محسوس چیز کا ایسا مشاہدہ ہے جیسے کہ محسوس چیز کا ہو جیسا کہ بکری، بکرے کی دوستی اور بھیڑیے کی دشمنی کو محسوس کرتی ہے۔ (اسی طرح موت بھی غیر حسی چیز ہے جسے حسی کی جگہ پر لاکر کہا گیا کہ تم نے اس کا مشاہدہ کر لیا۔)"],[887,"§مختلف تہذیبوں اور قوموں کا عروج و زوال کیسے ہوتا ہے؟\nیعنی ایسے واقعات عام لوگوں کے لیے محض ایک تاریخی بیان کی حیثیت رکھتے ہیں۔ جن لوگوں کے دلوں میں اللہ کا ڈر نہیں ہوتا وہ یہی کہنے پر اکتفا کر لیتے ہیں کہ مختلف تہذیبیں بنتی اور مٹتی آئی ہیں۔ ایک یونانی تہذیب تھی، ایک رومی تہذیب تھی، ایک ہندی تہذیب تھی، ایک مصری تہذیب تھی، ایک بابلی تھی اور ہر تہذیب کی عمر طبعی تقریباً ایک ہزار سال ہوتی ہے۔ جب عمر پوری ہو جاتی ہےت و وہ تہذیب مٹ جاتی ہے تو اس کی جگہ کوئی نئی تہذیب لے لیتی ہے جس کا دنیا بھر میں بول بالا ہوجاتاہے۔ اس تاریخی بیان میں ایک بڑا مغالطہ یہ ہے کہ ہر تہذیب کی عمر ہزار سال یا تقریباً ہزار سال نہیں ہوتی۔ بلکہ اس سے بہت کم بھی ہو سکتی ہے اور اس سے بہت زیادہ بھی۔ پھر وہ یہ سوچنے کی زحمت گوارا ہی نہیں کرتے کہ یہ تہذیبیں بن کیسے جاتی ہیں اور بگڑتی کیونکر ہیں؟ قرآن نے اس سوال کا جواب یہ دیا ہے کہ کوئی قوم اس دنیا میں ایسی نہیں جہاں اللہ کا پیغمبر مبعوث نہ ہوا ہو۔(35:24) پھر جب تک کوئی قوم اپنے پیغمبر کی تعلیمات پر عمل پیرا رہتی ہے تو یہ اس کے عروج کا زمانہ ہوتا ہے اور جب یہی قوم عیش وعشرت اور فحاشی و بے حیائی اور معصیت کے کاموں میں مبتلا ہو جاتی ہے جس کا نام ان کی زبان میں تہذیب ہوتاہے تواس پر بتدریج زوال آنا شروع ہوجاتا ہے یا وہ گناہوں میں بہت زیادہ ڈوب جائے تو ناگہانی قسم کاعذاب انھیں تباہ برباد کر دیتاہے اور اللہ سے ڈرنے والے لوگ جب بھی کسی قوم کے عروج وزوال پر نظر ڈالتے ہیں تو اسی نظریہ کے مطابق ڈالتے ہیں اور ایسے واقعات سے عبرت بھی حاصل کرتے ہیں اور ہدایت بھی۔\nاس مقام پر یہ مضمون اس مناسبت سے آیا ہے کہ جو مشرکین مکہ اور یہود اور ان کے حلیف اور منافقین جو بھی اللہ کی آیات کو جھٹلا رہے ہیں اور مسلمانوں سے محاذآرائی کررکھی ہے ان سب کا یہی انجام ہونے والا ہے۔\nان ہدایات وارشادات کے بعد اب پھر غزوہ اُحد کا بیان ہو رہا ہے اور یہ آیت غالباً اس وقت نازل ہوئی جب غزوہ اُحد میں مسلمان ایک دفعہ شکست کھا کر مایوسی و بددلی کا شکار ہو رہے تھے۔ اگرچہ اس کاروئے سخن بظاہر مجاہدین اُحد کی طرف معلوم ہوتا ہے۔ تاہم اللہ تعالیٰ نے ہمیشہ کے لیے ایک کلیہ بیان فرما دیا کہ اگر تم فی الواقع مومن ہو اور سست اور غزوہ ہونے کے بجائے اللہ پر توکل اور صبر کرو گے تو اللہ تعالیٰ یقینا ً تمھیں غلبہ عطا فرمائے گا اور اگر تم مغلوب و مقہور ہو تو وہ وجوہ تلاش کرو جن کی وجہ سے یہ صورت حال پیدا ہوئی ہے۔\nجنگ بدر میں کافروں کو اس سے زیادہ صدمہ پہنچا تھا۔ اس وقت کافروں کے ستر سردار قتل ہوئے تو ستر گرفتار بھی ہوئے۔جب کہ غزوۂ اُحد میں ستر مسلمان شہید ہو گئے اور اللہ کے فضل و کرم سے مسلمانوں کا ایک آدمی بھی گرفتار نہ ہوا۔ کیونکہ بالآخر میدان مسلمانوں کے ہاتھ رہا اور قریش مکہ کو پسپا ہونا پڑا تھا۔"],[888,"§غزوۂ اُحد میں وقتی شکست کی حکمتیں\nاس آیت میں شکستہ دل مسلمانوں کو ڈھارس بندھائی جا رہی ہے۔پھر اس شکست کی بعض حکمتیں بیان کی گئی ہیں۔ ان میں سے ایک یہ ہے کہ خوشی اور غمی،فتح و شکست، کامرانی و ناکامی، خوشحالی وتنگدستی ایسی چیزیں ہیں جو لوگوں میں ہر کسی کو پیش آتی رہتی ہیں۔ اس لیے اگر مسلمانوں کو وقتی طور پر شکست ہو بھی گئی تو غمزدہ اور بد دل ہونے کی کوئی وجہ نہیں۔ انھیں کافروں کی طرف دیکھنا چاہیے جو میدان بدرمیں بری طرح مار کھانے کے باوجود پھر سے نئے عزم کے ساتھ باطل کی حمایت میں لڑنے آگئے ہیں۔ دوسری حکمت اس غذوہ میں یہ ہے کہ سچے مومنوں اور منافقوں میں امتیاز ہو جائے،جسے تم لوگ اپنی آنکھوں سے دیکھ لو۔ ﴿وَيَتَّخِذَ مِنْكُمْ شُهَدَآءَ﴾ کا دوسرا مطلب یہ بھی ہو سکتا ہے کہ تم میں سے کچھ لوگوں کو شہادت کا درجہ نصیب ہو۔\nتیسری حکمت یہ ہے کہ حقیقی مسلمان ممتاز ہو کر سب کے سامنے آجائیں اور کافر اس عارضی فتح سے دلیر ہو کر پھر سے مسلمانوں پر حملہ کرنے آجائیں تو ان کے ان کرتوتوں کا انھیں بدلہ مل سکے۔ چنانچہ بعد میں غزوۂ خندق میںکفار شکست کھا کر بھاگ کھڑے ہوئے۔ اس کے بعد ان میں یہ سکت ہی نہ رہی کہ جارحانہ طور پر مسلمانوں پر حملہ آور ہو سکیں۔"],[889,"§جہاد کے ذریعے امتحان\nیعنی جنت کے جن اعلیٰ درجات اور مقامات پر اللہ تعالیٰ تمھیں پہنچانا چاہتا ہے کیا تمھارا یہ خیال ہے کہ بس یوں ہی بیٹھے بیٹھے آرام سے وہاں جا پہنچو گے اور اللہ تمھارا امتحان لے کر یہ نہ دیکھے گا کہ جہاد میں حصہ لینے والے اور اس میں ثابت قدم رہنے والے کون کون ہیں۔ جنت کے بلند درجات پر تو وہی لوگ فائز ہوں گے جو اللہ کی راہ میں ہر طرح کی سختیاں جھیلنے اور قربانیاں پیش کرنے کے لیے تیار ہوں۔ یہاں بھی اللہ کے دیکھنے یا جاننے سے وہی مراد ہے جو سابقہ آیت میں مذکور ہوئی یعنی ﴿وَيَتَّخِذَ مِنْكُمْ شُهَدَآءَ﴾ کہ مسلمانوں کی پوری جماعت یہ صورت حال بچشم خود ملاحظہ کرے۔"],[890,"§خباب بن اَرت اور مشرکین مکہ کی سزائیں\nمکی دور میں مسلمانوں پر قریش مکہ کی طرف سے بے پناہ مظالم اور مصائب ڈھائے جا رہے تھے۔ سیدنا خباب رضی اللہ عنہ بن اَرت ان مصائب سے کچھ گھبرا سے گئے اور چاہا کہ جا کر رسول اللہ صلی اللہ علیہ وسلم سے دریافت فرمائیں کہ جس وقت کی آپ بشارت سناتے ہیں وہ کب آئے گا؟ چنانچہ وہ خودراوی ہیں کہ ”میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اس وقت آپ کعبہ کے سایہ میں ایک چادر پر تکیہ لگائے بیٹھے تھے۔ اس زمانہ میں ہم مشرک لوگوں سے سخت تکلیفیں اُٹھا رہے تھے۔ میں نے آپ صلی اللہ علیہ وسلم سے عرض کیا کہ آپ اللہ تعالیٰ سے ان مشرکوں کے لیے بددعا کیوں نہیں کرتے؟ یہ سنتے ہی آپ (تکیہ چھو ڑکر) سیدھے بیٹھ گئے اور آپ صلی اللہ علیہ وسلم کا چہرہ (غصے سے) سرخ ہو گیا اور فرمایا:”تم سے پہلے ایسے لوگ گزر چکے ہیں جن کے گوشت اور پٹھوں میں ہڈیوں تک لوہے کی کنگھیاں چلائی جاتی تھیں۔ مگر وہ اپنے سچے دین سے پھرتے نہیں تھے اور آرا ان کے سر کے درمیان رکھ کر چلا دیا جاتا اور ان کے دو ٹکڑے کر دیے جاتے مگر وہ سچے دین سے نہیں پھرتے تھے اور اللہ ایک دن اس کام کو ضرور پورا کرے گا۔“ (بخاری، باب بنیان الکعبۃ، باب مالقی النبی و اصحابہ من المشرکین بمکۃ)اور ایک روایت میں یہ الفاظ بھی ہیں۔ ”مگر تم لوگ تو جلدی مچاتے ہو۔“\nگویا رسول اللہ صلی اللہ علیہ وسلم نے بھی سیدنا خباب بن اَرت کو صبر و استقلال اور ثابت قدمی کا وہی سبق سکھایا جو اس آیت میں مسلمانوں کو سکھایا جا رہا ہے۔"],[891,"§موت اور دشمن سے مڈبھیڑ کی آرزو نہ کرو\nاس آیت میں غزوۂ اُحد کا ایک دوسرا منظر پیش کیا گیا ہے۔ جبکہ مسلمان ابتداء ً شکست سے دو چار ہوئے تھے جو صحابہ رضی اللہ عنہم غزوہ بدر میں شرکت سے محروم رہ گئے تھے وہ شہدائے بدر کے فضائل سن سن کر تمنا کیا کرتے تھے کہ اگر پھر اللہ نے ایسا موقع فراہم کیا تو ہم اللہ کی راہ میں جان دے کر شہادت کے مراتب حاصل کریں گے۔ مشورہ کے وقت ایسے ہی صحابہ نے زور دیا تھا کہ جنگ مدینہ سے باہر کھلے میدان میں لڑنا چاہیے، لیکن جب شکست ہوئی تو ایسے صحابہ میں سے بھی کچھ لوگ بھاگ نکلے۔ اس آیت میں انھی لوگوں سے خطاب ہے کہ جو چیز تم چاہتے تھے وہی تمھیں پیش آئی ہے۔ اب پیچھے ہٹنے کا کیا مطلب ہے؟ اسی سلسلہ میں ایک حدیث ہے کہ آپ نے فرما یا دشمن سے مڈبھیڑ کی تمنا مت کرو۔ اور جب ایسا موقع آجائے تو پھر ثابت قدمی دکھاؤ۔ (بخاری، کتاب التمنی، باب کراہیۃ تمنی لقائ العدو نیز کتاب الجہاد، باب لا تمنوا لقائ العدو)\nیعنی بغیر قتال و شدائد کی آزمائش کے تم جنت میں چلے جاؤ گے ؟ نہیں بلکہ جنت ان لوگوں کو ملے گی جو آزمائش میں پورے اُتریں گے۔ جیسے دوسرے مقام پر فرمایا:﴿اَمْ حَسِبْتُمْ اَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَاْتِكُمْ مَّثَلُ الَّذِيْنَ خَلَوْا مِنْ قَبْلِكُمْؕ مَسَّتْهُمُ الْبَاْسَآءُ وَالضَّرَّآءُ وَزُلْزِلُوْا﴾ (البقرۃ:214) ’’کیا تم نے گمان کیا کہ تم جنت میں چلے جاؤ گے اور ابھی تم پر وہ حالت نہیں آئی جو تم سے پہلے لوگوں پرآئی تھی، انہیں تنگ دستی اور تکلیفیں پہنچیں اور وہ خوب ہلائے گئے۔‘‘ مزید فرمایا : ﴿اَحَسِبَ النَّاسُ اَنْ يُّتْرَكُوْۤا اَنْ يَّقُوْلُوْۤا اٰمَنَّا وَهُمْ لَا يُفْتَنُوْنَ۰۰۲﴾ (العنکبوت:2) ’’کیا لوگ گمان کرتے ہیں کہ انہیں صرف یہ کہنے پر چھوڑ دیا جائے گا ہم ایمان لائے اور ان کی آزمائش نہ ہو گی؟‘‘"],[892,"§بلاغت\nهَذَا بَيَانٌ یہاں لفظ هَذَ اکا (مشار الیہ) تاریخ کا وہ ہمہ گیر اُصول ہے جو تمام قوموں کے عروج وزوال کا باعث رہا ہے کہ فتح و کامرانی انہی قوموں کا مقدر ہے جو ایمان باللہ اور عمل صالح کی راہ پر گامزن رہے ہوں اور جنہوں نے اللہ تعالیٰ کی اطاعت سے منہ موڑا اور نیکیوں کو چھوڑا، انہیں ہلاکت و بربادی کے عذاب سے بہر حال دو چار ہونا ہے جیسا کہ فرمایا: ﴿فَانْظُرُوْا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِيْنَ۠۰۰۱۳۷﴾ (آل عمران :137) ’’اور دیکھو کہ جھٹلانے والوں کا کیا انجام ہواہے۔‘‘\nبیان سے مراد اس جگہ اس ہمہ گیر اور اٹل اصول کی وضاحت اور تبیین ہے جو تاریخ کے تمام ادوار میں بقا و فنا کا ضامن وکفیل رہا ہے یعنی قوموں کی بقاوار تقاء اخلاقی خوبیوں کی رہین منت ہے۔ (لسان القرآن،ص : 249)\nوضاحت :…غزوۂ اُحد میں مسلمانوں کو شکست کا سامنا کرنا پڑا ایک سبب ان کا صبر نہ کرنا تھا غنیمت کے حصول کے لیے اپنی ذمہ داری کو چھوڑ کر بھاگ کھڑے ہوئے حالانکہ ڈسپلن (نظم و ضبط) کا تقاضا تھا کہ وہ قیادت کی اطاعت سے سر موانحراف نہ کرتے۔ چنانچہ اللہ پاک ایمان والوں کومطلع فرما رہے ہیں کہ اللہ تعالیٰ کا قانون جو اس کی تمام مخلوقات پر حاوی ہے تم سے پہلے کچھ اُمتیں گزری ہیں تو اللہ تعالیٰ کی زمین کی سیاحت کرو تمہیں ان لوگوں کا انجام واضح طور پر نظر آئے گا جنہوں نے اللہ تعالیٰ کے قانون کو پامال کیا۔ جیسا کہ نوح علیہ السلام کی قوم، عاد، ثمود وغیرہ قومیں گزری ہیں اللہ تعالیٰ نے ان کی جانب پیغمبروں علیہم السلام کو مبعوث فرمایا لیکن انہوں نے پیغمبروں علیہم السلام کی تعلیم کو تسلیم نہ کیا تو اللہ تعالیٰ نے اپنے اٹل قانون کے مطابق تکذیب کرنے والوں کو تباہ و برباد کر دیا لیکن ایماند اروں کو عذاب سے محفوظ رکھا اگرچہ انہیں ان کی قوم سے تکالیف پہنچیں۔ اب اللہ تعالیٰ کا قانون حسب سابق جاری ہے تو اے ایمان والو ! اللہ تعالیٰ تمہیں دشمنوں کے ظلم و ستم سے تحفظ عطا کرے گا (اور تمہارے دشمنوں کو جنہوں نے اللہ تعالیٰ کے قانون کی مخالفت کی) تباہ و برباد کردے گا اگرتمہیں اس بارے میں شک ہے تو روئے زمین کی سیاحت کرو اور ان قوموں کے کھنڈرات کا جائزہ لو جنہیں اس لیے صفحہ ہستی سے مٹا دیا گیا کہ انہوں نے اللہ تعالیٰ کے احکام کی مخالفت کی حقیقت یہ ہے کہ ان آیات میں لوگوں کو ایک واضح موقف پر کھڑا کر دیا گیا ہے جس سے حق و باطل میں امتیاز و اقع ہوجائے گا بلکہ ایسا روشنی کا مینار ہے جس کے ذریعہ جنت کا حصول آسان ہو جائے گا۔ بنیادی شرط اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت ہے۔\n﴿وَلَا تَهِنُوْا وَلَا تَحْزَنُوْا﴾ ان جملوں میں اللہ تعالیٰ ایمان داروں کو غزوۂ اُحد میں شکست ہونے کے سبب تسلی دلا ر ہے ہیں ان سے مخاطب ہو کر فرما رہے ہیں کہ تم میں ضعف و اضمحلال کا کچھ اثر نہیں ہونا چاہیے تم نے جہاد کو چھوڑنا نہیں ہے اگر غزوۂ اُحد میں تمہاری فوج کے کچھ نوجوان شہید ہوگئے ہیں تو تم نے اس غم کے سبب جہاد سے کنارہ کش نہیں ہونا ہے۔ یقیناً تمہیں تمہارے دشمنوں پر غلبہ حاصل ہوگا زمانہ ماضی میں بھی تمہیں غلبہ حاصل ہوا اور مستقبل میں بھی تمہیں غلبہ حاصل ہوگا لیکن شرط یہ ہے کہ تمہارا ایمان مستحکم ہو اور تم تقویٰ کی دولت سے مالامال ہو تمہیں یقین کرنا چاہیے کہ اگر تمہارے لشکر کے کچھ لوگ زخمی ہوئے اور جانبر نہیں ہو سکے ہیں۔ جب کہ بعض جانبر ہو گئے ہیں تو اس سے تم میں کمزوری رونما نہ ہو اور تم سے خود کو جہاد کی عظمت سے الگ نہیں کرنا ہے کیا یہ حقیقت نہیں کہ جنگ بدر میں تمہارے دشمن کے کچھ رفقاء زخمی ہوئے اور کچھ موت کے حوالہ ہوئے جب کہ لڑائی کی مثال ڈول جیسی ہے کبھی تم کامیاب کبھی تمہارا دشمن کامیاب یہ اللہ تعالیٰ کا قانون ہے جسے قانون فطرت کہاجاسکتا ہے۔ چنانچہ ﴿تِلْكَ الْاَيَّامُ نُدَاوِلُهَا﴾ کامفہوم بھی یہی ہے۔ بعد ازاں اس کا سبب بیان کیا کہ اللہ پاک نے اس المناک حادثہ کے سبب ایمان والوں کے ایمان کا جائزہ لینا تھا اور انہیں شہادت سے ہمکنار کرنا تھا جب کہ منافقین راستہ میں ہی اپنے سردار عبداللہ بن ابی رئیس المنافقین کی قیادت میں واپس چلے گئے لیکن پختہ مسلمان میدان جنگ میں بہادری کے ساتھ لڑتے رہے ان میں کچھ شہادت کے منصب جلیلہ سے ہمکنار ہوئے ان کی تعداد ستر (70) تھی ان میں چار (4) افراد مہاجرین سے تھے ان کے لیڈر حمزہ بن عبدالمطلب رضی اللہ عنہ تھے جو سید الشہداء کے لقب سے ملقب ہوئے۔ ان کے علاوہ سبھی انصار سے تھے۔\n﴿وَلِيُمَحِّصَ اللّٰهُ الَّذِيْنَ اٰمَنُوْا﴾ اللہ پاک نے جنگ اُحد میں ایمان والوں کو شکست سے اس لیے دو چار کیا تاکہ انہیں ان کے گناہوں سے پاکیزہ کیا جائے کہ وہ مکمل طور پر صاف ہو جائیں۔ مزید برآں شکست کے سبب مستقبل میں آپ کی اطاعت سے کبھی دست کش نہ ہوں گے بلکہ ان کے مسلسل اور پے درپے حملوں سے جزیرۃ العرب سے کفر کا نام و نشان مٹ گیا۔(ایسر التفاسیر : 319/1)"],[893,"§علامہ مراغی رحمہ اللہ کا تبصرہ\nعلامہ مراغی بیان کرتے ہیں غزوۂ اُحد میں شکست کے نتیجہ میں پختہ قسم کے ایمان داروں کا منافقین سے امتیاز ہو گیا اور جن ایمان داروں میں کچھ کمزوری تھی اس کے سبب ان کی کمزوری جاتی رہی سبھی مسلمان سونے کی خالص ڈلی بن گئے جو ہر قسم کے میل کچیل سے صاف ہوتی ہے۔ اکثر و بیشتر بار انسان پر اس کا ذاتی معاملہ بھی کبھی مشتبہ دکھائی دیتاہے۔ بار بار تجربات کے بعد اصل حقیقت اُبھر کر سامنے آتی ہے بلکہ امتحانات اور مصائب کی بھٹی میں سے گزرنے کے بعد آلائشیں کافور ہوتی ہیں جیسا کہ سونے کی ڈلی کو کٹھالی میں گرم کرنے سے کھوٹ کو اصل سے دور کیاجاتا ہے۔ کیا یہ حقیقت نہیں کہ ایک شخص کا جب اپنے دین کے بارے میں اعتقاد ہو کہ اس کا دین سچا ہے تو حالات کے ساز گار ہونے کے دور میں وہ آسانی کے ساتھ جانی، مالی قربانی دینے کے لیے تیار ہوجاتا ہے تاکہ دین اسلام کا جھنڈا بلند ہو جب کہ اس کی مخالفت کرنے والوں کے مکر و فریب کی چالیں کامیابی سے ہمکنار نہیں ہوتیں۔ غور فرمائیں جن صحابہ کرام رضی اللہ عنہم نے جنگ اُحد کے موقع پر رسول اکرم صلی اللہ علیہ وسلم کے حکم کی مخالفت کی اور غنیمت لوٹنے کے لالچ میں اپنی ذمہ داری کو خیر باد کہا اور وہ لوگ جو شکست خوردگی کے عالم میں میدان اُحد سے بھاگ گئے اللہ پاک نے انہیں کس طرح وہ بلند مقام عطا کیا جب کہ شکستگی کے عالم میں انہوں نے فیصلہ کیا کہ مسلمان لہو و لعب کے لیے پیدا نہیں کیا گیا ہے سستی، کاہلی اس کے نزدیک بھی نہ آئے بلکہ کسی کو سہارا نہ سمجھاجائے۔ خرق عادت کے طور پر کامیابی کا حصول اور سیادت کے منصب کا بھی وہ استحقاق نہیں رکھتا بلکہ اس کو سمجھنا چاہیے کہ اس کی ذمہ داری صرف یہ ہے کہ وہ نہایت محنت اور مشقت کے ساتھ اپنی ذمہ داری سے عہدہ برآہونے میں مسلسل وپیہم رواں دواں رہے بلکہ ذمہ داری کی ادائیگی میںجانی، مالی قربانی سے دریغ نہ کرے۔\nچنانچہ غزوۂ اُحد میں جو صحابہ کرام رضی اللہ عنہم سخت آزمائش میں ثابت قدم رہے انہوں نے اس کے بعد وقوع پذیر ہونے والی جنگوں میں جو کردار ادا کیا وہ تاریخ کے صفحات میں ان کی عظمت کو ہمیشہ اُجاگر کرتا رہے گا۔ چنانچہ غزوۂ حمراء الاسد میں نبی صلی اللہ علیہ وسلم نے حکم دیا کہ مشرکین کے تعاقب میں صرف وہ لوگ قدم زن ہوں جو غزوۂ اُحد میں شریک تھے اس کے نتیجہ میں شریک بہادروں نے رسول اکرم صلی اللہ علیہ وسلم کے فرمان کے مطابق دل و جان کے ساتھ عزم صادق کا ثبوت پیش کرتے ہوئے مردانگی کے وہ جوہر دکھلائے جو تاریخ کے صفحات پر ہمیشہ مرتسم رہیں گے۔ حالانکہ وہ شکست خوردگی اور زخموں کے سبب کمزور تھے۔\n(المراغی : 82/2)\n﴿وَمَا مُحَمَّدٌ اِلَّا رَسُوْلٌۚ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُؕ اَفَاۡىِٕنْ مَّاتَ اَوْ قُتِلَ انْقَلَبْتُمْ عَلٰۤى اَعْقَابِكُمْؕ وَمَنْ يَّنْقَلِبْ عَلٰى عَقِبَيْهِ فَلَنْ يَّضُرَّ اللّٰهَ شَيْـًٔاؕ وَسَيَجْزِي اللّٰهُ الشّٰكِرِيْنَ۰۰۱۴۴ وَمَا كَانَ لِنَفْسٍ اَنْ تَمُوْتَ اِلَّا بِاِذْنِ اللّٰهِ كِتٰبًا مُّؤَجَّلًاؕ وَمَنْ يُّرِدْ ثَوَابَ الدُّنْيَا نُؤْتِهٖ مِنْهَاۚ وَمَنْ يُّرِدْ ثَوَابَ الْاٰخِرَةِ نُؤْتِهٖ مِنْهَاؕ وَسَنَجْزِي الشّٰكِرِيْنَ۰۰۱۴۵ وَكَاَيِّنْ مِّنْ نَّبِيٍّ قٰتَلَۙ مَعَهٗ رِبِّيُّوْنَ كَثِيْرٌۚ فَمَا وَهَنُوْا لِمَاۤ اَصَابَهُمْ فِيْ سَبِيْلِ اللّٰهِ وَمَا ضَعُفُوْا وَمَا اسْتَكَانُوْاؕ وَاللّٰهُ يُحِبُّ الصّٰبِرِيْنَ۰۰۱۴۶ وَمَا كَانَ قَوْلَهُمْ اِلَّاۤ اَنْ قَالُوْا رَبَّنَا اغْفِرْ لَنَا ذُنُوْبَنَا وَاِسْرَافَنَا فِيْۤ اَمْرِنَا وَثَبِّتْ اَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكٰفِرِيْنَ۰۰۱۴۷ فَاٰتٰىهُمُ اللّٰهُ ثَوَابَ الدُّنْيَا وَحُسْنَ ثَوَابِ الْاٰخِرَةِؕ وَاللّٰهُ يُحِبُّ الْمُحْسِنِيْنَࣖ۰۰۱۴۸﴾\nاور محمد صلی اللہ علیہ وسلم ایک رسول ہی تو ہیں۔ ان سے پہلے بہت سے رسول گزر چکے ہیں۔ اگر ان کا انتقال ہو جائے یا یہ شہید ہو جائیں تو کیا تم اسلام سے اپنی ایڑیوں کے بل پھر جائو گے؟ اور جو کوئی اپنی ایڑیوں کے بل پھر جائے تو وہ اللہ کا کچھ بھی بگاڑ نہ سکے گا۔ اور اللہ شکر ادا کرنے والوں کو اچھی جزا دے گا\nاور کوئی جاندار اللہ کے حکم کے بغیر مر نہیں سکتا، اس نے موت کا وقت لکھا ہوا ہے اور جو کوئی دنیا کا بدلہ چاہتا ہو تو ہم اسے دنیا ہی میں کچھ دے دیتے ہیں اور جو کوئی آخرت کا بدلہ چاہتا ہو تو ہم اسے اس میں سے کچھ دے دیتے ہیں اور ہم شکر ادا کرنے والوں کو اچھی جزا دیں گے\nاور کتنے ہی نبی گزرے جن کے ساتھ مل کر بہت سے اللہ والوں نے جہاد کیا، انہیں اللہ کی راہ میں جو تکلیفیں پہنچیں انہوں نے ہمت نہ ہاری اور نہ کمزوری دکھائی اور نہ وہ (کافروں سے) دبے، اور اللہ صبر کرنے والوں کو پسند کرتا ہے\nاور ان کا کہنا یہی تھا کہ اے ہمارے رب! ہمارے گناہ بخش دے اور ہمارے کاموں میں ہم سے جو زیادتیاں ہوئیں وہ معاف کر دے۔ اور ہمیں ثابت قدم رکھ اور کافر قوم کے مقابلے میں ہماری مدد فرما\nچنانچہ اللہ نے انہیں دنیا میں ثواب دیا اور آخرت میں بہت اچھا ثواب دیا۔ اور اللہ نیکو کاروں کو پسند کرتا ہے"],[894,"§غزوۂ اُحد میں رسول اللہ صلی اللہ علیہ وسلم کی شہادت کی افواہ\nجب اُحد کے دن کچھ مسلمان شکست کھا گئے اور کچھ شہیدہو گئے تو شیطان نے یہ اعلان کر دیا کہ محمد صلی اللہ علیہ وسلم شہید ہو گئے ہیں۔ ابن قمیئہ مشرکوں کے پاس آکر کہنے لگا : میں نے محمد صلی اللہ علیہ وسلم کو شہید کیا ہے تو بہت سے لوگوں کے دلوں میں یہ بات اُترگئی۔ اور انہیں یقین ہو گیا کہ واقعی رسول اللہ صلی اللہ علیہ وسلم شہید ہو گئے ہیں۔ اور انہوں نے خیال کیا کہ ایسا کچھ بعید بھی نہیں کیونکہ اللہ تعالیٰ نے بیان فرمایا ہے کہ بہت سے انبیائے کرام علیہم السلام کو شہیدکر دیا گیاتھا۔ اس افواہ کی وجہ سے مسلمانوں میں بہت کمزوری و بزدلی اور جنگ سے دوں ہمتی پیدا ہو گئی تو اسی سلسلے میں اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم پر یہ آیت کریمہ نازل فرمائی : ﴿وَمَا مُحَمَّدٌ اِلَّا رَسُوْلٌۚ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُؕ﴾ ’’اور محمد صلی اللہ علیہ وسلم تو صرف (اللہ کے) پیغمبر صلی اللہ علیہ وسلم ہیں۔ ان سے پہلے بھی بہت سے پیغمبر علیہم السلام ہو گزرے ہیں۔ ‘‘ یعنی نبو ت و رسالت اور جواز شہادت میں وہ آپ کے لیے اسوہ ہیں۔\nابن ابو نَجِيح نے اپنے باپ سے روایت کیا ہے کہ ایک مہاجر کا ایک انصاری کے پاس سے گزر ہوا جبکہ وہ خاک و خون میں تڑپ رہا تھا تو اس نے کہا: اے فلاں! کیا تجھے یہ معلوم ہے کہ حضرت محمد صلی اللہ علیہ وسلم تو شہید ہو گئے ہیں، اس حالت میں بھی انصاری نے یہ سن کر کہا کہ اگر حضرت محمد صلی اللہ علیہ وسلم جامِ شہادت نوش فرما گئے ہیں تو آپ صلی اللہ علیہ وسلم نے اللہ تعالیٰ کے دین کو پہنچا دیا ہے، لہٰذاجاؤ اور اپنے دین کو بچانے کے لیے جہاد کرو تو اس موقع پر یہ آیت کریمہ نازل ہوئی تھی :﴿وَمَا مُحَمَّدٌ اِلَّا رَسُوْلٌۚ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُؕ﴾ اسے حافظ ابو بکر بیہقی رحمہ اللہ نے ’’دلائل النبوۃ‘‘ میں روایت کیا ہے۔\n(دلائل النبوۃ : 248/3)\nجو لوگ اس سلسلے میں کمزوری میں مبتلا ہوئے،ان کی تردید کرتے ہوئے اللہ تعالیٰ نے فرمایا ہے :﴿اَفَاۡىِٕنْ مَّاتَ اَوْ قُتِلَ انْقَلَبْتُمْ عَلٰۤى اَعْقَابِكُمْؕ﴾ ’’بھلا اگر انہیں موت آجائے یا قتل کر دیا جائے تو تم اُلٹے پاؤں پھر جاؤ (مرتد ہوجاؤ) گے؟‘‘ ﴿وَمَنْ يَّنْقَلِبْ عَلٰى عَقِبَيْهِ فَلَنْ يَّضُرَّ اللّٰهَ شَيْـًٔاؕ وَسَيَجْزِي اللّٰهُ الشّٰكِرِيْنَ۰۰۱۴۴﴾ ’’اور جو اُلٹے پاؤں پھر جائے گا تو اللہ تعالیٰ کا کچھ نقصان نہیں کر سکے گا اور اللہ تعالیٰ شکر گزاروں کو عنقریب (بڑا) ثواب دے گا۔‘‘ یعنی ان کو جو اس کی اطاعت بجالائیں گے، اس کے دین کی خاطر جہاد کریں گے اور اس کے رسو ل علیہ السلام کی اتباع کریں گے، خواہ آپ صلی اللہ علیہ وسلم حیات ہوں یا وفات پا جائیں۔\nصحاح، مسانید، سنن اور دیگر کتب اسلام سے متعدد سندوں سے، جو کہ تواتر کی حد تک پہنچ کر قطعیت اور علم یقینی کا فائدہ دیتی ہیں، ثابت ہے اور میں نے شیخین حضرت ابو بکر و عمر رضی اللہ عنہما کی مسندوں میں بھی اسے ذکر کیا ہے کہ سیدنا ابو بکر صدیق رضی اللہ عنہ نے اس آیت کریمہ کی اس وقت تلاوت کی تھی جب رسول اللہ صلی اللہ علیہ وسلم نے انتقال فرمایا تھا۔(صحیح البخاری : 1241-1242، سنن النسائی : 1841) امام بخاری رحمہ اللہ نے سیدہ عائشہ رضی اللہ عنہا کی روایت کو بیان کیا ہے کہ سیدنا ابو بکر رضی اللہ عنہ مقام سنح میں اپنی رہائش سے گھوڑے پر تشریف لائے اور گھوڑے سے اُتر کر مسجد میں آگئے، لوگوں سے کوئی بات نہ کی اور سیدہ عائشہ رضی اللہ عنہا کے پاس چلے گئے اور رسول اللہ صلی اللہ علیہ وسلم کا قصد کیا، اس وقت آپ کو دھاری دار حِبَري کپڑے سے ڈھانپا ہوا تھا، سیدنا صدیق اکبر رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کے چہرۂ اقدس سے کپڑے کو ہٹایا، آپ صلی اللہ علیہ وسلم پر جھک گئے، بوسہ دیا اور رونے لگ گئے اور کہا:میرے ماں باپ آپ صلی اللہ علیہ وسلم پر قربان ! اللہ کی قسم ! اللہ آپ صلی اللہ علیہ وسلم پر دو موتوں کو جمع نہیں فرمائے گا جو موت آپ صلی اللہ علیہ وسلم کے لیے لکھ دی گئی تھی وہ آپ صلی اللہ علیہ وسلم پر وارد ہو چکی ہے۔ (صحیح البخاری : 1241-1242)\nامام زہری رحمہ اللہ نے بطریق ابو سلمہ حضرت ابن عباس رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ سیدنا ابو بکر رضی اللہ عنہ جب آئے تو سیدنا عمر رضی اللہ عنہ لوگوں سے گفتگو کر رہے تھے تو آپ رضی اللہ عنہ نے فرمایا: عمر بیٹھ جاؤ، سیدنا عمر رضی اللہ عنہ نے بیٹھنے سے انکار کیا تو لوگ سیدنا عمر رضی اللہ عنہ کو چھوڑ کرآپ رضی اللہ عنہ کی طرف متوجہ ہوگئے تو آپ رضی اللہ عنہ نے فرمایا: امابعد! جو حضرت محمد صلی اللہ علیہ وسلم کی عبادت کرتا تھا تو حضرت محمد صلی اللہ علیہ وسلم وفات پاگئے ہیں اورجو اللہ تعالیٰ کی عبادت کرتا تھا تو اللہ تعالیٰ کی ذات گرامی تو زندہ ہے جس کو فنا نہیں۔ اللہ تعالیٰ نے فرمایا ہے :﴿وَمَا مُحَمَّدٌ اِلَّا رَسُوْلٌۚ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُؕ﴾ تا﴿وَسَيَجْزِي اللّٰهُ الشّٰكِرِيْنَ۰۰۱۴۴﴾\nحضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ اللہ کی قسم ! یوں معلوم ہوتا ہے کہ لوگوں کو یہ معلوم ہی نہ تھا کہ یہ آیت نازل ہوئی ہے حتی کہ سیدنا ابو بکر رضی اللہ عنہ نے اس کی تلاوت فرمائی، لوگوں نے سیدنا ابو بکر رضی اللہ عنہ سے اس آیت کو حاصل کیا اور جس جس نے بھی اس آیت کو سنا تو بے ساختہ اس کی تلاوت شروع کر دی۔ حضرت سعید بن مسیب رحمہ اللہ سے روایت ہے کہ سیدنا عمر رضی اللہ عنہ نے فرمایا: کہ اللہ کی قسم ! میں نے جب سیدنا ابو بکر صدیق رضی اللہ عنہ سے اس آیت کی تلاوت سنی تو میں کھڑے کا کھڑا رہ گیا، میرے پاؤں مجھے اُٹھانہیں رہے تھے حتی کہ میں گر گیا۔ (صحیح البخاری : 4454)\nفرمان الٰہی : ﴿وَمَا كَانَ لِنَفْسٍ اَنْ تَمُوْتَ اِلَّا بِاِذْنِ اللّٰهِ كِتٰبًا مُّؤَجَّلًاؕ﴾ یعنی کوئی شخص اللہ تعالیٰ کے حکم کے بغیر مر نہیں سکتا حتی کہ اپنی اس مدت کو پورا کرلے جسے اللہ تعالیٰ نے اس کے لیے مقرر فرما رکھا ہے۔ اسی لیے فرمایا: ﴿كِتٰبًا مُّؤَجَّلًاؕ﴾ ’’(اس نے موت کا) وقت مقرر کر کے لکھ رکھا ہے۔‘‘ جیساکہ فرمایا:﴿وَمَا يُعَمَّرُ مِنْ مُّعَمَّرٍ وَّلَا يُنْقَصُ مِنْ عُمُرِهٖۤ اِلَّا فِيْ كِتٰبٍؕ﴾ (فاطر:11) ’’اور نہ کسی بڑی عمر والے کو عمر زیادہ دی جاتی ہے اور نہ اس کی عمر کم کی جاتی ہے مگر (سب کچھ) کتاب میں (لکھا ہوا) ہے۔‘‘ اور فرمایا:﴿هُوَ الَّذِيْ خَلَقَكُمْ مِّنْ طِيْنٍ ثُمَّ قَضٰۤى اَجَلًاؕ وَاَجَلٌ مُّسَمًّى عِنْدَهٗ﴾ (الأنعام: 2) ’’وہی تو ہے جس نے تم کو مٹی سے پیدا کیا، پھر (مرنے کا) ایک وقت مقرر کر دیا اور ایک مدت اس کے ہاں اور مقرر ہے۔‘‘\nاور فرمایا:﴿وَمَنْ يُّرِدْ ثَوَابَ الدُّنْيَا نُؤْتِهٖ مِنْهَاۚ وَمَنْ يُّرِدْ ثَوَابَ الْاٰخِرَةِ نُؤْتِهٖ مِنْهَاؕ﴾ ’’اور جو شخص دنیا میں (اعمال کا)بدلہ چاہے اس کو ہم یہیں بدلہ دے دیں گے اور جو آخرت میں طالب ِ ثواب ہو اس کو وہاں اجر عطا کریں گے۔‘‘ یعنی جس کا عمل صرف دنیا کے لیے ہوگا تو وہ اس قدر دنیا حاصل کرے گا جو اللہ تعالیٰ نے اس کے مقدر میں لکھ رکھی ہوگی۔ اور آخرت میں اس کا کوئی حصہ نہ ہوگا اورجو اپنے عمل سے آخرت کا طلب گار ہوگا تو اللہ تعالیٰ اسے آخرت کا اجر و ثواب عطا فرمائے گا۔ اور ساتھ ہی دنیا میں اس کے لیے جو لکھا ہوگا، وہ بھی اسے ضرور ملے گا جیسا کہ اللہ تعالیٰ نے فرمایاہے: ﴿مَنْ كَانَ يُرِيْدُ حَرْثَ الْاٰخِرَةِ نَزِدْ لَهٗ فِيْ حَرْثِهٖۚ وَمَنْ كَانَ يُرِيْدُ حَرْثَ الدُّنْيَا نُؤْتِهٖ مِنْهَاۙ وَمَا لَهٗ فِي الْاٰخِرَةِ مِنْ نَّصِيْبٍ۰۰۲۰﴾ (الشوری:20) ’’جو شخص آخرت کی کھیتی کا طالب ہو اس کے لیے ہم اس کی کھیتی میں افزائش کریں گے اور جو دنیا کی کھیتی کا خواستگار ہو، اس کو ہم اس میں سے دیں گے اور اس کا آخرت میںحصہ نہ ہوگا۔‘‘ اور فرمایا:﴿مَنْ كَانَ يُرِيْدُ الْعَاجِلَةَ عَجَّلْنَا لَهٗ فِيْهَا مَا نَشَآءُ لِمَنْ نُّرِيْدُ ثُمَّ جَعَلْنَا لَهٗ جَهَنَّمَۚ يَصْلٰىهَا مَذْمُوْمًا مَّدْحُوْرًا۰۰۱۸ وَمَنْ اَرَادَ الْاٰخِرَةَ وَسَعٰى لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَاُولٰٓىِٕكَ كَانَ سَعْيُهُمْ مَّشْكُوْرًا۰۰۱۹﴾ (بنی إسرائیل:18-19) ’’جو شخص دنیا (کی آسودگی) کا خواہش مند ہو تو ہم اس میں سے جسے چاہتے ہیں اور جتنا چاہتے ہیں جلد دے دیتے ہیں، پھر اس کے لیے جہنم کو (ٹھکانا) مقرر کر رکھا ہے جس میں وہ ملعون ہو کر اور (اللہ کی درگاہ سے) راندہ ہو کر داخل ہوگا۔ اور جوشخص آخرت کا خواستگار ہو اور اس میں اتنی کوشش کرے جتنی اسے لائق ہے اور وہ مومن بھی ہو تو ایسے ہی لوگوں کی کوشش ٹھکانے لگتی ہے۔‘‘ اسی طرح یہاں فرمایا: ﴿وَسَنَجْزِي الشّٰكِرِيْنَ۰۰۱۴۵﴾ ’’اور ہم شکر گزاروں کو عنقریب (بہت اچھا) صلہ دیں گے۔‘‘ یعنی ان کے شکر اور عمل کے مطابق ہم انہیں اپنے فضل و رحمت سے دنیا و آخرت میں اچھا بدلہ عطا کریں گے۔\nاُحد کے دن مسلمانوں کا جو جانی نقصان ہوا تھا، اس کی وجہ سے تسلی دیتے ہوئے اللہ تعالیٰ فرما رہا ہے : ﴿وَكَاَيِّنْ مِّنْ نَّبِيٍّ قٰتَلَۙ مَعَهٗ رِبِّيُّوْنَ كَثِيْرٌۚ﴾ ’’اور بہت سے نبی ہو گزرے ہیں جن کے ساتھ مل کر اکثر اہل اللہ (اللہ کے دشمنوں سے) لڑے ہیں۔‘‘ (یہ معنی موجودہ قراء ت کی رُو سے ہیں) یعنی قتال و جہاد میں ان کو جو مصیبتیں اور آزمائشیں پہنچیں وہ ان کی وجہ سے ضعف و استکانت کا شکار نہیں ہوئے۔ اور ایک روایت میں﴿ قٰتَلَ١ۙ﴾ کو [قُتِل]پڑھا گیا ہے۔ اس صورت میں معنی ہوںگے: ’’کتنے ہی نبی شہید ہوئے اور ان کے ساتھ ان کے اصحاب اور اہل اللہ میں سے بہت سے لوگ شہید ہوئے تھے۔‘‘ اس قول کو امام ابن جریر رحمہ اللہ نے بھی اختیار کیا ہے۔ (تفسیر الطبری : 155/4)\nاور دوسرا قول یہ بیان کیا گیا ہے کہ کتنے ہی نبیوں کے سامنے ان کے اصحاب اور اہل اللہ میں سے بہت سے لوگ شہید کیے گئے تھے۔’’سیرت ‘‘ میں امام ابن اسحاق رحمہ اللہ کا رجحان اس دوسرے قول کی طرف ہے، یعنی کتنے ہی نبیوں علیہم السلام نے اللہ تعالیٰ کے راستے میں اللہ تعالیٰ کے دشمنوں سے جہاد کیا اور ان کے ساتھ بہت سے اہل اللہ بھی جہاد میں شریک تھے لیکن وہ اپنے نبی علیہ السلام کے بعد کمزور نہ ہوئے، نہ انہوں نے اپنے دشمن کے مقابلے میں کسی دوں ہمتی کا ثبوت دیا اور نہ اللہ تعالیٰ کے راستے میں جہاد کرنے کی وجہ سے انہیں جو تکلیفیں پہنچیں ان کی وجہ سے وہ بزدل ہی ہوئے اور یہی صبر ہے۔\n﴿وَاللّٰهُ يُحِبُّ الصّٰبِرِيْنَ۰۰۱۴۶﴾ ’’اور اللہ تعالیٰ صبر کرنے والوں کو دوست رکھتا ہے۔ ‘‘(السیرۃ النبویۃ لابن ہشام : 118/3)گویا انہوں نے ﴿مَعَهٗ رِبِّيُّوْنَ كَثِيْرٌۚ﴾ کو حال بنایا ہے۔ اس قول کی سہیلی نے بھی خوب خوب تائید کی ہے۔ اور اسے ﴿فَمَا وَهَنُوْا لِمَاۤ اَصَابَهُمْ﴾ سے بھی تقویت حاصل ہوتی ہے۔ اموی نے بھی اپنی مغازی میں محمد بن ابراہیم رحمہ اللہ کی کتاب کے حوالے سے یہی بیان کیا ہے اور اس کے سوا کوئی دوسرا قول بیان ہی نہیں کیا۔\nامام سفیان ثوری رحمہ اللہ نے سیدنا ابن مسعود رضی اللہ عنہ کی روایت بیان کی ہے کہ ﴿رِبِّيُّوْنَ كَثِيْرٌۚ﴾ سے مراد ہے کہ کئی ہزار لوگوں نے لڑائی کی۔(تفسیر الطبری : 156/4) حضرت ابن عباس رضی اللہ عنہما، مجاہد، سعید بن جبیر، عکرمہ، حسن، قتادہ، سُدی، ربیع اور عطاء خراسانی رحمہم اللہ فرماتے ہیں کہ :﴿رِبِّيُّوْنَ﴾ کے معنی ہیں بہت سی جماعتیں۔(تفسیر ابن أبی حاتم : 780/3) امام عبدالرزاق رحمہ اللہ نے معمر رحمہ اللہ سے اور انہوں نے حسن سے روایت کیا ہے کہ ﴿رِبِّيُّوْنَ كَثِيْرٌۚ﴾ کے معنی ہیں بہت سے علماء۔ (تفسیر ابن أبی حاتم : 780/3 و تفسیر عبدالرزاق : 415/1، رقم : 467) نیز آپ رضی اللہ عنہ سے ایک روایت یہ بھی ہے کہ اس کے معنی ہیں ایسے علماء جو صبر کرنے والے اورابرار و اتقیاء ہوں۔ (تفسیر ابن أبی حاتم : 781/3)\n﴿فَاٰتٰىهُمُ اللّٰهُ ثَوَابَ الدُّنْيَا﴾ ’’تو اللہ تعالیٰ نے ان کو دنیامیں بھی بدلہ دیا۔‘‘ یعنی فتح و نصرت اور کامیابی سے سرفراز فرمایا۔﴿وَحُسْنَ ثَوَابِ الْاٰخِرَةِؕ﴾ یعنی دنیا کے بدلے کے ساتھ آخرت میں بھی اچھا بدلہ عطا فرمائے گا۔ ﴿وَاللّٰهُ يُحِبُّ الْمُحْسِنِيْنَࣖ۰۰۱۴۸﴾ ’’اور اللہ تعالیٰ نیکوکاروں کو دوست رکھتا ہے۔‘‘\nغزوات کے مورخین نے لکھا ہے کہ جب کچھ مسلمان میدان اُحد سے شکست کھا کر بھاگ پڑے تو عبداللہ بن قمیئہ رسول اللہ صلی اللہ علیہ وسلم کو قتل کرنے کی غرض سے آگےبڑھا، معصب بن عمیر رضی اللہ عنہ مسلمانوں کا جھنڈا لیے وہیں موجود تھے، انہوںنے آپ صلی اللہ علیہ وسلم کی طرف سے دفاع کرنا چاہا تو ابن قمیئہ نے انہیں قتل کر دیا، اور اسے گمان ہو گیا کہ اس نے رسول اللہ صلی اللہ علیہ وسلم کو قتل کر دیا اور کہنا شروع کر دیا کہ میں نے محمد صلی اللہ علیہ وسلم کو قتل کر دیا۔ شیطان بھی چیخ پڑا کہ محمد صلی اللہ علیہ وسلم کا قتل ہو گیا۔ جب بہت سے مسلمانوں کے کانوں میں یہ آواز پڑی تو جنگ کرنا بند کر دیا اور تھرا کر بیٹھ گئے۔ بعض نے کہا کہ کاش کوئی آدمی ہمارے لیے ابوسفیان سے امان مانگ لیتا۔ بعض منافقین نے کہا کہ اگر محمد صلی اللہ علیہ وسلم نبی ہوتا تو قتل نہ ہوتا۔\nاللہ تعالیٰ نے یہ آیت نازل فرما کر اس ذہنیت کی تردید کی اور کہا کہ محمد صلی اللہ علیہ وسلم تو ایک نبی ہیں۔ ان سے پہلے بھی اللہ کے بہت سے انبیاء و رسول گزر چکے ہیں تو کیا اگر وہ مر جائیں گے یا قتل کر دئیے جائیں گے تو تم لوگ اللہ کے دین سے پھر جائو گے؟ یاد رکھو کہ جو شخص دین اسلام سے صرف اس وجہ سے پھر جائے گا تو وہ صرف اپنے آپ کو نقصان پہنچائے گا، کیونکہ دین تو اللہ کا ہےاور عبادت اللہ کی کرنی ہے، وہ تو ہمیشہ سےزندہ ہے اور ہمیشہ زندہ رہے گا، کسی نبی یا رسول کی موت یا قتل سے اللہ کا دین دنیا سے اُٹھ نہیں جاتا، اسی لیے انس بن مالک رضی اللہ عنہ کے چچا (انس بن النضر رضی اللہ عنہ) نے جب صحابہ کا یہ حال دیکھا تو کہا کہ اے لوگو! اگر محمد صلی اللہ علیہ وسلم قتل کر دئیے گئے تو محمد صلی اللہ علیہ وسلم کا رب زندہ ہے، وہ کبھی نہیں مرے گا، اور تم رسول اللہ صلی اللہ علیہ وسلم کے بعد زندہ رہ کر کیا کرو گے، آئو جس مقصد کے لیے محمد نے جنگ کی، اسی کے لیے تم بھی جنگ کرو، اور جس کی خاطر محمد صلی اللہ علیہ وسلم نےجان دے دی، تم بھی جان دے دو، پھر کہا،اے اللہ! یہ لوگ جو کچھ کہہ رہے ہیں اس کے لیے معافی مانگتا ہوں اور اپنی براءت کا اظہار کرتا ہوں، پھر اپنی تلوار کھینچ کر جنگ کرنی شروع کر دی یہاں تک کہ قتل کر دئیے گئے۔ رضی اللہ عنہ\n(دیکھئے بخاری، کتاب الجہاد، باب : 12)\nامام ابن القیم رحمہ اللہ نے زاد المعاد میں لکھا ہے کہ ’’اس آیت کریمہ کا جو مضمون ہے اور اس میں جو سزا کا ذکر ہے، اس کی حقیقت رسول اللہ صلی اللہ علیہ وسلم کی وفات کے وقت کھل کر سامنے آئی کہ بہت سے منافقین اور ضعیف الایمان لوگ ایمان سے مرتد ہو گئے اور جو مخلص لوگ اسلام پر ثابت قدم رہے اللہ نے انہیں عزت دی اور فتح و نصرت سے نوازا‘‘ انتہی\nبخاری کی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی وفات کے دن ابوبکر صدیق رضی اللہ عنہ نے اسی آیت کی تلاوت کی اور ان کی تلاوت سن کر تمام صحابہ رضی اللہ عنہم نے تلاوت کرنی شروع کر دی اور عمر رضی اللہ عنہ تھرا کر بیٹھ گئے اور انہیں ایسا معلوم ہوا کہ جیسے یہ آیت آج ہی نازل ہوئی ہے۔"],[895,"§میدانِ اُحد کے معرکہ کے حالات\nجب سیدنا عبداللہ بن جبیر رضی اللہ عنہ کے ساتھی درہ چھوڑ کر لوٹ مار میں لگ گئے تو خالد بن ولید(جو اس وقت تک مسلمان نہیں ہوئے تھے اور کفار کے ایک دستہ کی کمان کر رہے تھے) پہاڑی کا چکر کاٹ کر اسی درہ سے مسلمانوں پر حملہ آور ہوئے۔ سوسوار ان کے ہمراہ تھے۔ ادھر سیدنا عبداللہ کے ساتھ صرف بارہ آدمی رہ گئے تھے۔ دس بارہ تیر انداز بھلا سوسواروں کی یلغار کو کیسے روک سکتے تھے۔ انھوں نے مقابلہ تو بڑی بے جگری سے کیا مگر سب شہید ہو گئے۔ مسلمان مجاہدین اپنے عقب یعنی درہ کی طرف سے مطمئن تھے کہ اچانک مشرکین کا یہ رسالہ ان کے سروں پر جا پہنچا اور سامنے سے مشرکوں کی جو فوج بھاگ کھڑی ہوئی تھی وہ بھی پیچھے پلٹ آئی اور مسلمان دونوں طرف سے گھر گئے۔بہت زور کارَن پڑا اور بہت سے مسلمان شہید اور زخمی ہوئے۔"],[896,"§عارضی شکست کا سبب اور رسول اللہ صلی اللہ علیہ وسلم کی وفات کی افواہ پر مسلمانوں کی بے قراری\nاسی دوران ابن قمیئہ نے ایک بھاری پتھر آپ صلی اللہ علیہ وسلم پر پھینکا جس سے آپ صلی اللہ علیہ وسلم کا سامنے کا دانت بھی ٹوٹ گیا اور چہرہ مبارک بھی زخمی ہوا۔ اس ضرب کی شدت سے آپ بے ہوش ہو کر گر پڑے اور ابن قمیئہ یا کسی اور نے دور سے پکارا ”محمد قتل کر دیے گئے“ یہ سنتے ہی مسلمانوں کے اوسان خطا ہو گئے اور پاؤں اُکھڑ گئے بعض مسلمان جنگ چھوڑ کر بیٹھ گئے اور کہنے لگے اب لڑنے کا کیا فائدہ ہے اور بعض کمزور دل مسلمانوں کو یہ خیال آیا کہ جا کر مشرکوں کے سردار ابو سفیان سے امان حاصل کر لیں اور اس بدحواسی کے عالم میں بعض یہ بھی سوچنے لگے کہ جب محمد صلی اللہ علیہ وسلم قتل ہو گئے تو ہمیں اپنے پہلے دین میں واپس چلے جانا چاہیے۔ یہی وہ وقت تھا جب منافقوں نے یوں زبان درازی شروع کر دی کہ محمد صلی اللہ علیہ وسلم اگر اللہ کے رسول ہوتے تو مارے نہ جاتے۔ اس وقت سیدنا انس بن مالک رضی اللہ عنہ کے چچا انس بن نضر رضی اللہ عنہ نے کہا اگر محمد قتل ہوگئے تو رب محمد صلی اللہ علیہ وسلم قتل نہیں ہوئے۔ آپ صلی اللہ علیہ وسلم کے بعد تمھارا زندہ رہنا کس کام کا؟ جس بات پر آپ صلی اللہ علیہ وسلم نے جان دی ہے اسی پر تم بھی اپنی جان دے دو اور کٹ مرو۔ یہ کہہ کر آپ کافروں میں گھس گئے اور بہادری کے جوہر دکھاتے ہوئے آخر شہید ہو گئے۔ اتنے میں رسول اللہ صلی اللہ علیہ وسلم کو ہوش آیا تو آپ صلی اللہ علیہ وسلم نے آواز دی :«⁠الى عباد الله انا رسول الله» ”اللہ کے بندو! ادھر آؤ میں اللہ کا رسول ہوں“ اور کعب بن مالک آپ کو پچان کر چلائے۔ مسلمانو! رسول اللہ صلی اللہ علیہ وسلم یہاں موجود ہیں۔ چنانچہ مسلمان آپ صلی اللہ علیہ وسلم کے گرد جمع ہونا شروع ہو گئے۔ تیس کے قریب صحابہ نے آپ صلی اللہ علیہ وسلم کے قریب ہو کر دفاع کیا اور مشرکوں کی فوج کو منتشر کر دیا۔ اس موقع پر سعد بن ابی وقاص رضی اللہ عنہ اور ابو طلحہ رضی اللہ عنہ نے نہایت جانبازی اور جانثاری کا نمونہ پیش کیا۔ اس موقع سے متعلق یہ آیت نازل ہوئی یعنی محمد آخر اللہ تونہیں جو حی و قیوم ہوں، ایک رسول ہی ہیں۔ ان سے پہلے سب رسول دنیا سے رخصت ہو چکے پھر اگر آپ صلی اللہ علیہ وسلم فوت ہو جائیں یا شہید ہو جائیں تو کیا تم اسلام چھوڑ دو گے؟ دین کی حفاظت اور جہاد فی سبیل اللہ ترک کر دو گے؟ تمھیں ہر گز ایسا نہیں کرنا چاہیے اور اگر کوئی ایسا کرے گا تو اپنا ہی نقصان کرے گا۔ اللہ کا تو کچھ بھی بگاڑ نہیں سکےگا۔"]])